// §207 Weekly problems email: BI problem detector summary once a week
// via portal_notify (insights kind). Defaults OFF. Connector tick +
// Settings card + test-send. Run from the website repo root (folder
// that contains OmniFlow-Control-Plane/).
// Expected clean: applied N already 0 warnings 0. Rerun: applied 0 already N warnings 0.
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
const BACKUP_TAG = ".pre_weekly_problems_207.bak";
let applied = 0, already = 0, warnings = 0;
if (!fs.existsSync("OmniFlow-Control-Plane") || !fs.statSync("OmniFlow-Control-Plane").isDirectory()) {
  console.log("X Run this from the website repo root (bot root) - the folder that contains OmniFlow-Control-Plane/. Nothing was written.");
  process.exit(1);
}
function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
      fs.unlinkSync(repoPath);
      console.log("X " + repoPath + " FAILED to compile - not written");
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("X " + repoPath + " FAILED to compile - old copy restored");
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
writeNewRepair("omniflow-backend-patch/portal_bi.py", "def materialize_weekly_problems", false,
    "\"\"\"Business Intelligence layer (MASTER-UPGRADE build-order 12): insights,\nproblem detector, AI quality and the journey funnel - deterministic mining\nover data the platform ALREADY collects. Zero LLM cost, no new write path.\n\n    GET /api/v1/portal/bi/report?days=7|30 ->\n        {days, generated_at, insights, ai_quality, funnel, problems}\n\n* insights   - what customers talk about (topic lexicon over the inbound\n               messages of the window, with the previous window for trend\n               and real example questions as evidence), sentiment /\n               purchase-intent / urgency mix (portal_intelligence), busy\n               hours, knowledge gaps, commerce signals (COD declines,\n               checkout conversion, delivery problems, overdue replies,\n               CSAT).\n* ai_quality - what the assistant did and how well: decisions send vs\n               handoff with reasons, average confidence, grounded / cited\n               share (portal_brain_traces), resolution rate (answered chats\n               that never needed a human), CSAT after AI answers, engine\n               failures + latency (portal_ai_usage), handoff trend\n               (portal_escalations), the questions it could not answer.\n* funnel     - the owner's journey stages (portal_memory): who is where\n               now, who reached each stage in the window, stage-to-stage\n               conversion, median time to move on, contacts stalled.\n* problems   - the Problem Detector: rules over the numbers above ->\n               Problem / Evidence / Impact / Confidence / Action, each with\n               a deep link. Thresholds default from env (OF_BI_*) and owners can\n               override them per workspace (client_settings.bi_thresholds);\n               busy hours use the business_hours timezone. Confidence\n               grows with sample size, nothing fires on thin data.\n\nEvery block runs behind a SAVEPOINT so one missing table blanks only that\nblock; samples are capped (OF_BI_SAMPLE_MAX / OF_BI_EVENTS_MAX) so a busy\nworkspace cannot make the page wait. Tenant-scoped; open to API keys\n(read-only).\n\"\"\"\n\nimport logging\nimport json\nimport os\nimport re\nimport statistics\nfrom datetime import datetime, timezone\nfrom typing import Any, Callable, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\n\nlogger = logging.getLogger(\"omniflow.portal-bi\")\n\nbp = Blueprint(\"portal_bi\", __name__, url_prefix=\"/api/v1/portal\")\n\nDEFAULT_DAYS = 7\nALLOWED_DAYS = (7, 30)\nSAMPLE_MAX = int(os.environ.get(\"OF_BI_SAMPLE_MAX\", \"3000\") or 3000)\nEVENTS_MAX = int(os.environ.get(\"OF_BI_EVENTS_MAX\", \"5000\") or 5000)\nGAPS_MAX = int(os.environ.get(\"OF_BI_GAPS_MAX\", \"200\") or 200)\nEXAMPLES = int(os.environ.get(\"OF_BI_EXAMPLES\", \"3\") or 3)\nTZ_OFFSET_HOURS = int(os.environ.get(\"OF_BI_TZ_OFFSET_HOURS\", \"5\") or 5)\nSTALL_DAYS = int(os.environ.get(\"OF_BI_STALL_DAYS\", \"7\") or 7)\nMAX_PROBLEMS = int(os.environ.get(\"OF_BI_MAX_PROBLEMS\", \"8\") or 8)\n\n\ndef _env_float(name: str, default: float) -> float:\n    try:\n        return float(os.environ.get(name, \"\") or default)\n    except Exception:\n        return default\n\n\n#: Problem-detector thresholds (share = 0..1, min = sample size).\nTHRESHOLDS: Dict[str, float] = {\n    \"gaps_min\": _env_float(\"OF_BI_GAPS_MIN\", 5),\n    \"topic_min\": _env_float(\"OF_BI_TOPIC_MIN\", 10),\n    \"delivery_share\": _env_float(\"OF_BI_DELIVERY_SHARE\", 0.25),\n    \"price_share\": _env_float(\"OF_BI_PRICE_SHARE\", 0.20),\n    \"trouble_share\": _env_float(\"OF_BI_TROUBLE_SHARE\", 0.15),\n    \"negative_share\": _env_float(\"OF_BI_NEGATIVE_SHARE\", 0.25),\n    \"sentiment_min\": _env_float(\"OF_BI_SENTIMENT_MIN\", 10),\n    \"handoff_share\": _env_float(\"OF_BI_HANDOFF_SHARE\", 0.30),\n    \"decisions_min\": _env_float(\"OF_BI_DECISIONS_MIN\", 10),\n    \"handoff_growth\": _env_float(\"OF_BI_HANDOFF_GROWTH\", 0.5),\n    \"handoff_min\": _env_float(\"OF_BI_HANDOFF_MIN\", 5),\n    \"policy_min\": _env_float(\"OF_BI_POLICY_MIN\", 3),\n    \"ai_fail_share\": _env_float(\"OF_BI_AI_FAIL_SHARE\", 0.20),\n    \"ai_calls_min\": _env_float(\"OF_BI_AI_CALLS_MIN\", 10),\n    \"cod_decline_share\": _env_float(\"OF_BI_COD_DECLINE_SHARE\", 0.30),\n    \"cod_min\": _env_float(\"OF_BI_COD_MIN\", 10),\n    \"checkout_conversion\": _env_float(\"OF_BI_CHECKOUT_CONVERSION\", 0.40),\n    \"checkout_min\": _env_float(\"OF_BI_CHECKOUT_MIN\", 10),\n    \"delivery_fail_share\": _env_float(\"OF_BI_DELIVERY_FAIL_SHARE\", 0.15),\n    \"bookings_min\": _env_float(\"OF_BI_BOOKINGS_MIN\", 10),\n    \"csat_low\": _env_float(\"OF_BI_CSAT_LOW\", 3.5),\n    \"csat_min\": _env_float(\"OF_BI_CSAT_MIN\", 5),\n    \"overdue_min\": _env_float(\"OF_BI_OVERDUE_MIN\", 5),\n    \"stall_share\": _env_float(\"OF_BI_STALL_SHARE\", 0.30),\n    \"stall_min\": _env_float(\"OF_BI_STALL_MIN\", 10),\n}\n\n#: Owner-editable knobs under client_settings.settings.bi_thresholds.\n#: Env OF_BI_* remains the default floor; blank keys fall back here.\nOWNER_THRESHOLD_KEYS = (\n    \"gaps_min\", \"topic_min\", \"delivery_share\", \"price_share\", \"trouble_share\",\n    \"negative_share\", \"sentiment_min\", \"handoff_share\", \"decisions_min\",\n    \"handoff_growth\", \"handoff_min\", \"policy_min\", \"ai_fail_share\",\n    \"ai_calls_min\", \"cod_decline_share\", \"cod_min\", \"checkout_conversion\",\n    \"checkout_min\", \"delivery_fail_share\", \"bookings_min\", \"csat_low\",\n    \"csat_min\", \"overdue_min\", \"stall_share\", \"stall_min\",\n)\nSHARE_KEYS = {\n    \"delivery_share\", \"price_share\", \"trouble_share\", \"negative_share\",\n    \"handoff_share\", \"ai_fail_share\", \"cod_decline_share\", \"checkout_conversion\",\n    \"delivery_fail_share\", \"stall_share\", \"handoff_growth\",\n}\nMIN_KEYS = {\n    \"gaps_min\", \"topic_min\", \"sentiment_min\", \"decisions_min\", \"handoff_min\",\n    \"policy_min\", \"ai_calls_min\", \"cod_min\", \"checkout_min\", \"bookings_min\",\n    \"csat_min\", \"overdue_min\", \"stall_min\",\n}\n\n\ndef _clamp_threshold(key: str, value: float) -> float:\n    if key in SHARE_KEYS:\n        return max(0.0, min(1.0, float(value)))\n    if key == \"csat_low\":\n        return max(1.0, min(5.0, float(value)))\n    if key in MIN_KEYS:\n        return max(1.0, min(1000.0, float(value)))\n    return float(value)\n\n\ndef default_thresholds() -> Dict[str, float]:\n    return {k: float(v) for k, v in THRESHOLDS.items()}\n\n\ndef thresholds_for(cur, client_id: int) -> Dict[str, float]:\n    \"\"\"Env defaults overlaid with owner-saved client_settings.bi_thresholds.\"\"\"\n    out = default_thresholds()\n    try:\n        cur.execute(\n            \"SELECT settings -> 'bi_thresholds' AS bi_thresholds FROM \"\n            + portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        stored = rows[0].get(\"bi_thresholds\") if rows and rows[0] else None\n        if isinstance(stored, str):\n            import json as _json\n            try:\n                stored = _json.loads(stored)\n            except Exception:\n                stored = None\n        if isinstance(stored, dict):\n            for key in OWNER_THRESHOLD_KEYS:\n                raw = stored.get(key)\n                if raw is None or isinstance(raw, bool):\n                    continue\n                try:\n                    out[key] = _clamp_threshold(key, float(raw))\n                except Exception:\n                    continue\n    except Exception as error:\n        logger.warning(\"bi thresholds load failed: %s\", error)\n    return out\n\n\ndef timezone_offset_hours(cur, client_id: int) -> int:\n    \"\"\"Workspace timezone from business_hours; env OF_BI_TZ_OFFSET_HOURS fallback.\"\"\"\n    name = None\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \"\n            + portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n        if isinstance(stored, str):\n            import json as _json\n            try:\n                stored = _json.loads(stored)\n            except Exception:\n                stored = None\n        if isinstance(stored, dict):\n            name = stored.get(\"timezone\")\n    except Exception as error:\n        logger.warning(\"bi timezone load failed: %s\", error)\n    if isinstance(name, str) and name.strip():\n        try:\n            from zoneinfo import ZoneInfo\n            from datetime import datetime as _dt\n            now = _dt.now(ZoneInfo(\"UTC\"))\n            local = now.astimezone(ZoneInfo(name.strip()))\n            offset = local.utcoffset()\n            if offset is not None:\n                return int(offset.total_seconds() // 3600)\n        except Exception:\n            pass\n    return TZ_OFFSET_HOURS\n\n\ndef _validate_thresholds(payload) -> tuple:\n    if not isinstance(payload, dict):\n        return None, \"bi_thresholds must be an object.\"\n    clean: Dict[str, float] = {}\n    for key, raw in payload.items():\n        if key not in OWNER_THRESHOLD_KEYS:\n            continue\n        if raw is None or isinstance(raw, bool):\n            return None, key + \" must be a number.\"\n        try:\n            clean[key] = _clamp_threshold(key, float(raw))\n        except Exception:\n            return None, key + \" must be a number.\"\n    return clean, None\n\n\n#: (key, label, keywords) - lower-cased substring / word matches over the\n#: customer's text; Roman-Urdu + English. A message may carry several.\nTOPICS: Tuple[Tuple[str, str, Tuple[str, ...]], ...] = (\n    (\"delivery_time\", \"Delivery time\", (\n        \"kab tak\", \"kitne din\", \"kitna time\", \"kab aayega\", \"kab ayega\",\n        \"kab milega\", \"kab pohnch\", \"kab pahunch\", \"delivery\", \"deliver\",\n        \"shipping\", \"courier\", \"tracking\", \"track\", \"dispatch\", \"arrive\",\n        \"pohanch\", \"pahunch\")),\n    (\"price\", \"Price & discounts\", (\n        \"price\", \"qeemat\", \"keemat\", \"kitne ka\", \"kitne ki\", \"kitna hai\",\n        \"rate\", \"mehnga\", \"mehngi\", \"sasta\", \"sasti\", \"discount\", \"kam karo\",\n        \"kam kar\", \"offer\", \"deal\", \"cheap\", \"expensive\", \"final price\")),\n    (\"availability\", \"Availability & sizes\", (\n        \"available\", \"availab\", \"stock\", \"mil jayega\", \"mil jaye ga\",\n        \"milega\", \"hai kya\", \"size\", \"colour\", \"color\", \"variant\", \"restock\",\n        \"out of stock\", \"khatam\")),\n    (\"payment\", \"Payment & COD\", (\n        \"payment\", \"jazzcash\", \"easypaisa\", \"bank\", \"advance\", \"cod\",\n        \"cash on delivery\", \"paisay\", \"paise\", \"transfer\", \"card\", \"pay \")),\n    (\"returns\", \"Returns & refunds\", (\n        \"return\", \"wapas\", \"wapis\", \"exchange\", \"refund\", \"replace\",\n        \"kharab\", \"defect\", \"damage\", \"tuta\", \"toota\", \"galat\", \"wrong item\")),\n    (\"complaint\", \"Complaints\", (\n        \"complaint\", \"shikayat\", \"bakwas\", \"ghatiya\", \"late\", \"abhi tak nahi\",\n        \"nahi aya\", \"nahi aaya\", \"nahi mila\", \"fraud\", \"dhoka\", \"cheat\",\n        \"worst\", \"bura\", \"not received\", \"no response\", \"koi jawab\")),\n    (\"order_status\", \"Order status\", (\n        \"order\", \"status\", \"confirm\", \"booking\", \"book kar\", \"receipt\",\n        \"invoice\", \"order number\", \"order no\")),\n    (\"hours_location\", \"Hours & location\", (\n        \"timing\", \"open hai\", \"kab tak open\", \"kab khulta\", \"address\",\n        \"location\", \"kahan hai\", \"kahan par\", \"shop kahan\", \"branch\",\n        \"map\", \"directions\", \"closed\")),\n)\nTOPIC_LABELS = {key: label for key, label, _kw in TOPICS}\n_WORD_RE = re.compile(r\"[a-z]+\")\n\n\ndef topics_for(text: str) -> List[str]:\n    \"\"\"Topic keys present in one customer text (deterministic lexicon).\"\"\"\n    lowered = \" \" + re.sub(r\"\\s+\", \" \", str(text or \"\").lower()) + \" \"\n    words = set(_WORD_RE.findall(lowered))\n    found: List[str] = []\n    for key, _label, keywords in TOPICS:\n        for keyword in keywords:\n            if \" \" in keyword.strip() or keyword.endswith(\" \"):\n                hit = keyword in lowered\n            elif len(keyword) <= 4:\n                hit = keyword in words\n            else:\n                hit = keyword in lowered\n            if hit:\n                found.append(key)\n                break\n    return found\n\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except Exception:\n        days = DEFAULT_DAYS\n    return days if days in ALLOWED_DAYS else DEFAULT_DAYS\n\n\ndef _share(part: int, whole: int) -> float:\n    return round(part / whole, 3) if whole else 0.0\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    return value.isoformat() if hasattr(value, \"isoformat\") else str(value)\n\n\ndef _snippet(text: Any, limit: int = 120) -> str:\n    text = re.sub(r\"\\s+\", \" \", str(text or \"\")).strip()\n    return text[:limit] + (\"\\u2026\" if len(text) > limit else \"\")\n\n\ndef _guarded(cur, label: str, fn: Callable[[], Any]):\n    \"\"\"Run one block behind a SAVEPOINT; None when it fails (a missing\n    table must blank only its block, never the whole report).\"\"\"\n    try:\n        cur.execute(\"SAVEPOINT of_bi\")\n        value = fn()\n        cur.execute(\"RELEASE SAVEPOINT of_bi\")\n        return value\n    except Exception as error:\n        logger.warning(\"bi %s failed: %s\", label, error)\n        try:\n            cur.execute(\"ROLLBACK TO SAVEPOINT of_bi\")\n        except Exception:\n            pass\n        return None\n\n\n# ---------------------------------------------------------------------------\n# insights\n# ---------------------------------------------------------------------------\n\ndef _sample_messages(cur, client_id: int, days: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT conversation_id, body, created_at,\"\n        \" (created_at > NOW() - make_interval(days => %s)) AS current\"\n        \" FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n        \" WHERE client_id = %s AND direction = 'in'\"\n        \" AND created_at > NOW() - make_interval(days => %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (days, client_id, days * 2, SAMPLE_MAX),\n    )\n    return portal_db.rows(cur)\n\n\ndef topic_insights(messages: List[Dict[str, Any]],\n                  tz_offset_hours: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"Pure: topic shares for the current window, the previous window's\n    share for trend, example questions, busy hours.\"\"\"\n    offset = TZ_OFFSET_HOURS if tz_offset_hours is None else int(tz_offset_hours)\n    current = [m for m in messages if m.get(\"current\")]\n    previous = [m for m in messages if not m.get(\"current\")]\n    counts: Dict[str, int] = {}\n    prev_counts: Dict[str, int] = {}\n    examples: Dict[str, List[str]] = {}\n    conversations: Dict[str, set] = {}\n    hours: Dict[int, int] = {}\n    for message in current:\n        keys = topics_for(message.get(\"body\"))\n        for key in keys:\n            counts[key] = counts.get(key, 0) + 1\n            conversations.setdefault(key, set()).add(message.get(\"conversation_id\"))\n            bucket = examples.setdefault(key, [])\n            if len(bucket) < EXAMPLES:\n                snippet = _snippet(message.get(\"body\"))\n                if snippet and snippet not in bucket:\n                    bucket.append(snippet)\n        when = message.get(\"created_at\")\n        if hasattr(when, \"hour\"):\n            hours[(when.hour + offset) % 24] = hours.get(\n                (when.hour + offset) % 24, 0) + 1\n    for message in previous:\n        for key in topics_for(message.get(\"body\")):\n            prev_counts[key] = prev_counts.get(key, 0) + 1\n    total, prev_total = len(current), len(previous)\n    topics = []\n    for key, label, _kw in TOPICS:\n        count = counts.get(key, 0)\n        share = _share(count, total)\n        prev_share = _share(prev_counts.get(key, 0), prev_total)\n        trend = \"flat\"\n        if prev_total and total:\n            if share >= prev_share + 0.05:\n                trend = \"up\"\n            elif share <= prev_share - 0.05:\n                trend = \"down\"\n        elif total and count and not prev_total:\n            trend = \"new\"\n        topics.append({\"key\": key, \"label\": label, \"count\": count,\n                       \"share\": share, \"prev_share\": prev_share,\n                       \"trend\": trend,\n                       \"conversations\": len(conversations.get(key, ())),\n                       \"examples\": examples.get(key, [])})\n    topics.sort(key=lambda t: (-t[\"count\"], t[\"key\"]))\n    busy = sorted(hours.items(), key=lambda item: (-item[1], item[0]))[:3]\n    return {\n        \"messages\": total,\n        \"previous_messages\": prev_total,\n        \"conversations\": len({m.get(\"conversation_id\") for m in current}),\n        \"topics\": topics,\n        \"busy_hours\": [{\"hour\": hour, \"messages\": n} for hour, n in busy],\n        \"tz_offset_hours\": offset,\n    }\n\n\ndef _intelligence_mix(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_intelligence\n\n    cur.execute(\n        \"SELECT sentiment, purchase_intent, urgency, language, COUNT(*) AS n\"\n        \" FROM \" + portal_db._q(portal_intelligence.TABLE) +\n        \" WHERE client_id = %s AND updated_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY sentiment, purchase_intent, urgency, language\",\n        (client_id, days),\n    )\n    out: Dict[str, Any] = {\"conversations\": 0, \"sentiment\": {},\n                           \"purchase_intent\": {}, \"urgency\": {}, \"language\": {}}\n    for row in portal_db.rows(cur):\n        n = int(row.get(\"n\") or 0)\n        out[\"conversations\"] += n\n        for field in (\"sentiment\", \"purchase_intent\", \"urgency\", \"language\"):\n            key = str(row.get(field) or \"unknown\")\n            out[field][key] = out[field].get(key, 0) + n\n    total = out[\"conversations\"]\n    out[\"negative_share\"] = _share(out[\"sentiment\"].get(\"negative\", 0), total)\n    out[\"high_purchase_share\"] = _share(out[\"purchase_intent\"].get(\"high\", 0), total)\n    out[\"urgent_share\"] = _share(out[\"urgency\"].get(\"high\", 0), total)\n    return out\n\n\ndef _gaps(cur, client_id: int, days: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT question, intent, resolved, created_at FROM \" +\n        portal_db._q(portal_db.GAPS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, days, GAPS_MAX),\n    )\n    rows = portal_db.rows(cur)\n    topic_counts: Dict[str, int] = {}\n    examples: List[str] = []\n    unresolved = 0\n    for row in rows:\n        if not int(row.get(\"resolved\") or 0):\n            unresolved += 1\n        for key in topics_for(row.get(\"question\")):\n            topic_counts[key] = topic_counts.get(key, 0) + 1\n        snippet = _snippet(row.get(\"question\"), 100)\n        if snippet and len(examples) < 5 and snippet not in examples:\n            examples.append(snippet)\n    top = sorted(topic_counts.items(), key=lambda i: (-i[1], i[0]))[:3]\n    return {\"count\": len(rows), \"unresolved\": unresolved,\n            \"top_topics\": [{\"key\": k, \"label\": TOPIC_LABELS.get(k, k), \"count\": n}\n                           for k, n in top],\n            \"examples\": examples}\n\n\ndef _commerce(cur, client_id: int, days: int) -> Dict[str, Any]:\n    out: Dict[str, Any] = {}\n    cur.execute(\n        \"SELECT action, COUNT(*) AS n FROM \" + portal_db._q(\"portal_action_log\") +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" AND action IN ('cod.confirmed', 'cod.declined', 'negotiation.round',\"\n        \" 'checkout.created', 'ai.answer', 'kb.auto_reply')\"\n        \" GROUP BY action\",\n        (client_id, days),\n    )\n    actions = {str(r.get(\"action\")): int(r.get(\"n\") or 0) for r in portal_db.rows(cur)}\n    confirmed = actions.get(\"cod.confirmed\", 0)\n    declined = actions.get(\"cod.declined\", 0)\n    out[\"cod\"] = {\"confirmed\": confirmed, \"declined\": declined,\n                  \"decline_share\": _share(declined, confirmed + declined)}\n    out[\"negotiation_rounds\"] = actions.get(\"negotiation.round\", 0)\n    out[\"auto_answers\"] = actions.get(\"ai.answer\", 0) + actions.get(\"kb.auto_reply\", 0)\n    return out\n\n\ndef _checkout(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_checkout\n\n    cur.execute(\n        \"SELECT COUNT(*) AS created,\"\n        \" COUNT(*) FILTER (WHERE status IN ('paid', 'shipped', 'delivered')) AS paid\"\n        \" FROM \" + portal_db._q(portal_checkout.LINKS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    created = int((rows[0] if rows else {}).get(\"created\") or 0)\n    paid = int((rows[0] if rows else {}).get(\"paid\") or 0)\n    return {\"created\": created, \"paid\": paid, \"conversion\": _share(paid, created)}\n\n\ndef _deliveries(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_courier\n\n    cur.execute(\n        \"SELECT status, COUNT(*) AS n FROM \" + portal_db._q(portal_courier.BOOKINGS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY status\",\n        (client_id, days),\n    )\n    by_status: Dict[str, int] = {}\n    total = problems = 0\n    for row in portal_db.rows(cur):\n        status = str(row.get(\"status\") or \"unknown\").lower()\n        n = int(row.get(\"n\") or 0)\n        by_status[status] = n\n        total += n\n        if any(word in status for word in (\"fail\", \"return\", \"cancel\", \"lost\", \"refus\")):\n            problems += n\n    return {\"bookings\": total, \"problem_bookings\": problems,\n            \"problem_share\": _share(problems, total), \"by_status\": by_status}\n\n\ndef _service(cur, client_id: int, days: int) -> Dict[str, Any]:\n    try:\n        import portal_conversations\n\n        overdue_hours = int(getattr(portal_conversations, \"OVERDUE_HOURS\", 4))\n    except Exception:\n        overdue_hours = 4\n    msgs = portal_db._q(portal_db.MSGS_TABLE)\n    cur.execute(\n        \"SELECT COUNT(*) AS n FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n        \" WHERE c.client_id = %s AND c.status = 'open'\"\n        \" AND EXISTS (SELECT 1 FROM \" + msgs + \" nr\"\n        \" WHERE nr.conversation_id = c.id GROUP BY nr.conversation_id\"\n        \" HAVING COALESCE(MAX(CASE WHEN nr.direction = 'in' THEN nr.id END), 0)\"\n        \" > COALESCE(MAX(CASE WHEN nr.direction = 'out' THEN nr.id END), 0)\"\n        \" AND MAX(CASE WHEN nr.direction = 'in' THEN nr.created_at END)\"\n        \" < NOW() - make_interval(hours => %s))\",\n        (client_id, overdue_hours),\n    )\n    rows = portal_db.rows(cur)\n    overdue = int((rows[0] if rows else {}).get(\"n\") or 0)\n    cur.execute(\n        \"SELECT AVG(score) AS avg_score, COUNT(*) AS n FROM \" +\n        portal_db._q(portal_db.CSAT_TABLE) +\n        \" WHERE client_id = %s AND score IS NOT NULL\"\n        \" AND answered_at > NOW() - make_interval(days => %s)\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    avg = (rows[0] if rows else {}).get(\"avg_score\")\n    return {\"overdue_replies\": overdue, \"overdue_hours\": overdue_hours,\n            \"csat_avg\": round(float(avg), 2) if avg is not None else None,\n            \"csat_answers\": int((rows[0] if rows else {}).get(\"n\") or 0)}\n\n\ndef insights(cur, client_id: int, days: int) -> Dict[str, Any]:\n    \"\"\"Customer-side picture for the window (each block fail-soft).\"\"\"\n    days = _days(days)\n    tz_off = timezone_offset_hours(cur, client_id)\n    topics = _guarded(cur, \"topics\", lambda: topic_insights(\n        _sample_messages(cur, client_id, days), tz_off))\n    return {\n        \"days\": days,\n        \"timezone_offset_hours\": tz_off,\n        \"topics\": topics,\n        \"mix\": _guarded(cur, \"intelligence\", lambda: _intelligence_mix(cur, client_id, days)),\n        \"gaps\": _guarded(cur, \"gaps\", lambda: _gaps(cur, client_id, days)),\n        \"commerce\": _guarded(cur, \"commerce\", lambda: _commerce(cur, client_id, days)),\n        \"checkout\": _guarded(cur, \"checkout\", lambda: _checkout(cur, client_id, days)),\n        \"deliveries\": _guarded(cur, \"deliveries\", lambda: _deliveries(cur, client_id, days)),\n        \"service\": _guarded(cur, \"service\", lambda: _service(cur, client_id, days)),\n    }\n\n\n# ---------------------------------------------------------------------------\n# AI quality\n# ---------------------------------------------------------------------------\n\ndef _traces(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_brain\n\n    traces = portal_db._q(portal_brain.TRACES_TABLE)\n    cur.execute(\n        \"SELECT kind, decision, COALESCE(grounding->>'reason', '') AS reason,\"\n        \" COUNT(*) AS n,\"\n        \" AVG(NULLIF(grounding->>'confidence', '')::numeric) AS avg_confidence,\"\n        \" COUNT(*) FILTER (WHERE\"\n        \" jsonb_array_length(COALESCE(grounding->'kb_ids', '[]'::jsonb)) > 0\"\n        \" OR jsonb_array_length(COALESCE(grounding->'knowledge_ids', '[]'::jsonb)) > 0\"\n        \" OR jsonb_array_length(COALESCE(grounding->'fact_ids', '[]'::jsonb)) > 0)\"\n        \" AS grounded,\"\n        \" COUNT(*) FILTER (WHERE\"\n        \" jsonb_array_length(COALESCE(grounding->'citations', '[]'::jsonb)) > 0)\"\n        \" AS cited\"\n        \" FROM \" + traces +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY kind, decision, reason\",\n        (client_id, days),\n    )\n    groups = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT DATE(created_at) AS day, decision, COUNT(*) AS n FROM \" + traces +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY DATE(created_at), decision ORDER BY day\",\n        (client_id, days),\n    )\n    daily = portal_db.rows(cur)\n    return summarize_traces(groups, daily)\n\n\ndef summarize_traces(groups: List[Dict[str, Any]], daily: List[Dict[str, Any]]) -> Dict[str, Any]:\n    \"\"\"Pure: decisions / handoff share / reasons / confidence / grounding.\"\"\"\n    total = sends = handoffs = grounded = cited = 0\n    answers = drafts = 0\n    reasons: Dict[str, int] = {}\n    conf_weight = 0.0\n    conf_n = 0\n    for row in groups:\n        n = int(row.get(\"n\") or 0)\n        total += n\n        if str(row.get(\"kind\") or \"\") == \"ingest_answer\":\n            answers += n\n        else:\n            drafts += n\n        if str(row.get(\"decision\") or \"\") == \"send\":\n            sends += n\n        else:\n            handoffs += n\n            reason = str(row.get(\"reason\") or \"unknown\")\n            if reason.startswith(\"policy:\"):\n                reason = \"policy\"\n            reasons[reason] = reasons.get(reason, 0) + n\n        grounded += int(row.get(\"grounded\") or 0)\n        cited += int(row.get(\"cited\") or 0)\n        avg = row.get(\"avg_confidence\")\n        if avg is not None:\n            conf_weight += float(avg) * n\n            conf_n += n\n    by_day: Dict[str, Dict[str, int]] = {}\n    for row in daily:\n        day = row.get(\"day\")\n        key = day.isoformat() if hasattr(day, \"isoformat\") else str(day)\n        entry = by_day.setdefault(key, {\"send\": 0, \"handoff\": 0})\n        if str(row.get(\"decision\") or \"\") == \"send\":\n            entry[\"send\"] += int(row.get(\"n\") or 0)\n        else:\n            entry[\"handoff\"] += int(row.get(\"n\") or 0)\n    return {\n        \"decisions\": total,\n        \"auto_answers\": answers,\n        \"drafts\": drafts,\n        \"sends\": sends,\n        \"handoffs\": handoffs,\n        \"handoff_share\": _share(handoffs, total),\n        \"reasons\": reasons,\n        \"policy_blocks\": reasons.get(\"policy\", 0),\n        \"llm_unavailable\": reasons.get(\"llm_unavailable\", 0),\n        \"avg_confidence\": round(conf_weight / conf_n, 3) if conf_n else None,\n        \"grounded_share\": _share(grounded, total),\n        \"cited_share\": _share(cited, total),\n        \"by_day\": [{\"day\": day, **entry} for day, entry in sorted(by_day.items())],\n    }\n\n\ndef _resolution(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_escalation\n\n    cur.execute(\n        \"SELECT COUNT(DISTINCT a.conversation_id) AS answered,\"\n        \" COUNT(DISTINCT CASE WHEN e.id IS NOT NULL THEN a.conversation_id END)\"\n        \" AS escalated\"\n        \" FROM \" + portal_db._q(\"portal_action_log\") + \" a\"\n        \" LEFT JOIN \" + portal_db._q(portal_escalation.TABLE) + \" e\"\n        \" ON e.client_id = a.client_id AND e.conversation_id = a.conversation_id\"\n        \" AND e.created_at >= a.created_at\"\n        \" WHERE a.client_id = %s AND a.action = 'ai.answer'\"\n        \" AND a.created_at > NOW() - make_interval(days => %s)\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    answered = int((rows[0] if rows else {}).get(\"answered\") or 0)\n    escalated = int((rows[0] if rows else {}).get(\"escalated\") or 0)\n    cur.execute(\n        \"SELECT AVG(s.score) AS avg_score, COUNT(*) AS n FROM \" +\n        portal_db._q(portal_db.CSAT_TABLE) + \" s\"\n        \" WHERE s.client_id = %s AND s.score IS NOT NULL\"\n        \" AND s.answered_at > NOW() - make_interval(days => %s)\"\n        \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(\"portal_action_log\") + \" a\"\n        \" WHERE a.client_id = s.client_id AND a.conversation_id = s.conversation_id\"\n        \" AND a.action = 'ai.answer')\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    avg = (rows[0] if rows else {}).get(\"avg_score\")\n    return {\"answered_conversations\": answered, \"escalated_after\": escalated,\n            \"resolved_share\": _share(answered - escalated, answered),\n            \"csat_after_ai\": round(float(avg), 2) if avg is not None else None,\n            \"csat_after_ai_n\": int((rows[0] if rows else {}).get(\"n\") or 0)}\n\n\ndef _handoffs(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_escalation\n\n    table = portal_db._q(portal_escalation.TABLE)\n    cur.execute(\n        \"SELECT COUNT(*) FILTER (WHERE created_at > NOW() - make_interval(days => %s))\"\n        \" AS current,\"\n        \" COUNT(*) FILTER (WHERE created_at <= NOW() - make_interval(days => %s)\"\n        \" AND created_at > NOW() - make_interval(days => %s)) AS previous,\"\n        \" COUNT(*) FILTER (WHERE status = 'open') AS open_now,\"\n        \" COUNT(*) FILTER (WHERE status = 'open' AND target_user_id IS NULL)\"\n        \" AS open_unassigned,\"\n        \" AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)))\"\n        \" FILTER (WHERE resolved_at > NOW() - make_interval(days => %s))\"\n        \" AS avg_resolve_seconds\"\n        \" FROM \" + table + \" WHERE client_id = %s\",\n        (days, days, days * 2, days, client_id),\n    )\n    rows = portal_db.rows(cur)\n    totals = rows[0] if rows else {}\n    cur.execute(\n        \"SELECT source, reason, COUNT(*) AS n FROM \" + table +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY source, reason ORDER BY n DESC LIMIT 20\",\n        (client_id, days),\n    )\n    by_source: Dict[str, int] = {}\n    reasons: List[Dict[str, Any]] = []\n    for row in portal_db.rows(cur):\n        n = int(row.get(\"n\") or 0)\n        source = str(row.get(\"source\") or \"system\")\n        by_source[source] = by_source.get(source, 0) + n\n        reasons.append({\"label\": portal_escalation.reason_label(row.get(\"reason\")),\n                        \"source\": source, \"count\": n})\n    current = int(totals.get(\"current\") or 0)\n    previous = int(totals.get(\"previous\") or 0)\n    avg = totals.get(\"avg_resolve_seconds\")\n    growth = None\n    if previous:\n        growth = round((current - previous) / previous, 2)\n    return {\"current\": current, \"previous\": previous, \"growth\": growth,\n            \"open\": int(totals.get(\"open_now\") or 0),\n            \"open_unassigned\": int(totals.get(\"open_unassigned\") or 0),\n            \"avg_resolve_minutes\": (round(float(avg) / 60.0, 1)\n                                    if avg is not None else None),\n            \"by_source\": by_source, \"reasons\": reasons[:5]}\n\n\ndef ai_quality(cur, client_id: int, days: int,\n               gaps: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n    days = _days(days)\n\n    def _usage():\n        import portal_ai_usage\n\n        portal_ai_usage._ensure_ddl(cur)\n        report = portal_ai_usage.usage_report(cur, client_id, days)\n        totals = report[\"totals\"]\n        return {\"calls\": totals[\"calls\"], \"failed\": totals[\"failed\"],\n                \"failed_share\": _share(totals[\"failed\"], totals[\"calls\"]),\n                \"avg_latency_ms\": totals[\"avg_latency_ms\"],\n                \"cost_usd\": totals[\"cost_usd\"], \"priced\": totals[\"priced\"]}\n\n    out = {\n        \"days\": days,\n        \"traces\": _guarded(cur, \"traces\", lambda: _traces(cur, client_id, days)),\n        \"resolution\": _guarded(cur, \"resolution\", lambda: _resolution(cur, client_id, days)),\n        \"handoffs\": _guarded(cur, \"handoffs\", lambda: _handoffs(cur, client_id, days)),\n        \"usage\": _guarded(cur, \"usage\", _usage),\n    }\n    if gaps is None:\n        gaps = _guarded(cur, \"gaps\", lambda: _gaps(cur, client_id, days))\n    out[\"unanswered\"] = {\"count\": (gaps or {}).get(\"count\", 0),\n                         \"examples\": (gaps or {}).get(\"examples\", [])}\n    return out\n\n\n# ---------------------------------------------------------------------------\n# journey funnel\n# ---------------------------------------------------------------------------\n\ndef _funnel_rows(cur, client_id: int, days: int) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]]]:\n    import portal_memory\n\n    cur.execute(\n        \"SELECT id, name, position FROM \" + portal_db._q(portal_memory.STAGES_TABLE) +\n        \" WHERE client_id = %s AND is_active = TRUE ORDER BY position, id\",\n        (client_id,),\n    )\n    stages = portal_db.rows(cur)\n    if not stages:\n        return [], [], []\n    cur.execute(\n        \"SELECT stage_id, COUNT(*) AS n FROM \" + portal_db._q(portal_memory.STATE_TABLE) +\n        \" WHERE client_id = %s GROUP BY stage_id\",\n        (client_id,),\n    )\n    state = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT contact_id, stage_name, created_at FROM \" +\n        portal_db._q(portal_memory.EVENTS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" ORDER BY contact_id, id LIMIT %s\",\n        (client_id, days * 2, EVENTS_MAX),\n    )\n    events = portal_db.rows(cur)\n    return stages, state, events\n\n\ndef build_funnel(stages: List[Dict[str, Any]], state: List[Dict[str, Any]],\n                 events: List[Dict[str, Any]], days: int,\n                 now: Optional[datetime] = None) -> Dict[str, Any]:\n    \"\"\"Pure: current distribution, reached-in-window, conversion between\n    consecutive stages, median hours to move on, stalled contacts.\"\"\"\n    now = now or datetime.now(timezone.utc)\n    order = [str(s.get(\"name\")) for s in stages]\n    position = {name: index for index, name in enumerate(order)}\n    by_id = {int(s.get(\"id\") or 0): str(s.get(\"name\")) for s in stages}\n    current: Dict[str, int] = {name: 0 for name in order}\n    for row in state:\n        name = by_id.get(int(row.get(\"stage_id\") or 0))\n        if name is not None:\n            current[name] += int(row.get(\"n\") or 0)\n    window_start = now.timestamp() - days * 86400\n    reached: Dict[str, set] = {name: set() for name in order}\n    durations: Dict[str, List[float]] = {name: [] for name in order}\n    last_event: Dict[str, Tuple[str, float]] = {}\n    per_contact: Dict[str, List[Tuple[str, float]]] = {}\n    for row in events:\n        name = str(row.get(\"stage_name\") or \"\")\n        if name not in position:\n            continue\n        when = row.get(\"created_at\")\n        stamp = when.timestamp() if hasattr(when, \"timestamp\") else 0.0\n        contact = str(row.get(\"contact_id\") or \"\")\n        per_contact.setdefault(contact, []).append((name, stamp))\n    for contact, moves in per_contact.items():\n        for index, (name, stamp) in enumerate(moves):\n            if stamp >= window_start:\n                reached[name].add(contact)\n            if index + 1 < len(moves):\n                next_name, next_stamp = moves[index + 1]\n                if position[next_name] > position[name] and next_stamp >= stamp:\n                    durations[name].append((next_stamp - stamp) / 3600.0)\n        last_event[contact] = moves[-1]\n    stalled: Dict[str, int] = {name: 0 for name in order}\n    stall_seconds = STALL_DAYS * 86400\n    for contact, (name, stamp) in last_event.items():\n        if position[name] < len(order) - 1 and now.timestamp() - stamp > stall_seconds:\n            stalled[name] += 1\n    out_stages = []\n    for index, name in enumerate(order):\n        reached_n = len(reached[name])\n        prev_reached = len(reached[order[index - 1]]) if index else None\n        conversion = (_share(reached_n, prev_reached) if prev_reached else None)\n        median = (round(statistics.median(durations[name]), 1)\n                  if durations[name] else None)\n        out_stages.append({\n            \"name\": name, \"position\": index, \"current\": current[name],\n            \"reached\": reached_n, \"conversion_from_previous\": conversion,\n            \"median_hours_to_next\": median, \"stalled\": stalled[name],\n        })\n    first = len(reached[order[0]]) if order else 0\n    last = len(reached[order[-1]]) if order else 0\n    total_contacts = sum(current.values())\n    total_stalled = sum(stalled.values())\n    return {\n        \"configured\": bool(order),\n        \"days\": days,\n        \"stages\": out_stages,\n        \"contacts\": total_contacts,\n        \"reached_first\": first,\n        \"reached_last\": last,\n        \"overall_conversion\": _share(last, first) if first else None,\n        \"stalled\": total_stalled,\n        \"stalled_share\": _share(total_stalled, len(last_event)) if last_event else 0.0,\n        \"stall_days\": STALL_DAYS,\n        \"events\": len(events),\n    }\n\n\ndef funnel(cur, client_id: int, days: int) -> Dict[str, Any]:\n    days = _days(days)\n    stages, state, events = _funnel_rows(cur, client_id, days)\n    return build_funnel(stages, state, events, days)\n\n\n# ---------------------------------------------------------------------------\n# problem detector\n# ---------------------------------------------------------------------------\n\ndef _confidence(n: float, minimum: float) -> float:\n    \"\"\"Grows with the sample: minimum -> 0.55, 4x minimum -> 0.95.\"\"\"\n    if minimum <= 0:\n        return 0.95\n    return round(min(0.95, 0.4 + 0.6 * min(1.0, n / (4.0 * minimum))), 2)\n\n\ndef _severity(value: float, threshold: float, factor: float = 2.0) -> str:\n    return \"critical\" if threshold and value >= threshold * factor else \"warn\"\n\n\ndef _pct(share: Any) -> str:\n    try:\n        return str(int(round(float(share or 0) * 100))) + \"%\"\n    except Exception:\n        return \"0%\"\n\n\ndef detect_problems(ins: Optional[Dict[str, Any]], quality: Optional[Dict[str, Any]],\n                    fun: Optional[Dict[str, Any]], days: int,\n                    thresholds: Optional[Dict[str, float]] = None) -> List[Dict[str, Any]]:\n    \"\"\"Pure rules -> Problem / Evidence / Impact / Confidence / Action.\"\"\"\n    T = thresholds if isinstance(thresholds, dict) and thresholds else THRESHOLDS\n    ins = ins or {}\n    quality = quality or {}\n    fun = fun or {}\n    problems: List[Dict[str, Any]] = []\n\n    def add(key, title, severity, evidence, impact, confidence, action_label, href):\n        problems.append({\"key\": key, \"title\": title, \"severity\": severity,\n                         \"evidence\": evidence, \"impact\": impact,\n                         \"confidence\": confidence,\n                         \"action\": {\"label\": action_label, \"href\": href}})\n\n    topics = ins.get(\"topics\") or {}\n    by_topic = {t[\"key\"]: t for t in (topics.get(\"topics\") or [])}\n    sample = int(topics.get(\"messages\") or 0)\n\n    gaps = ins.get(\"gaps\") or {}\n    if gaps.get(\"count\", 0) >= T[\"gaps_min\"]:\n        top = gaps.get(\"top_topics\") or []\n        add(\"knowledge_gaps\",\n            \"Customers keep asking things the assistant cannot answer\",\n            _severity(gaps[\"count\"], T[\"gaps_min\"], 3),\n            {\"unanswered_questions\": gaps[\"count\"],\n             \"top_topic\": top[0][\"label\"] if top else None,\n             \"examples\": gaps.get(\"examples\", [])[:EXAMPLES]},\n            str(gaps[\"count\"]) + \" questions in \" + str(days)\n            + \" days waited for a person (\" + str(gaps.get(\"unresolved\", 0))\n            + \" still unresolved).\",\n            _confidence(gaps[\"count\"], T[\"gaps_min\"]),\n            \"Add these answers to the Knowledge base\", \"/dashboard/knowledge-base\")\n\n    delivery = by_topic.get(\"delivery_time\")\n    if delivery and delivery[\"count\"] >= T[\"topic_min\"] \\\n            and delivery[\"share\"] >= T[\"delivery_share\"]:\n        add(\"delivery_questions\",\n            _pct(delivery[\"share\"]) + \" of customer messages ask about delivery time\",\n            _severity(delivery[\"share\"], T[\"delivery_share\"]),\n            {\"messages\": delivery[\"count\"], \"share\": delivery[\"share\"],\n             \"trend\": delivery[\"trend\"], \"examples\": delivery[\"examples\"]},\n            \"Publishing your delivery policy lets the assistant answer these \"\n            \"instantly instead of your team.\",\n            _confidence(sample, T[\"topic_min\"]),\n            \"Publish a delivery policy source\", \"/dashboard/knowledge-base\")\n\n    price = by_topic.get(\"price\")\n    if price and price[\"count\"] >= T[\"topic_min\"] and price[\"share\"] >= T[\"price_share\"]:\n        add(\"price_objections\",\n            _pct(price[\"share\"]) + \" of messages are about price or discounts\",\n            _severity(price[\"share\"], T[\"price_share\"]),\n            {\"messages\": price[\"count\"], \"share\": price[\"share\"],\n             \"negotiation_rounds\": (ins.get(\"commerce\") or {}).get(\"negotiation_rounds\", 0),\n             \"examples\": price[\"examples\"]},\n            \"Price questions that go unanswered turn into lost sales; a \"\n            \"price list the assistant can quote and clear negotiation bounds \"\n            \"close them.\",\n            _confidence(sample, T[\"topic_min\"]),\n            \"Review prices and negotiation bounds\", \"/dashboard/settings\")\n\n    trouble_count = sum(by_topic.get(k, {}).get(\"count\", 0) for k in (\"returns\", \"complaint\"))\n    trouble_share = _share(trouble_count, sample)\n    if trouble_count >= T[\"topic_min\"] and trouble_share >= T[\"trouble_share\"]:\n        add(\"complaints_returns\",\n            _pct(trouble_share) + \" of messages are complaints or return requests\",\n            _severity(trouble_share, T[\"trouble_share\"]),\n            {\"messages\": trouble_count, \"share\": trouble_share,\n             \"examples\": (by_topic.get(\"complaint\", {}).get(\"examples\", [])\n                          + by_topic.get(\"returns\", {}).get(\"examples\", []))[:EXAMPLES]},\n            \"Unhappy customers rarely order twice; these chats need a human \"\n            \"fast and a clear return policy the assistant can state.\",\n            _confidence(sample, T[\"topic_min\"]),\n            \"Open the conversations\", \"/dashboard/conversations\")\n\n    mix = ins.get(\"mix\") or {}\n    if mix.get(\"conversations\", 0) >= T[\"sentiment_min\"] \\\n            and mix.get(\"negative_share\", 0) >= T[\"negative_share\"]:\n        add(\"negative_sentiment\",\n            _pct(mix[\"negative_share\"]) + \" of recent conversations read negative\",\n            _severity(mix[\"negative_share\"], T[\"negative_share\"]),\n            {\"conversations\": mix[\"conversations\"],\n             \"negative\": (mix.get(\"sentiment\") or {}).get(\"negative\", 0)},\n            \"Negative sentiment this high usually means a delivery or \"\n            \"quality problem is repeating.\",\n            _confidence(mix[\"conversations\"], T[\"sentiment_min\"]),\n            \"Review negative conversations\", \"/dashboard/conversations\")\n\n    traces = quality.get(\"traces\") or {}\n    if traces.get(\"decisions\", 0) >= T[\"decisions_min\"] \\\n            and traces.get(\"handoff_share\", 0) >= T[\"handoff_share\"]:\n        reasons = traces.get(\"reasons\") or {}\n        top_reason = max(reasons.items(), key=lambda i: i[1])[0] if reasons else None\n        add(\"ai_low_confidence\",\n            \"The assistant hands off \" + _pct(traces[\"handoff_share\"]) + \" of the time\",\n            _severity(traces[\"handoff_share\"], T[\"handoff_share\"]),\n            {\"decisions\": traces[\"decisions\"], \"handoffs\": traces[\"handoffs\"],\n             \"top_reason\": top_reason, \"avg_confidence\": traces.get(\"avg_confidence\"),\n             \"grounded_share\": traces.get(\"grounded_share\")},\n            \"Every handoff is a chat your team answers by hand. More business \"\n            \"facts and published documents raise its confidence.\",\n            _confidence(traces[\"decisions\"], T[\"decisions_min\"]),\n            \"Add business facts and documents\", \"/dashboard/bot\")\n\n    if traces.get(\"policy_blocks\", 0) >= T[\"policy_min\"]:\n        add(\"ai_policy_blocks\",\n            \"Policy stopped \" + str(traces[\"policy_blocks\"]) + \" AI replies\",\n            _severity(traces[\"policy_blocks\"], T[\"policy_min\"]),\n            {\"policy_blocks\": traces[\"policy_blocks\"], \"decisions\": traces.get(\"decisions\", 0)},\n            \"The assistant keeps drafting promises it must not make (refunds, \"\n            \"discounts, dates). Tighten its instructions and refund rules.\",\n            _confidence(traces[\"policy_blocks\"], T[\"policy_min\"]),\n            \"Review persona instructions and facts\", \"/dashboard/bot\")\n\n    handoffs = quality.get(\"handoffs\") or {}\n    if handoffs.get(\"current\", 0) >= T[\"handoff_min\"] and handoffs.get(\"growth\") is not None \\\n            and handoffs[\"growth\"] >= T[\"handoff_growth\"]:\n        add(\"handoffs_rising\",\n            \"Handoffs to your team are up \" + _pct(handoffs[\"growth\"]) + \" vs the previous \"\n            + str(days) + \" days\",\n            _severity(handoffs[\"growth\"], T[\"handoff_growth\"]),\n            {\"current\": handoffs[\"current\"], \"previous\": handoffs[\"previous\"],\n             \"by_source\": handoffs.get(\"by_source\"), \"reasons\": handoffs.get(\"reasons\")},\n            \"Something new is tripping the assistant or your workflows.\",\n            _confidence(handoffs[\"current\"], T[\"handoff_min\"]),\n            \"Open the handoff queue\", \"/dashboard/bot\")\n\n    if handoffs.get(\"open_unassigned\", 0) >= 1:\n        add(\"handoffs_unassigned\",\n            str(handoffs[\"open_unassigned\"]) + \" handoff\"\n            + (\"s are\" if handoffs[\"open_unassigned\"] != 1 else \" is\")\n            + \" waiting with nobody assigned\",\n            \"critical\" if handoffs[\"open_unassigned\"] >= 3 else \"warn\",\n            {\"open_unassigned\": handoffs[\"open_unassigned\"], \"open\": handoffs.get(\"open\", 0)},\n            \"Customers in these chats are waiting for a person who has not \"\n            \"been picked.\",\n            0.95,\n            \"Set an escalation contact on your AI personas\", \"/dashboard/bot\")\n\n    usage = quality.get(\"usage\") or {}\n    if usage.get(\"calls\", 0) >= T[\"ai_calls_min\"] and usage.get(\"failed_share\", 0) >= T[\"ai_fail_share\"]:\n        add(\"ai_engine_failures\",\n            _pct(usage[\"failed_share\"]) + \" of AI calls failed\",\n            _severity(usage[\"failed_share\"], T[\"ai_fail_share\"]),\n            {\"calls\": usage[\"calls\"], \"failed\": usage[\"failed\"],\n             \"avg_latency_ms\": usage.get(\"avg_latency_ms\")},\n            \"Failed calls mean silent handoffs and slower replies; the AI \"\n            \"engine key, model or provider needs attention.\",\n            _confidence(usage[\"calls\"], T[\"ai_calls_min\"]),\n            \"Check the AI engine status\", \"/dashboard/bot\")\n\n    cod = (ins.get(\"commerce\") or {}).get(\"cod\") or {}\n    cod_total = cod.get(\"confirmed\", 0) + cod.get(\"declined\", 0)\n    if cod_total >= T[\"cod_min\"] and cod.get(\"decline_share\", 0) >= T[\"cod_decline_share\"]:\n        add(\"cod_declines\",\n            _pct(cod[\"decline_share\"]) + \" of COD confirmations are declined\",\n            _severity(cod[\"decline_share\"], T[\"cod_decline_share\"]),\n            {\"confirmed\": cod[\"confirmed\"], \"declined\": cod[\"declined\"]},\n            \"Each declined COD is a parcel that would have come back; advance \"\n            \"payment on risky orders protects the margin.\",\n            _confidence(cod_total, T[\"cod_min\"]),\n            \"Review COD risk and advance settings\", \"/dashboard/cod\")\n\n    checkout = ins.get(\"checkout\") or {}\n    if checkout.get(\"created\", 0) >= T[\"checkout_min\"] \\\n            and checkout.get(\"conversion\", 0) < T[\"checkout_conversion\"]:\n        add(\"checkout_unpaid\",\n            \"Only \" + _pct(checkout[\"conversion\"]) + \" of checkout links get paid\",\n            \"critical\" if checkout[\"conversion\"] < T[\"checkout_conversion\"] / 2 else \"warn\",\n            {\"created\": checkout[\"created\"], \"paid\": checkout[\"paid\"]},\n            str(checkout[\"created\"] - checkout[\"paid\"]) + \" links were sent and never paid; \"\n            \"a reminder workflow recovers a share of them.\",\n            _confidence(checkout[\"created\"], T[\"checkout_min\"]),\n            \"Start a payment-reminder workflow\", \"/dashboard/workflows\")\n\n    deliveries = ins.get(\"deliveries\") or {}\n    if deliveries.get(\"bookings\", 0) >= T[\"bookings_min\"] \\\n            and deliveries.get(\"problem_share\", 0) >= T[\"delivery_fail_share\"]:\n        add(\"delivery_failures\",\n            _pct(deliveries[\"problem_share\"]) + \" of courier bookings failed or came back\",\n            _severity(deliveries[\"problem_share\"], T[\"delivery_fail_share\"]),\n            {\"bookings\": deliveries[\"bookings\"], \"problems\": deliveries[\"problem_bookings\"],\n             \"by_status\": deliveries.get(\"by_status\")},\n            \"Returned parcels cost twice; check addresses, COD confirmation \"\n            \"and the courier's performance.\",\n            _confidence(deliveries[\"bookings\"], T[\"bookings_min\"]),\n            \"Open courier bookings\", \"/dashboard/courier\")\n\n    service = ins.get(\"service\") or {}\n    if service.get(\"overdue_replies\", 0) >= T[\"overdue_min\"]:\n        add(\"slow_replies\",\n            str(service[\"overdue_replies\"]) + \" open chats have waited over \"\n            + str(service.get(\"overdue_hours\", 4)) + \" hours for a reply\",\n            _severity(service[\"overdue_replies\"], T[\"overdue_min\"]),\n            {\"overdue_replies\": service[\"overdue_replies\"],\n             \"overdue_hours\": service.get(\"overdue_hours\")},\n            \"Slow first replies lose sales; routing rules or a higher AI \"\n            \"autonomy level cover the gap.\",\n            0.95,\n            \"Open overdue conversations\", \"/dashboard/conversations?needs_reply=overdue\")\n\n    if service.get(\"csat_answers\", 0) >= T[\"csat_min\"] and service.get(\"csat_avg\") is not None \\\n            and service[\"csat_avg\"] < T[\"csat_low\"]:\n        add(\"csat_low\",\n            \"Customer satisfaction is \" + str(service[\"csat_avg\"]) + \" / 5\",\n            \"critical\" if service[\"csat_avg\"] < T[\"csat_low\"] - 1 else \"warn\",\n            {\"csat_avg\": service[\"csat_avg\"], \"answers\": service[\"csat_answers\"]},\n            \"Low ratings track the complaints above; fix the cause, then ask \"\n            \"again.\",\n            _confidence(service[\"csat_answers\"], T[\"csat_min\"]),\n            \"Review recent ratings\", \"/dashboard/analytics\")\n\n    if fun.get(\"configured\") and fun.get(\"events\", 0) >= T[\"stall_min\"] \\\n            and fun.get(\"stalled_share\", 0) >= T[\"stall_share\"]:\n        stuck = sorted((fun.get(\"stages\") or []), key=lambda s: -s.get(\"stalled\", 0))\n        add(\"journey_stalled\",\n            _pct(fun[\"stalled_share\"]) + \" of customers have not moved in \"\n            + str(fun.get(\"stall_days\", STALL_DAYS)) + \" days\",\n            _severity(fun[\"stalled_share\"], T[\"stall_share\"]),\n            {\"stalled\": fun.get(\"stalled\"), \"worst_stage\": stuck[0][\"name\"] if stuck else None,\n             \"overall_conversion\": fun.get(\"overall_conversion\")},\n            \"Customers stuck at one stage need a nudge - a follow-up workflow \"\n            \"on that stage moves them.\",\n            _confidence(fun.get(\"events\", 0), T[\"stall_min\"]),\n            \"Automate a follow-up for that stage\", \"/dashboard/workflows\")\n\n    rank = {\"critical\": 0, \"warn\": 1, \"info\": 2}\n    problems.sort(key=lambda p: (rank.get(p[\"severity\"], 3), -p[\"confidence\"], p[\"key\"]))\n    return problems[:MAX_PROBLEMS]\n\n\n# ---------------------------------------------------------------------------\n# report\n# ---------------------------------------------------------------------------\n\ndef report(cur, client_id: int, days: int) -> Dict[str, Any]:\n    days = _days(days)\n    T = thresholds_for(cur, client_id)\n    ins = insights(cur, client_id, days)\n    quality = ai_quality(cur, client_id, days, gaps=ins.get(\"gaps\"))\n    fun = _guarded(cur, \"funnel\", lambda: funnel(cur, client_id, days))\n    problems = detect_problems(ins, quality, fun, days, thresholds=T)\n    return {\n        \"days\": days,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n        \"insights\": ins,\n        \"ai_quality\": quality,\n        \"funnel\": fun,\n        \"problems\": problems,\n        \"problem_counts\": {\n            \"critical\": sum(1 for p in problems if p[\"severity\"] == \"critical\"),\n            \"warn\": sum(1 for p in problems if p[\"severity\"] == \"warn\"),\n        },\n        \"topics\": [{\"key\": k, \"label\": l} for k, l, _kw in TOPICS],\n        \"thresholds\": T,\n        \"timezone_offset_hours\": ins.get(\"timezone_offset_hours\", TZ_OFFSET_HOURS),\n    }\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\n@bp.get(\"/bi/report\")\ndef get_report():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = report(cur, client_id, days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(data), 200\n\n\n@bp.get(\"/bi/thresholds\")\ndef get_thresholds():\n    \"\"\"Owner-readable problem-detector thresholds (env defaults + overrides).\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = thresholds_for(cur, client_id)\n            tz = timezone_offset_hours(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\n        \"thresholds\": data,\n        \"defaults\": default_thresholds(),\n        \"timezone_offset_hours\": tz,\n        \"keys\": list(OWNER_THRESHOLD_KEYS),\n    }), 200\n\n\n@bp.put(\"/bi/thresholds\")\ndef update_thresholds():\n    \"\"\"Owner saves problem-detector thresholds into client_settings.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        from portal_auth import ensure_human_principal\n        forbidden = ensure_human_principal(principal)\n        if forbidden is not None:\n            return forbidden\n    except Exception:\n        pass\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"thresholds\", payload.get(\"bi_thresholds\", payload))\n    clean, problem = _validate_thresholds(raw)\n    if problem:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": problem}}), 400\n    client_id = int(principal.get(\"client_id\") or 0)\n    import json as _json\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"client_settings\") +\n                \" (client_id BIGINT PRIMARY KEY,\"\n                \" settings JSONB NOT NULL DEFAULT '{}'::jsonb,\"\n                \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n            )\n            # Merge with existing so partial updates keep other keys.\n            cur.execute(\n                \"SELECT settings -> 'bi_thresholds' AS bi_thresholds FROM \"\n                + portal_db._q(\"client_settings\") +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            existing = {}\n            if rows and isinstance(rows[0].get(\"bi_thresholds\"), dict):\n                existing = dict(rows[0][\"bi_thresholds\"])\n            existing.update(clean)\n            # Re-clamp whole map.\n            final = {}\n            for key in OWNER_THRESHOLD_KEYS:\n                if key in existing:\n                    try:\n                        final[key] = _clamp_threshold(key, float(existing[key]))\n                    except Exception:\n                        continue\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(\"client_settings\") +\n                \" (client_id, settings) VALUES (%s, %s::jsonb)\"\n                \" ON CONFLICT (client_id) DO UPDATE SET\"\n                \" settings = client_settings.settings || EXCLUDED.settings,\"\n                \" updated_at = NOW()\",\n                (client_id, _json.dumps({\"bi_thresholds\": final})),\n            )\n            portal_db.log_action(\n                cur, client_id, \"bi.thresholds_update\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"BI thresholds updated (\" + str(len(final)) + \" keys).\")[:200],\n            )\n            data = thresholds_for(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"thresholds\": data}), 200\n\n\n# ---------------------------------------------------------------------------\n# Weekly problems email (ops polish): rides the connector poll like the\n# owner daily digest. Defaults OFF. Uses portal_bi.report + portal_notify.\n# ---------------------------------------------------------------------------\n\nWEEKLY_DEFAULT_HOUR = int(os.environ.get(\"OF_BI_WEEKLY_HOUR\", \"9\") or 9)\nWEEKLY_DEFAULT_WEEKDAY = int(os.environ.get(\"OF_BI_WEEKLY_WEEKDAY\", \"1\") or 1)  # Mon=1..Sun=7 ISO\n\n\ndef default_weekly_settings() -> Dict[str, Any]:\n    return {\n        \"enabled\": False,\n        \"hour\": max(6, min(21, WEEKLY_DEFAULT_HOUR)),\n        \"weekday\": max(1, min(7, WEEKLY_DEFAULT_WEEKDAY)),\n        \"last_sent_date\": None,\n    }\n\n\ndef _load_weekly_settings(cur, client_id: int) -> Dict[str, Any]:\n    out = default_weekly_settings()\n    try:\n        cur.execute(\n            \"SELECT settings -> 'weekly_problems' AS weekly_problems FROM \"\n            + portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        stored = rows[0].get(\"weekly_problems\") if rows and rows[0] else None\n        if isinstance(stored, str):\n            try:\n                stored = json.loads(stored)\n            except Exception:\n                stored = None\n        if isinstance(stored, dict):\n            if isinstance(stored.get(\"enabled\"), bool):\n                out[\"enabled\"] = stored[\"enabled\"]\n            try:\n                hour = int(stored.get(\"hour\"))\n                if 6 <= hour <= 21:\n                    out[\"hour\"] = hour\n            except Exception:\n                pass\n            try:\n                wd = int(stored.get(\"weekday\"))\n                if 1 <= wd <= 7:\n                    out[\"weekday\"] = wd\n            except Exception:\n                pass\n            ls = stored.get(\"last_sent_date\")\n            if isinstance(ls, str) and ls:\n                out[\"last_sent_date\"] = ls[:10]\n    except Exception as error:\n        logger.warning(\"weekly problems settings load failed: %s\", error)\n    return out\n\n\ndef _save_weekly_settings(cur, client_id: int, settings: Dict[str, Any],\n                          actor_user_id=None, note: str = \"\") -> Dict[str, Any]:\n    cur.execute(\n        \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"client_settings\") +\n        \" (client_id BIGINT PRIMARY KEY,\"\n        \" settings JSONB NOT NULL DEFAULT '{}'::jsonb,\"\n        \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n    )\n    clean = {\n        \"enabled\": bool(settings.get(\"enabled\")),\n        \"hour\": max(6, min(21, int(settings.get(\"hour\") or WEEKLY_DEFAULT_HOUR))),\n        \"weekday\": max(1, min(7, int(settings.get(\"weekday\") or WEEKLY_DEFAULT_WEEKDAY))),\n        \"last_sent_date\": settings.get(\"last_sent_date\"),\n    }\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(\"client_settings\") +\n        \" (client_id, settings) VALUES (%s, %s::jsonb)\"\n        \" ON CONFLICT (client_id) DO UPDATE SET\"\n        \" settings = client_settings.settings || EXCLUDED.settings,\"\n        \" updated_at = NOW()\",\n        (client_id, json.dumps({\"weekly_problems\": clean})),\n    )\n    if note:\n        portal_db.log_action(\n            cur, client_id, \"bi.weekly_problems_settings\", \"customer_user\",\n            actor_user_id, None, note[:200],\n        )\n    return clean\n\n\ndef _format_weekly_body(data: Dict[str, Any]) -> Tuple[str, str, str]:\n    \"\"\"Return (title, detail, severity) for portal_notify.\"\"\"\n    problems = data.get(\"problems\") or []\n    counts = data.get(\"problem_counts\") or {}\n    critical = int(counts.get(\"critical\") or 0)\n    warn = int(counts.get(\"warn\") or 0)\n    days = int(data.get(\"days\") or 7)\n    if not problems:\n        title = \"Business insights: quiet week\"\n        detail = (\n            \"No problems crossed the detector thresholds in the last \"\n            + str(days) + \" days. Open Insights anytime to review topics \"\n            \"and AI quality.\"\n        )\n        return title, detail[:500], \"normal\"\n\n    title = (\n        \"Business insights: \"\n        + str(critical) + \" to fix now, \"\n        + str(warn) + \" worth a look\"\n    )\n    lines = []\n    for problem in problems[:6]:\n        sev = str(problem.get(\"severity\") or \"warn\")\n        label = \"FIX\" if sev == \"critical\" else \"LOOK\"\n        action = (problem.get(\"action\") or {}).get(\"label\") or \"\"\n        line = \"[\" + label + \"] \" + str(problem.get(\"title\") or \"\")\n        if action:\n            line += \" \u2014 \" + action\n        lines.append(line)\n    detail = (\n        \"Last \" + str(days) + \" days. Top signals:\\n\"\n        + \"\\n\".join(lines)\n        + \"\\nOpen /dashboard/insights to review evidence and act.\"\n    )\n    severity = \"high\" if critical else \"normal\"\n    return title[:200], detail[:500], severity\n\n\ndef materialize_weekly_problems(cur, client_id: int, conn=None) -> int:\n    \"\"\"Once a week (owner-chosen weekday + hour), email/bell the BI problems.\n    Defaults OFF. Never raises. Returns 1 when a notification was sent.\"\"\"\n    try:\n        settings = _load_weekly_settings(cur, client_id)\n        if not settings.get(\"enabled\"):\n            return 0\n        # ISO weekday 1=Mon .. 7=Sun via PostgreSQL\n        cur.execute(\n            \"SELECT EXTRACT(ISODOW FROM NOW())::int AS wd,\"\n            \" EXTRACT(HOUR FROM NOW())::int AS h,\"\n            \" TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD') AS d\"\n        )\n        rows = portal_db.rows(cur)\n        row = rows[0] if rows else {}\n        wd = int(row.get(\"wd\") or 0)\n        hour = int(row.get(\"h\") or 0)\n        today = str(row.get(\"d\") or \"\")\n        if wd != int(settings.get(\"weekday\") or 0):\n            return 0\n        if hour < int(settings.get(\"hour\") or 9):\n            return 0\n        if settings.get(\"last_sent_date\") == today:\n            return 0\n\n        data = report(cur, client_id, 7)\n        title, detail, severity = _format_weekly_body(data)\n        import portal_notify\n\n        portal_notify.notify(\n            client_id,\n            \"insights\",\n            title,\n            detail,\n            severity=severity,\n            dedupe_key=\"weekly_problems:\" + today,\n            in_app=True,\n        )\n        settings[\"last_sent_date\"] = today\n        _save_weekly_settings(cur, client_id, settings, note=\"\")\n        if conn is not None:\n            try:\n                conn.commit()\n            except Exception:\n                pass\n        portal_db.log_action(\n            cur, client_id, \"bi.weekly_problems_sent\", \"system\", None, None,\n            (title)[:200],\n        )\n        if conn is not None:\n            try:\n                conn.commit()\n            except Exception:\n                pass\n        return 1\n    except Exception as error:\n        logger.warning(\"weekly problems materialize failed: %s\", error)\n        return 0\n\n\n@bp.get(\"/bi/weekly-problems\")\ndef get_weekly_problems_settings():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = _load_weekly_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\n        \"settings\": data,\n        \"weekdays\": [\n            {\"value\": 1, \"label\": \"Monday\"},\n            {\"value\": 2, \"label\": \"Tuesday\"},\n            {\"value\": 3, \"label\": \"Wednesday\"},\n            {\"value\": 4, \"label\": \"Thursday\"},\n            {\"value\": 5, \"label\": \"Friday\"},\n            {\"value\": 6, \"label\": \"Saturday\"},\n            {\"value\": 7, \"label\": \"Sunday\"},\n        ],\n    }), 200\n\n\n@bp.put(\"/bi/weekly-problems\")\ndef update_weekly_problems_settings():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        from portal_auth import ensure_human_principal\n        forbidden = ensure_human_principal(principal)\n        if forbidden is not None:\n            return forbidden\n    except Exception:\n        pass\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"settings\", payload)\n    if not isinstance(raw, dict):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"settings must be an object.\"}}), 400\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            current = _load_weekly_settings(cur, client_id)\n            if \"enabled\" in raw and isinstance(raw.get(\"enabled\"), bool):\n                current[\"enabled\"] = raw[\"enabled\"]\n            if \"hour\" in raw:\n                try:\n                    hour = int(raw.get(\"hour\"))\n                    if not (6 <= hour <= 21):\n                        raise ValueError(\"hour\")\n                    current[\"hour\"] = hour\n                except Exception:\n                    return jsonify({\"error\": {\n                        \"code\": \"bad_request\",\n                        \"message\": \"hour must be between 6 and 21.\"}}), 400\n            if \"weekday\" in raw:\n                try:\n                    wd = int(raw.get(\"weekday\"))\n                    if not (1 <= wd <= 7):\n                        raise ValueError(\"weekday\")\n                    current[\"weekday\"] = wd\n                except Exception:\n                    return jsonify({\"error\": {\n                        \"code\": \"bad_request\",\n                        \"message\": \"weekday must be 1 (Mon) to 7 (Sun).\"}}), 400\n            saved = _save_weekly_settings(\n                cur, client_id, current,\n                actor_user_id=principal.get(\"user_id\"),\n                note=(\"Weekly problems email \"\n                      + (\"on\" if current[\"enabled\"] else \"off\") + \".\"),\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"settings\": saved}), 200\n\n\n@bp.post(\"/bi/weekly-problems/send\")\ndef send_weekly_problems_now():\n    \"\"\"Owner test: build this week's report and notify immediately (no schedule gate).\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        from portal_auth import ensure_human_principal\n        forbidden = ensure_human_principal(principal)\n        if forbidden is not None:\n            return forbidden\n    except Exception:\n        pass\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = report(cur, client_id, 7)\n            title, detail, severity = _format_weekly_body(data)\n            import portal_notify\n            result = portal_notify.notify(\n                client_id, \"insights\", title, detail,\n                severity=severity,\n                dedupe_key=\"weekly_problems:manual:\"\n                + str(int(__import__(\"time\").time())),\n                in_app=True,\n                email_sync=True,\n            )\n            portal_db.log_action(\n                cur, client_id, \"bi.weekly_problems_sent\", \"customer_user\",\n                principal.get(\"user_id\"), None, (title + \" (manual)\")[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"title\": title, \"result\": result,\n                    \"problem_counts\": data.get(\"problem_counts\")}), 200\n\n");
writeNewRepair("OmniFlow-Control-Plane/portal_bi.py", "def materialize_weekly_problems", true,
    "\"\"\"Business Intelligence layer (MASTER-UPGRADE build-order 12): insights,\nproblem detector, AI quality and the journey funnel - deterministic mining\nover data the platform ALREADY collects. Zero LLM cost, no new write path.\n\n    GET /api/v1/portal/bi/report?days=7|30 ->\n        {days, generated_at, insights, ai_quality, funnel, problems}\n\n* insights   - what customers talk about (topic lexicon over the inbound\n               messages of the window, with the previous window for trend\n               and real example questions as evidence), sentiment /\n               purchase-intent / urgency mix (portal_intelligence), busy\n               hours, knowledge gaps, commerce signals (COD declines,\n               checkout conversion, delivery problems, overdue replies,\n               CSAT).\n* ai_quality - what the assistant did and how well: decisions send vs\n               handoff with reasons, average confidence, grounded / cited\n               share (portal_brain_traces), resolution rate (answered chats\n               that never needed a human), CSAT after AI answers, engine\n               failures + latency (portal_ai_usage), handoff trend\n               (portal_escalations), the questions it could not answer.\n* funnel     - the owner's journey stages (portal_memory): who is where\n               now, who reached each stage in the window, stage-to-stage\n               conversion, median time to move on, contacts stalled.\n* problems   - the Problem Detector: rules over the numbers above ->\n               Problem / Evidence / Impact / Confidence / Action, each with\n               a deep link. Thresholds default from env (OF_BI_*) and owners can\n               override them per workspace (client_settings.bi_thresholds);\n               busy hours use the business_hours timezone. Confidence\n               grows with sample size, nothing fires on thin data.\n\nEvery block runs behind a SAVEPOINT so one missing table blanks only that\nblock; samples are capped (OF_BI_SAMPLE_MAX / OF_BI_EVENTS_MAX) so a busy\nworkspace cannot make the page wait. Tenant-scoped; open to API keys\n(read-only).\n\"\"\"\n\nimport logging\nimport json\nimport os\nimport re\nimport statistics\nfrom datetime import datetime, timezone\nfrom typing import Any, Callable, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import PortalAuthUnavailable, authenticate_portal_request\n\nlogger = logging.getLogger(\"omniflow.portal-bi\")\n\nbp = Blueprint(\"portal_bi\", __name__, url_prefix=\"/api/v1/portal\")\n\nDEFAULT_DAYS = 7\nALLOWED_DAYS = (7, 30)\nSAMPLE_MAX = int(os.environ.get(\"OF_BI_SAMPLE_MAX\", \"3000\") or 3000)\nEVENTS_MAX = int(os.environ.get(\"OF_BI_EVENTS_MAX\", \"5000\") or 5000)\nGAPS_MAX = int(os.environ.get(\"OF_BI_GAPS_MAX\", \"200\") or 200)\nEXAMPLES = int(os.environ.get(\"OF_BI_EXAMPLES\", \"3\") or 3)\nTZ_OFFSET_HOURS = int(os.environ.get(\"OF_BI_TZ_OFFSET_HOURS\", \"5\") or 5)\nSTALL_DAYS = int(os.environ.get(\"OF_BI_STALL_DAYS\", \"7\") or 7)\nMAX_PROBLEMS = int(os.environ.get(\"OF_BI_MAX_PROBLEMS\", \"8\") or 8)\n\n\ndef _env_float(name: str, default: float) -> float:\n    try:\n        return float(os.environ.get(name, \"\") or default)\n    except Exception:\n        return default\n\n\n#: Problem-detector thresholds (share = 0..1, min = sample size).\nTHRESHOLDS: Dict[str, float] = {\n    \"gaps_min\": _env_float(\"OF_BI_GAPS_MIN\", 5),\n    \"topic_min\": _env_float(\"OF_BI_TOPIC_MIN\", 10),\n    \"delivery_share\": _env_float(\"OF_BI_DELIVERY_SHARE\", 0.25),\n    \"price_share\": _env_float(\"OF_BI_PRICE_SHARE\", 0.20),\n    \"trouble_share\": _env_float(\"OF_BI_TROUBLE_SHARE\", 0.15),\n    \"negative_share\": _env_float(\"OF_BI_NEGATIVE_SHARE\", 0.25),\n    \"sentiment_min\": _env_float(\"OF_BI_SENTIMENT_MIN\", 10),\n    \"handoff_share\": _env_float(\"OF_BI_HANDOFF_SHARE\", 0.30),\n    \"decisions_min\": _env_float(\"OF_BI_DECISIONS_MIN\", 10),\n    \"handoff_growth\": _env_float(\"OF_BI_HANDOFF_GROWTH\", 0.5),\n    \"handoff_min\": _env_float(\"OF_BI_HANDOFF_MIN\", 5),\n    \"policy_min\": _env_float(\"OF_BI_POLICY_MIN\", 3),\n    \"ai_fail_share\": _env_float(\"OF_BI_AI_FAIL_SHARE\", 0.20),\n    \"ai_calls_min\": _env_float(\"OF_BI_AI_CALLS_MIN\", 10),\n    \"cod_decline_share\": _env_float(\"OF_BI_COD_DECLINE_SHARE\", 0.30),\n    \"cod_min\": _env_float(\"OF_BI_COD_MIN\", 10),\n    \"checkout_conversion\": _env_float(\"OF_BI_CHECKOUT_CONVERSION\", 0.40),\n    \"checkout_min\": _env_float(\"OF_BI_CHECKOUT_MIN\", 10),\n    \"delivery_fail_share\": _env_float(\"OF_BI_DELIVERY_FAIL_SHARE\", 0.15),\n    \"bookings_min\": _env_float(\"OF_BI_BOOKINGS_MIN\", 10),\n    \"csat_low\": _env_float(\"OF_BI_CSAT_LOW\", 3.5),\n    \"csat_min\": _env_float(\"OF_BI_CSAT_MIN\", 5),\n    \"overdue_min\": _env_float(\"OF_BI_OVERDUE_MIN\", 5),\n    \"stall_share\": _env_float(\"OF_BI_STALL_SHARE\", 0.30),\n    \"stall_min\": _env_float(\"OF_BI_STALL_MIN\", 10),\n}\n\n#: Owner-editable knobs under client_settings.settings.bi_thresholds.\n#: Env OF_BI_* remains the default floor; blank keys fall back here.\nOWNER_THRESHOLD_KEYS = (\n    \"gaps_min\", \"topic_min\", \"delivery_share\", \"price_share\", \"trouble_share\",\n    \"negative_share\", \"sentiment_min\", \"handoff_share\", \"decisions_min\",\n    \"handoff_growth\", \"handoff_min\", \"policy_min\", \"ai_fail_share\",\n    \"ai_calls_min\", \"cod_decline_share\", \"cod_min\", \"checkout_conversion\",\n    \"checkout_min\", \"delivery_fail_share\", \"bookings_min\", \"csat_low\",\n    \"csat_min\", \"overdue_min\", \"stall_share\", \"stall_min\",\n)\nSHARE_KEYS = {\n    \"delivery_share\", \"price_share\", \"trouble_share\", \"negative_share\",\n    \"handoff_share\", \"ai_fail_share\", \"cod_decline_share\", \"checkout_conversion\",\n    \"delivery_fail_share\", \"stall_share\", \"handoff_growth\",\n}\nMIN_KEYS = {\n    \"gaps_min\", \"topic_min\", \"sentiment_min\", \"decisions_min\", \"handoff_min\",\n    \"policy_min\", \"ai_calls_min\", \"cod_min\", \"checkout_min\", \"bookings_min\",\n    \"csat_min\", \"overdue_min\", \"stall_min\",\n}\n\n\ndef _clamp_threshold(key: str, value: float) -> float:\n    if key in SHARE_KEYS:\n        return max(0.0, min(1.0, float(value)))\n    if key == \"csat_low\":\n        return max(1.0, min(5.0, float(value)))\n    if key in MIN_KEYS:\n        return max(1.0, min(1000.0, float(value)))\n    return float(value)\n\n\ndef default_thresholds() -> Dict[str, float]:\n    return {k: float(v) for k, v in THRESHOLDS.items()}\n\n\ndef thresholds_for(cur, client_id: int) -> Dict[str, float]:\n    \"\"\"Env defaults overlaid with owner-saved client_settings.bi_thresholds.\"\"\"\n    out = default_thresholds()\n    try:\n        cur.execute(\n            \"SELECT settings -> 'bi_thresholds' AS bi_thresholds FROM \"\n            + portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        stored = rows[0].get(\"bi_thresholds\") if rows and rows[0] else None\n        if isinstance(stored, str):\n            import json as _json\n            try:\n                stored = _json.loads(stored)\n            except Exception:\n                stored = None\n        if isinstance(stored, dict):\n            for key in OWNER_THRESHOLD_KEYS:\n                raw = stored.get(key)\n                if raw is None or isinstance(raw, bool):\n                    continue\n                try:\n                    out[key] = _clamp_threshold(key, float(raw))\n                except Exception:\n                    continue\n    except Exception as error:\n        logger.warning(\"bi thresholds load failed: %s\", error)\n    return out\n\n\ndef timezone_offset_hours(cur, client_id: int) -> int:\n    \"\"\"Workspace timezone from business_hours; env OF_BI_TZ_OFFSET_HOURS fallback.\"\"\"\n    name = None\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \"\n            + portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n        if isinstance(stored, str):\n            import json as _json\n            try:\n                stored = _json.loads(stored)\n            except Exception:\n                stored = None\n        if isinstance(stored, dict):\n            name = stored.get(\"timezone\")\n    except Exception as error:\n        logger.warning(\"bi timezone load failed: %s\", error)\n    if isinstance(name, str) and name.strip():\n        try:\n            from zoneinfo import ZoneInfo\n            from datetime import datetime as _dt\n            now = _dt.now(ZoneInfo(\"UTC\"))\n            local = now.astimezone(ZoneInfo(name.strip()))\n            offset = local.utcoffset()\n            if offset is not None:\n                return int(offset.total_seconds() // 3600)\n        except Exception:\n            pass\n    return TZ_OFFSET_HOURS\n\n\ndef _validate_thresholds(payload) -> tuple:\n    if not isinstance(payload, dict):\n        return None, \"bi_thresholds must be an object.\"\n    clean: Dict[str, float] = {}\n    for key, raw in payload.items():\n        if key not in OWNER_THRESHOLD_KEYS:\n            continue\n        if raw is None or isinstance(raw, bool):\n            return None, key + \" must be a number.\"\n        try:\n            clean[key] = _clamp_threshold(key, float(raw))\n        except Exception:\n            return None, key + \" must be a number.\"\n    return clean, None\n\n\n#: (key, label, keywords) - lower-cased substring / word matches over the\n#: customer's text; Roman-Urdu + English. A message may carry several.\nTOPICS: Tuple[Tuple[str, str, Tuple[str, ...]], ...] = (\n    (\"delivery_time\", \"Delivery time\", (\n        \"kab tak\", \"kitne din\", \"kitna time\", \"kab aayega\", \"kab ayega\",\n        \"kab milega\", \"kab pohnch\", \"kab pahunch\", \"delivery\", \"deliver\",\n        \"shipping\", \"courier\", \"tracking\", \"track\", \"dispatch\", \"arrive\",\n        \"pohanch\", \"pahunch\")),\n    (\"price\", \"Price & discounts\", (\n        \"price\", \"qeemat\", \"keemat\", \"kitne ka\", \"kitne ki\", \"kitna hai\",\n        \"rate\", \"mehnga\", \"mehngi\", \"sasta\", \"sasti\", \"discount\", \"kam karo\",\n        \"kam kar\", \"offer\", \"deal\", \"cheap\", \"expensive\", \"final price\")),\n    (\"availability\", \"Availability & sizes\", (\n        \"available\", \"availab\", \"stock\", \"mil jayega\", \"mil jaye ga\",\n        \"milega\", \"hai kya\", \"size\", \"colour\", \"color\", \"variant\", \"restock\",\n        \"out of stock\", \"khatam\")),\n    (\"payment\", \"Payment & COD\", (\n        \"payment\", \"jazzcash\", \"easypaisa\", \"bank\", \"advance\", \"cod\",\n        \"cash on delivery\", \"paisay\", \"paise\", \"transfer\", \"card\", \"pay \")),\n    (\"returns\", \"Returns & refunds\", (\n        \"return\", \"wapas\", \"wapis\", \"exchange\", \"refund\", \"replace\",\n        \"kharab\", \"defect\", \"damage\", \"tuta\", \"toota\", \"galat\", \"wrong item\")),\n    (\"complaint\", \"Complaints\", (\n        \"complaint\", \"shikayat\", \"bakwas\", \"ghatiya\", \"late\", \"abhi tak nahi\",\n        \"nahi aya\", \"nahi aaya\", \"nahi mila\", \"fraud\", \"dhoka\", \"cheat\",\n        \"worst\", \"bura\", \"not received\", \"no response\", \"koi jawab\")),\n    (\"order_status\", \"Order status\", (\n        \"order\", \"status\", \"confirm\", \"booking\", \"book kar\", \"receipt\",\n        \"invoice\", \"order number\", \"order no\")),\n    (\"hours_location\", \"Hours & location\", (\n        \"timing\", \"open hai\", \"kab tak open\", \"kab khulta\", \"address\",\n        \"location\", \"kahan hai\", \"kahan par\", \"shop kahan\", \"branch\",\n        \"map\", \"directions\", \"closed\")),\n)\nTOPIC_LABELS = {key: label for key, label, _kw in TOPICS}\n_WORD_RE = re.compile(r\"[a-z]+\")\n\n\ndef topics_for(text: str) -> List[str]:\n    \"\"\"Topic keys present in one customer text (deterministic lexicon).\"\"\"\n    lowered = \" \" + re.sub(r\"\\s+\", \" \", str(text or \"\").lower()) + \" \"\n    words = set(_WORD_RE.findall(lowered))\n    found: List[str] = []\n    for key, _label, keywords in TOPICS:\n        for keyword in keywords:\n            if \" \" in keyword.strip() or keyword.endswith(\" \"):\n                hit = keyword in lowered\n            elif len(keyword) <= 4:\n                hit = keyword in words\n            else:\n                hit = keyword in lowered\n            if hit:\n                found.append(key)\n                break\n    return found\n\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except Exception:\n        days = DEFAULT_DAYS\n    return days if days in ALLOWED_DAYS else DEFAULT_DAYS\n\n\ndef _share(part: int, whole: int) -> float:\n    return round(part / whole, 3) if whole else 0.0\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    return value.isoformat() if hasattr(value, \"isoformat\") else str(value)\n\n\ndef _snippet(text: Any, limit: int = 120) -> str:\n    text = re.sub(r\"\\s+\", \" \", str(text or \"\")).strip()\n    return text[:limit] + (\"\\u2026\" if len(text) > limit else \"\")\n\n\ndef _guarded(cur, label: str, fn: Callable[[], Any]):\n    \"\"\"Run one block behind a SAVEPOINT; None when it fails (a missing\n    table must blank only its block, never the whole report).\"\"\"\n    try:\n        cur.execute(\"SAVEPOINT of_bi\")\n        value = fn()\n        cur.execute(\"RELEASE SAVEPOINT of_bi\")\n        return value\n    except Exception as error:\n        logger.warning(\"bi %s failed: %s\", label, error)\n        try:\n            cur.execute(\"ROLLBACK TO SAVEPOINT of_bi\")\n        except Exception:\n            pass\n        return None\n\n\n# ---------------------------------------------------------------------------\n# insights\n# ---------------------------------------------------------------------------\n\ndef _sample_messages(cur, client_id: int, days: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT conversation_id, body, created_at,\"\n        \" (created_at > NOW() - make_interval(days => %s)) AS current\"\n        \" FROM \" + portal_db._q(portal_db.MSGS_TABLE) +\n        \" WHERE client_id = %s AND direction = 'in'\"\n        \" AND created_at > NOW() - make_interval(days => %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (days, client_id, days * 2, SAMPLE_MAX),\n    )\n    return portal_db.rows(cur)\n\n\ndef topic_insights(messages: List[Dict[str, Any]],\n                  tz_offset_hours: Optional[int] = None) -> Dict[str, Any]:\n    \"\"\"Pure: topic shares for the current window, the previous window's\n    share for trend, example questions, busy hours.\"\"\"\n    offset = TZ_OFFSET_HOURS if tz_offset_hours is None else int(tz_offset_hours)\n    current = [m for m in messages if m.get(\"current\")]\n    previous = [m for m in messages if not m.get(\"current\")]\n    counts: Dict[str, int] = {}\n    prev_counts: Dict[str, int] = {}\n    examples: Dict[str, List[str]] = {}\n    conversations: Dict[str, set] = {}\n    hours: Dict[int, int] = {}\n    for message in current:\n        keys = topics_for(message.get(\"body\"))\n        for key in keys:\n            counts[key] = counts.get(key, 0) + 1\n            conversations.setdefault(key, set()).add(message.get(\"conversation_id\"))\n            bucket = examples.setdefault(key, [])\n            if len(bucket) < EXAMPLES:\n                snippet = _snippet(message.get(\"body\"))\n                if snippet and snippet not in bucket:\n                    bucket.append(snippet)\n        when = message.get(\"created_at\")\n        if hasattr(when, \"hour\"):\n            hours[(when.hour + offset) % 24] = hours.get(\n                (when.hour + offset) % 24, 0) + 1\n    for message in previous:\n        for key in topics_for(message.get(\"body\")):\n            prev_counts[key] = prev_counts.get(key, 0) + 1\n    total, prev_total = len(current), len(previous)\n    topics = []\n    for key, label, _kw in TOPICS:\n        count = counts.get(key, 0)\n        share = _share(count, total)\n        prev_share = _share(prev_counts.get(key, 0), prev_total)\n        trend = \"flat\"\n        if prev_total and total:\n            if share >= prev_share + 0.05:\n                trend = \"up\"\n            elif share <= prev_share - 0.05:\n                trend = \"down\"\n        elif total and count and not prev_total:\n            trend = \"new\"\n        topics.append({\"key\": key, \"label\": label, \"count\": count,\n                       \"share\": share, \"prev_share\": prev_share,\n                       \"trend\": trend,\n                       \"conversations\": len(conversations.get(key, ())),\n                       \"examples\": examples.get(key, [])})\n    topics.sort(key=lambda t: (-t[\"count\"], t[\"key\"]))\n    busy = sorted(hours.items(), key=lambda item: (-item[1], item[0]))[:3]\n    return {\n        \"messages\": total,\n        \"previous_messages\": prev_total,\n        \"conversations\": len({m.get(\"conversation_id\") for m in current}),\n        \"topics\": topics,\n        \"busy_hours\": [{\"hour\": hour, \"messages\": n} for hour, n in busy],\n        \"tz_offset_hours\": offset,\n    }\n\n\ndef _intelligence_mix(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_intelligence\n\n    cur.execute(\n        \"SELECT sentiment, purchase_intent, urgency, language, COUNT(*) AS n\"\n        \" FROM \" + portal_db._q(portal_intelligence.TABLE) +\n        \" WHERE client_id = %s AND updated_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY sentiment, purchase_intent, urgency, language\",\n        (client_id, days),\n    )\n    out: Dict[str, Any] = {\"conversations\": 0, \"sentiment\": {},\n                           \"purchase_intent\": {}, \"urgency\": {}, \"language\": {}}\n    for row in portal_db.rows(cur):\n        n = int(row.get(\"n\") or 0)\n        out[\"conversations\"] += n\n        for field in (\"sentiment\", \"purchase_intent\", \"urgency\", \"language\"):\n            key = str(row.get(field) or \"unknown\")\n            out[field][key] = out[field].get(key, 0) + n\n    total = out[\"conversations\"]\n    out[\"negative_share\"] = _share(out[\"sentiment\"].get(\"negative\", 0), total)\n    out[\"high_purchase_share\"] = _share(out[\"purchase_intent\"].get(\"high\", 0), total)\n    out[\"urgent_share\"] = _share(out[\"urgency\"].get(\"high\", 0), total)\n    return out\n\n\ndef _gaps(cur, client_id: int, days: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT question, intent, resolved, created_at FROM \" +\n        portal_db._q(portal_db.GAPS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (client_id, days, GAPS_MAX),\n    )\n    rows = portal_db.rows(cur)\n    topic_counts: Dict[str, int] = {}\n    examples: List[str] = []\n    unresolved = 0\n    for row in rows:\n        if not int(row.get(\"resolved\") or 0):\n            unresolved += 1\n        for key in topics_for(row.get(\"question\")):\n            topic_counts[key] = topic_counts.get(key, 0) + 1\n        snippet = _snippet(row.get(\"question\"), 100)\n        if snippet and len(examples) < 5 and snippet not in examples:\n            examples.append(snippet)\n    top = sorted(topic_counts.items(), key=lambda i: (-i[1], i[0]))[:3]\n    return {\"count\": len(rows), \"unresolved\": unresolved,\n            \"top_topics\": [{\"key\": k, \"label\": TOPIC_LABELS.get(k, k), \"count\": n}\n                           for k, n in top],\n            \"examples\": examples}\n\n\ndef _commerce(cur, client_id: int, days: int) -> Dict[str, Any]:\n    out: Dict[str, Any] = {}\n    cur.execute(\n        \"SELECT action, COUNT(*) AS n FROM \" + portal_db._q(\"portal_action_log\") +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" AND action IN ('cod.confirmed', 'cod.declined', 'negotiation.round',\"\n        \" 'checkout.created', 'ai.answer', 'kb.auto_reply')\"\n        \" GROUP BY action\",\n        (client_id, days),\n    )\n    actions = {str(r.get(\"action\")): int(r.get(\"n\") or 0) for r in portal_db.rows(cur)}\n    confirmed = actions.get(\"cod.confirmed\", 0)\n    declined = actions.get(\"cod.declined\", 0)\n    out[\"cod\"] = {\"confirmed\": confirmed, \"declined\": declined,\n                  \"decline_share\": _share(declined, confirmed + declined)}\n    out[\"negotiation_rounds\"] = actions.get(\"negotiation.round\", 0)\n    out[\"auto_answers\"] = actions.get(\"ai.answer\", 0) + actions.get(\"kb.auto_reply\", 0)\n    return out\n\n\ndef _checkout(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_checkout\n\n    cur.execute(\n        \"SELECT COUNT(*) AS created,\"\n        \" COUNT(*) FILTER (WHERE status IN ('paid', 'shipped', 'delivered')) AS paid\"\n        \" FROM \" + portal_db._q(portal_checkout.LINKS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    created = int((rows[0] if rows else {}).get(\"created\") or 0)\n    paid = int((rows[0] if rows else {}).get(\"paid\") or 0)\n    return {\"created\": created, \"paid\": paid, \"conversion\": _share(paid, created)}\n\n\ndef _deliveries(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_courier\n\n    cur.execute(\n        \"SELECT status, COUNT(*) AS n FROM \" + portal_db._q(portal_courier.BOOKINGS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY status\",\n        (client_id, days),\n    )\n    by_status: Dict[str, int] = {}\n    total = problems = 0\n    for row in portal_db.rows(cur):\n        status = str(row.get(\"status\") or \"unknown\").lower()\n        n = int(row.get(\"n\") or 0)\n        by_status[status] = n\n        total += n\n        if any(word in status for word in (\"fail\", \"return\", \"cancel\", \"lost\", \"refus\")):\n            problems += n\n    return {\"bookings\": total, \"problem_bookings\": problems,\n            \"problem_share\": _share(problems, total), \"by_status\": by_status}\n\n\ndef _service(cur, client_id: int, days: int) -> Dict[str, Any]:\n    try:\n        import portal_conversations\n\n        overdue_hours = int(getattr(portal_conversations, \"OVERDUE_HOURS\", 4))\n    except Exception:\n        overdue_hours = 4\n    msgs = portal_db._q(portal_db.MSGS_TABLE)\n    cur.execute(\n        \"SELECT COUNT(*) AS n FROM \" + portal_db._q(portal_db.CONV_TABLE) + \" c\"\n        \" WHERE c.client_id = %s AND c.status = 'open'\"\n        \" AND EXISTS (SELECT 1 FROM \" + msgs + \" nr\"\n        \" WHERE nr.conversation_id = c.id GROUP BY nr.conversation_id\"\n        \" HAVING COALESCE(MAX(CASE WHEN nr.direction = 'in' THEN nr.id END), 0)\"\n        \" > COALESCE(MAX(CASE WHEN nr.direction = 'out' THEN nr.id END), 0)\"\n        \" AND MAX(CASE WHEN nr.direction = 'in' THEN nr.created_at END)\"\n        \" < NOW() - make_interval(hours => %s))\",\n        (client_id, overdue_hours),\n    )\n    rows = portal_db.rows(cur)\n    overdue = int((rows[0] if rows else {}).get(\"n\") or 0)\n    cur.execute(\n        \"SELECT AVG(score) AS avg_score, COUNT(*) AS n FROM \" +\n        portal_db._q(portal_db.CSAT_TABLE) +\n        \" WHERE client_id = %s AND score IS NOT NULL\"\n        \" AND answered_at > NOW() - make_interval(days => %s)\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    avg = (rows[0] if rows else {}).get(\"avg_score\")\n    return {\"overdue_replies\": overdue, \"overdue_hours\": overdue_hours,\n            \"csat_avg\": round(float(avg), 2) if avg is not None else None,\n            \"csat_answers\": int((rows[0] if rows else {}).get(\"n\") or 0)}\n\n\ndef insights(cur, client_id: int, days: int) -> Dict[str, Any]:\n    \"\"\"Customer-side picture for the window (each block fail-soft).\"\"\"\n    days = _days(days)\n    tz_off = timezone_offset_hours(cur, client_id)\n    topics = _guarded(cur, \"topics\", lambda: topic_insights(\n        _sample_messages(cur, client_id, days), tz_off))\n    return {\n        \"days\": days,\n        \"timezone_offset_hours\": tz_off,\n        \"topics\": topics,\n        \"mix\": _guarded(cur, \"intelligence\", lambda: _intelligence_mix(cur, client_id, days)),\n        \"gaps\": _guarded(cur, \"gaps\", lambda: _gaps(cur, client_id, days)),\n        \"commerce\": _guarded(cur, \"commerce\", lambda: _commerce(cur, client_id, days)),\n        \"checkout\": _guarded(cur, \"checkout\", lambda: _checkout(cur, client_id, days)),\n        \"deliveries\": _guarded(cur, \"deliveries\", lambda: _deliveries(cur, client_id, days)),\n        \"service\": _guarded(cur, \"service\", lambda: _service(cur, client_id, days)),\n    }\n\n\n# ---------------------------------------------------------------------------\n# AI quality\n# ---------------------------------------------------------------------------\n\ndef _traces(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_brain\n\n    traces = portal_db._q(portal_brain.TRACES_TABLE)\n    cur.execute(\n        \"SELECT kind, decision, COALESCE(grounding->>'reason', '') AS reason,\"\n        \" COUNT(*) AS n,\"\n        \" AVG(NULLIF(grounding->>'confidence', '')::numeric) AS avg_confidence,\"\n        \" COUNT(*) FILTER (WHERE\"\n        \" jsonb_array_length(COALESCE(grounding->'kb_ids', '[]'::jsonb)) > 0\"\n        \" OR jsonb_array_length(COALESCE(grounding->'knowledge_ids', '[]'::jsonb)) > 0\"\n        \" OR jsonb_array_length(COALESCE(grounding->'fact_ids', '[]'::jsonb)) > 0)\"\n        \" AS grounded,\"\n        \" COUNT(*) FILTER (WHERE\"\n        \" jsonb_array_length(COALESCE(grounding->'citations', '[]'::jsonb)) > 0)\"\n        \" AS cited\"\n        \" FROM \" + traces +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY kind, decision, reason\",\n        (client_id, days),\n    )\n    groups = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT DATE(created_at) AS day, decision, COUNT(*) AS n FROM \" + traces +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY DATE(created_at), decision ORDER BY day\",\n        (client_id, days),\n    )\n    daily = portal_db.rows(cur)\n    return summarize_traces(groups, daily)\n\n\ndef summarize_traces(groups: List[Dict[str, Any]], daily: List[Dict[str, Any]]) -> Dict[str, Any]:\n    \"\"\"Pure: decisions / handoff share / reasons / confidence / grounding.\"\"\"\n    total = sends = handoffs = grounded = cited = 0\n    answers = drafts = 0\n    reasons: Dict[str, int] = {}\n    conf_weight = 0.0\n    conf_n = 0\n    for row in groups:\n        n = int(row.get(\"n\") or 0)\n        total += n\n        if str(row.get(\"kind\") or \"\") == \"ingest_answer\":\n            answers += n\n        else:\n            drafts += n\n        if str(row.get(\"decision\") or \"\") == \"send\":\n            sends += n\n        else:\n            handoffs += n\n            reason = str(row.get(\"reason\") or \"unknown\")\n            if reason.startswith(\"policy:\"):\n                reason = \"policy\"\n            reasons[reason] = reasons.get(reason, 0) + n\n        grounded += int(row.get(\"grounded\") or 0)\n        cited += int(row.get(\"cited\") or 0)\n        avg = row.get(\"avg_confidence\")\n        if avg is not None:\n            conf_weight += float(avg) * n\n            conf_n += n\n    by_day: Dict[str, Dict[str, int]] = {}\n    for row in daily:\n        day = row.get(\"day\")\n        key = day.isoformat() if hasattr(day, \"isoformat\") else str(day)\n        entry = by_day.setdefault(key, {\"send\": 0, \"handoff\": 0})\n        if str(row.get(\"decision\") or \"\") == \"send\":\n            entry[\"send\"] += int(row.get(\"n\") or 0)\n        else:\n            entry[\"handoff\"] += int(row.get(\"n\") or 0)\n    return {\n        \"decisions\": total,\n        \"auto_answers\": answers,\n        \"drafts\": drafts,\n        \"sends\": sends,\n        \"handoffs\": handoffs,\n        \"handoff_share\": _share(handoffs, total),\n        \"reasons\": reasons,\n        \"policy_blocks\": reasons.get(\"policy\", 0),\n        \"llm_unavailable\": reasons.get(\"llm_unavailable\", 0),\n        \"avg_confidence\": round(conf_weight / conf_n, 3) if conf_n else None,\n        \"grounded_share\": _share(grounded, total),\n        \"cited_share\": _share(cited, total),\n        \"by_day\": [{\"day\": day, **entry} for day, entry in sorted(by_day.items())],\n    }\n\n\ndef _resolution(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_escalation\n\n    cur.execute(\n        \"SELECT COUNT(DISTINCT a.conversation_id) AS answered,\"\n        \" COUNT(DISTINCT CASE WHEN e.id IS NOT NULL THEN a.conversation_id END)\"\n        \" AS escalated\"\n        \" FROM \" + portal_db._q(\"portal_action_log\") + \" a\"\n        \" LEFT JOIN \" + portal_db._q(portal_escalation.TABLE) + \" e\"\n        \" ON e.client_id = a.client_id AND e.conversation_id = a.conversation_id\"\n        \" AND e.created_at >= a.created_at\"\n        \" WHERE a.client_id = %s AND a.action = 'ai.answer'\"\n        \" AND a.created_at > NOW() - make_interval(days => %s)\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    answered = int((rows[0] if rows else {}).get(\"answered\") or 0)\n    escalated = int((rows[0] if rows else {}).get(\"escalated\") or 0)\n    cur.execute(\n        \"SELECT AVG(s.score) AS avg_score, COUNT(*) AS n FROM \" +\n        portal_db._q(portal_db.CSAT_TABLE) + \" s\"\n        \" WHERE s.client_id = %s AND s.score IS NOT NULL\"\n        \" AND s.answered_at > NOW() - make_interval(days => %s)\"\n        \" AND EXISTS (SELECT 1 FROM \" + portal_db._q(\"portal_action_log\") + \" a\"\n        \" WHERE a.client_id = s.client_id AND a.conversation_id = s.conversation_id\"\n        \" AND a.action = 'ai.answer')\",\n        (client_id, days),\n    )\n    rows = portal_db.rows(cur)\n    avg = (rows[0] if rows else {}).get(\"avg_score\")\n    return {\"answered_conversations\": answered, \"escalated_after\": escalated,\n            \"resolved_share\": _share(answered - escalated, answered),\n            \"csat_after_ai\": round(float(avg), 2) if avg is not None else None,\n            \"csat_after_ai_n\": int((rows[0] if rows else {}).get(\"n\") or 0)}\n\n\ndef _handoffs(cur, client_id: int, days: int) -> Dict[str, Any]:\n    import portal_escalation\n\n    table = portal_db._q(portal_escalation.TABLE)\n    cur.execute(\n        \"SELECT COUNT(*) FILTER (WHERE created_at > NOW() - make_interval(days => %s))\"\n        \" AS current,\"\n        \" COUNT(*) FILTER (WHERE created_at <= NOW() - make_interval(days => %s)\"\n        \" AND created_at > NOW() - make_interval(days => %s)) AS previous,\"\n        \" COUNT(*) FILTER (WHERE status = 'open') AS open_now,\"\n        \" COUNT(*) FILTER (WHERE status = 'open' AND target_user_id IS NULL)\"\n        \" AS open_unassigned,\"\n        \" AVG(EXTRACT(EPOCH FROM (resolved_at - created_at)))\"\n        \" FILTER (WHERE resolved_at > NOW() - make_interval(days => %s))\"\n        \" AS avg_resolve_seconds\"\n        \" FROM \" + table + \" WHERE client_id = %s\",\n        (days, days, days * 2, days, client_id),\n    )\n    rows = portal_db.rows(cur)\n    totals = rows[0] if rows else {}\n    cur.execute(\n        \"SELECT source, reason, COUNT(*) AS n FROM \" + table +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY source, reason ORDER BY n DESC LIMIT 20\",\n        (client_id, days),\n    )\n    by_source: Dict[str, int] = {}\n    reasons: List[Dict[str, Any]] = []\n    for row in portal_db.rows(cur):\n        n = int(row.get(\"n\") or 0)\n        source = str(row.get(\"source\") or \"system\")\n        by_source[source] = by_source.get(source, 0) + n\n        reasons.append({\"label\": portal_escalation.reason_label(row.get(\"reason\")),\n                        \"source\": source, \"count\": n})\n    current = int(totals.get(\"current\") or 0)\n    previous = int(totals.get(\"previous\") or 0)\n    avg = totals.get(\"avg_resolve_seconds\")\n    growth = None\n    if previous:\n        growth = round((current - previous) / previous, 2)\n    return {\"current\": current, \"previous\": previous, \"growth\": growth,\n            \"open\": int(totals.get(\"open_now\") or 0),\n            \"open_unassigned\": int(totals.get(\"open_unassigned\") or 0),\n            \"avg_resolve_minutes\": (round(float(avg) / 60.0, 1)\n                                    if avg is not None else None),\n            \"by_source\": by_source, \"reasons\": reasons[:5]}\n\n\ndef ai_quality(cur, client_id: int, days: int,\n               gaps: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:\n    days = _days(days)\n\n    def _usage():\n        import portal_ai_usage\n\n        portal_ai_usage._ensure_ddl(cur)\n        report = portal_ai_usage.usage_report(cur, client_id, days)\n        totals = report[\"totals\"]\n        return {\"calls\": totals[\"calls\"], \"failed\": totals[\"failed\"],\n                \"failed_share\": _share(totals[\"failed\"], totals[\"calls\"]),\n                \"avg_latency_ms\": totals[\"avg_latency_ms\"],\n                \"cost_usd\": totals[\"cost_usd\"], \"priced\": totals[\"priced\"]}\n\n    out = {\n        \"days\": days,\n        \"traces\": _guarded(cur, \"traces\", lambda: _traces(cur, client_id, days)),\n        \"resolution\": _guarded(cur, \"resolution\", lambda: _resolution(cur, client_id, days)),\n        \"handoffs\": _guarded(cur, \"handoffs\", lambda: _handoffs(cur, client_id, days)),\n        \"usage\": _guarded(cur, \"usage\", _usage),\n    }\n    if gaps is None:\n        gaps = _guarded(cur, \"gaps\", lambda: _gaps(cur, client_id, days))\n    out[\"unanswered\"] = {\"count\": (gaps or {}).get(\"count\", 0),\n                         \"examples\": (gaps or {}).get(\"examples\", [])}\n    return out\n\n\n# ---------------------------------------------------------------------------\n# journey funnel\n# ---------------------------------------------------------------------------\n\ndef _funnel_rows(cur, client_id: int, days: int) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]], List[Dict[str, Any]]]:\n    import portal_memory\n\n    cur.execute(\n        \"SELECT id, name, position FROM \" + portal_db._q(portal_memory.STAGES_TABLE) +\n        \" WHERE client_id = %s AND is_active = TRUE ORDER BY position, id\",\n        (client_id,),\n    )\n    stages = portal_db.rows(cur)\n    if not stages:\n        return [], [], []\n    cur.execute(\n        \"SELECT stage_id, COUNT(*) AS n FROM \" + portal_db._q(portal_memory.STATE_TABLE) +\n        \" WHERE client_id = %s GROUP BY stage_id\",\n        (client_id,),\n    )\n    state = portal_db.rows(cur)\n    cur.execute(\n        \"SELECT contact_id, stage_name, created_at FROM \" +\n        portal_db._q(portal_memory.EVENTS_TABLE) +\n        \" WHERE client_id = %s AND created_at > NOW() - make_interval(days => %s)\"\n        \" ORDER BY contact_id, id LIMIT %s\",\n        (client_id, days * 2, EVENTS_MAX),\n    )\n    events = portal_db.rows(cur)\n    return stages, state, events\n\n\ndef build_funnel(stages: List[Dict[str, Any]], state: List[Dict[str, Any]],\n                 events: List[Dict[str, Any]], days: int,\n                 now: Optional[datetime] = None) -> Dict[str, Any]:\n    \"\"\"Pure: current distribution, reached-in-window, conversion between\n    consecutive stages, median hours to move on, stalled contacts.\"\"\"\n    now = now or datetime.now(timezone.utc)\n    order = [str(s.get(\"name\")) for s in stages]\n    position = {name: index for index, name in enumerate(order)}\n    by_id = {int(s.get(\"id\") or 0): str(s.get(\"name\")) for s in stages}\n    current: Dict[str, int] = {name: 0 for name in order}\n    for row in state:\n        name = by_id.get(int(row.get(\"stage_id\") or 0))\n        if name is not None:\n            current[name] += int(row.get(\"n\") or 0)\n    window_start = now.timestamp() - days * 86400\n    reached: Dict[str, set] = {name: set() for name in order}\n    durations: Dict[str, List[float]] = {name: [] for name in order}\n    last_event: Dict[str, Tuple[str, float]] = {}\n    per_contact: Dict[str, List[Tuple[str, float]]] = {}\n    for row in events:\n        name = str(row.get(\"stage_name\") or \"\")\n        if name not in position:\n            continue\n        when = row.get(\"created_at\")\n        stamp = when.timestamp() if hasattr(when, \"timestamp\") else 0.0\n        contact = str(row.get(\"contact_id\") or \"\")\n        per_contact.setdefault(contact, []).append((name, stamp))\n    for contact, moves in per_contact.items():\n        for index, (name, stamp) in enumerate(moves):\n            if stamp >= window_start:\n                reached[name].add(contact)\n            if index + 1 < len(moves):\n                next_name, next_stamp = moves[index + 1]\n                if position[next_name] > position[name] and next_stamp >= stamp:\n                    durations[name].append((next_stamp - stamp) / 3600.0)\n        last_event[contact] = moves[-1]\n    stalled: Dict[str, int] = {name: 0 for name in order}\n    stall_seconds = STALL_DAYS * 86400\n    for contact, (name, stamp) in last_event.items():\n        if position[name] < len(order) - 1 and now.timestamp() - stamp > stall_seconds:\n            stalled[name] += 1\n    out_stages = []\n    for index, name in enumerate(order):\n        reached_n = len(reached[name])\n        prev_reached = len(reached[order[index - 1]]) if index else None\n        conversion = (_share(reached_n, prev_reached) if prev_reached else None)\n        median = (round(statistics.median(durations[name]), 1)\n                  if durations[name] else None)\n        out_stages.append({\n            \"name\": name, \"position\": index, \"current\": current[name],\n            \"reached\": reached_n, \"conversion_from_previous\": conversion,\n            \"median_hours_to_next\": median, \"stalled\": stalled[name],\n        })\n    first = len(reached[order[0]]) if order else 0\n    last = len(reached[order[-1]]) if order else 0\n    total_contacts = sum(current.values())\n    total_stalled = sum(stalled.values())\n    return {\n        \"configured\": bool(order),\n        \"days\": days,\n        \"stages\": out_stages,\n        \"contacts\": total_contacts,\n        \"reached_first\": first,\n        \"reached_last\": last,\n        \"overall_conversion\": _share(last, first) if first else None,\n        \"stalled\": total_stalled,\n        \"stalled_share\": _share(total_stalled, len(last_event)) if last_event else 0.0,\n        \"stall_days\": STALL_DAYS,\n        \"events\": len(events),\n    }\n\n\ndef funnel(cur, client_id: int, days: int) -> Dict[str, Any]:\n    days = _days(days)\n    stages, state, events = _funnel_rows(cur, client_id, days)\n    return build_funnel(stages, state, events, days)\n\n\n# ---------------------------------------------------------------------------\n# problem detector\n# ---------------------------------------------------------------------------\n\ndef _confidence(n: float, minimum: float) -> float:\n    \"\"\"Grows with the sample: minimum -> 0.55, 4x minimum -> 0.95.\"\"\"\n    if minimum <= 0:\n        return 0.95\n    return round(min(0.95, 0.4 + 0.6 * min(1.0, n / (4.0 * minimum))), 2)\n\n\ndef _severity(value: float, threshold: float, factor: float = 2.0) -> str:\n    return \"critical\" if threshold and value >= threshold * factor else \"warn\"\n\n\ndef _pct(share: Any) -> str:\n    try:\n        return str(int(round(float(share or 0) * 100))) + \"%\"\n    except Exception:\n        return \"0%\"\n\n\ndef detect_problems(ins: Optional[Dict[str, Any]], quality: Optional[Dict[str, Any]],\n                    fun: Optional[Dict[str, Any]], days: int,\n                    thresholds: Optional[Dict[str, float]] = None) -> List[Dict[str, Any]]:\n    \"\"\"Pure rules -> Problem / Evidence / Impact / Confidence / Action.\"\"\"\n    T = thresholds if isinstance(thresholds, dict) and thresholds else THRESHOLDS\n    ins = ins or {}\n    quality = quality or {}\n    fun = fun or {}\n    problems: List[Dict[str, Any]] = []\n\n    def add(key, title, severity, evidence, impact, confidence, action_label, href):\n        problems.append({\"key\": key, \"title\": title, \"severity\": severity,\n                         \"evidence\": evidence, \"impact\": impact,\n                         \"confidence\": confidence,\n                         \"action\": {\"label\": action_label, \"href\": href}})\n\n    topics = ins.get(\"topics\") or {}\n    by_topic = {t[\"key\"]: t for t in (topics.get(\"topics\") or [])}\n    sample = int(topics.get(\"messages\") or 0)\n\n    gaps = ins.get(\"gaps\") or {}\n    if gaps.get(\"count\", 0) >= T[\"gaps_min\"]:\n        top = gaps.get(\"top_topics\") or []\n        add(\"knowledge_gaps\",\n            \"Customers keep asking things the assistant cannot answer\",\n            _severity(gaps[\"count\"], T[\"gaps_min\"], 3),\n            {\"unanswered_questions\": gaps[\"count\"],\n             \"top_topic\": top[0][\"label\"] if top else None,\n             \"examples\": gaps.get(\"examples\", [])[:EXAMPLES]},\n            str(gaps[\"count\"]) + \" questions in \" + str(days)\n            + \" days waited for a person (\" + str(gaps.get(\"unresolved\", 0))\n            + \" still unresolved).\",\n            _confidence(gaps[\"count\"], T[\"gaps_min\"]),\n            \"Add these answers to the Knowledge base\", \"/dashboard/knowledge-base\")\n\n    delivery = by_topic.get(\"delivery_time\")\n    if delivery and delivery[\"count\"] >= T[\"topic_min\"] \\\n            and delivery[\"share\"] >= T[\"delivery_share\"]:\n        add(\"delivery_questions\",\n            _pct(delivery[\"share\"]) + \" of customer messages ask about delivery time\",\n            _severity(delivery[\"share\"], T[\"delivery_share\"]),\n            {\"messages\": delivery[\"count\"], \"share\": delivery[\"share\"],\n             \"trend\": delivery[\"trend\"], \"examples\": delivery[\"examples\"]},\n            \"Publishing your delivery policy lets the assistant answer these \"\n            \"instantly instead of your team.\",\n            _confidence(sample, T[\"topic_min\"]),\n            \"Publish a delivery policy source\", \"/dashboard/knowledge-base\")\n\n    price = by_topic.get(\"price\")\n    if price and price[\"count\"] >= T[\"topic_min\"] and price[\"share\"] >= T[\"price_share\"]:\n        add(\"price_objections\",\n            _pct(price[\"share\"]) + \" of messages are about price or discounts\",\n            _severity(price[\"share\"], T[\"price_share\"]),\n            {\"messages\": price[\"count\"], \"share\": price[\"share\"],\n             \"negotiation_rounds\": (ins.get(\"commerce\") or {}).get(\"negotiation_rounds\", 0),\n             \"examples\": price[\"examples\"]},\n            \"Price questions that go unanswered turn into lost sales; a \"\n            \"price list the assistant can quote and clear negotiation bounds \"\n            \"close them.\",\n            _confidence(sample, T[\"topic_min\"]),\n            \"Review prices and negotiation bounds\", \"/dashboard/settings\")\n\n    trouble_count = sum(by_topic.get(k, {}).get(\"count\", 0) for k in (\"returns\", \"complaint\"))\n    trouble_share = _share(trouble_count, sample)\n    if trouble_count >= T[\"topic_min\"] and trouble_share >= T[\"trouble_share\"]:\n        add(\"complaints_returns\",\n            _pct(trouble_share) + \" of messages are complaints or return requests\",\n            _severity(trouble_share, T[\"trouble_share\"]),\n            {\"messages\": trouble_count, \"share\": trouble_share,\n             \"examples\": (by_topic.get(\"complaint\", {}).get(\"examples\", [])\n                          + by_topic.get(\"returns\", {}).get(\"examples\", []))[:EXAMPLES]},\n            \"Unhappy customers rarely order twice; these chats need a human \"\n            \"fast and a clear return policy the assistant can state.\",\n            _confidence(sample, T[\"topic_min\"]),\n            \"Open the conversations\", \"/dashboard/conversations\")\n\n    mix = ins.get(\"mix\") or {}\n    if mix.get(\"conversations\", 0) >= T[\"sentiment_min\"] \\\n            and mix.get(\"negative_share\", 0) >= T[\"negative_share\"]:\n        add(\"negative_sentiment\",\n            _pct(mix[\"negative_share\"]) + \" of recent conversations read negative\",\n            _severity(mix[\"negative_share\"], T[\"negative_share\"]),\n            {\"conversations\": mix[\"conversations\"],\n             \"negative\": (mix.get(\"sentiment\") or {}).get(\"negative\", 0)},\n            \"Negative sentiment this high usually means a delivery or \"\n            \"quality problem is repeating.\",\n            _confidence(mix[\"conversations\"], T[\"sentiment_min\"]),\n            \"Review negative conversations\", \"/dashboard/conversations\")\n\n    traces = quality.get(\"traces\") or {}\n    if traces.get(\"decisions\", 0) >= T[\"decisions_min\"] \\\n            and traces.get(\"handoff_share\", 0) >= T[\"handoff_share\"]:\n        reasons = traces.get(\"reasons\") or {}\n        top_reason = max(reasons.items(), key=lambda i: i[1])[0] if reasons else None\n        add(\"ai_low_confidence\",\n            \"The assistant hands off \" + _pct(traces[\"handoff_share\"]) + \" of the time\",\n            _severity(traces[\"handoff_share\"], T[\"handoff_share\"]),\n            {\"decisions\": traces[\"decisions\"], \"handoffs\": traces[\"handoffs\"],\n             \"top_reason\": top_reason, \"avg_confidence\": traces.get(\"avg_confidence\"),\n             \"grounded_share\": traces.get(\"grounded_share\")},\n            \"Every handoff is a chat your team answers by hand. More business \"\n            \"facts and published documents raise its confidence.\",\n            _confidence(traces[\"decisions\"], T[\"decisions_min\"]),\n            \"Add business facts and documents\", \"/dashboard/bot\")\n\n    if traces.get(\"policy_blocks\", 0) >= T[\"policy_min\"]:\n        add(\"ai_policy_blocks\",\n            \"Policy stopped \" + str(traces[\"policy_blocks\"]) + \" AI replies\",\n            _severity(traces[\"policy_blocks\"], T[\"policy_min\"]),\n            {\"policy_blocks\": traces[\"policy_blocks\"], \"decisions\": traces.get(\"decisions\", 0)},\n            \"The assistant keeps drafting promises it must not make (refunds, \"\n            \"discounts, dates). Tighten its instructions and refund rules.\",\n            _confidence(traces[\"policy_blocks\"], T[\"policy_min\"]),\n            \"Review persona instructions and facts\", \"/dashboard/bot\")\n\n    handoffs = quality.get(\"handoffs\") or {}\n    if handoffs.get(\"current\", 0) >= T[\"handoff_min\"] and handoffs.get(\"growth\") is not None \\\n            and handoffs[\"growth\"] >= T[\"handoff_growth\"]:\n        add(\"handoffs_rising\",\n            \"Handoffs to your team are up \" + _pct(handoffs[\"growth\"]) + \" vs the previous \"\n            + str(days) + \" days\",\n            _severity(handoffs[\"growth\"], T[\"handoff_growth\"]),\n            {\"current\": handoffs[\"current\"], \"previous\": handoffs[\"previous\"],\n             \"by_source\": handoffs.get(\"by_source\"), \"reasons\": handoffs.get(\"reasons\")},\n            \"Something new is tripping the assistant or your workflows.\",\n            _confidence(handoffs[\"current\"], T[\"handoff_min\"]),\n            \"Open the handoff queue\", \"/dashboard/bot\")\n\n    if handoffs.get(\"open_unassigned\", 0) >= 1:\n        add(\"handoffs_unassigned\",\n            str(handoffs[\"open_unassigned\"]) + \" handoff\"\n            + (\"s are\" if handoffs[\"open_unassigned\"] != 1 else \" is\")\n            + \" waiting with nobody assigned\",\n            \"critical\" if handoffs[\"open_unassigned\"] >= 3 else \"warn\",\n            {\"open_unassigned\": handoffs[\"open_unassigned\"], \"open\": handoffs.get(\"open\", 0)},\n            \"Customers in these chats are waiting for a person who has not \"\n            \"been picked.\",\n            0.95,\n            \"Set an escalation contact on your AI personas\", \"/dashboard/bot\")\n\n    usage = quality.get(\"usage\") or {}\n    if usage.get(\"calls\", 0) >= T[\"ai_calls_min\"] and usage.get(\"failed_share\", 0) >= T[\"ai_fail_share\"]:\n        add(\"ai_engine_failures\",\n            _pct(usage[\"failed_share\"]) + \" of AI calls failed\",\n            _severity(usage[\"failed_share\"], T[\"ai_fail_share\"]),\n            {\"calls\": usage[\"calls\"], \"failed\": usage[\"failed\"],\n             \"avg_latency_ms\": usage.get(\"avg_latency_ms\")},\n            \"Failed calls mean silent handoffs and slower replies; the AI \"\n            \"engine key, model or provider needs attention.\",\n            _confidence(usage[\"calls\"], T[\"ai_calls_min\"]),\n            \"Check the AI engine status\", \"/dashboard/bot\")\n\n    cod = (ins.get(\"commerce\") or {}).get(\"cod\") or {}\n    cod_total = cod.get(\"confirmed\", 0) + cod.get(\"declined\", 0)\n    if cod_total >= T[\"cod_min\"] and cod.get(\"decline_share\", 0) >= T[\"cod_decline_share\"]:\n        add(\"cod_declines\",\n            _pct(cod[\"decline_share\"]) + \" of COD confirmations are declined\",\n            _severity(cod[\"decline_share\"], T[\"cod_decline_share\"]),\n            {\"confirmed\": cod[\"confirmed\"], \"declined\": cod[\"declined\"]},\n            \"Each declined COD is a parcel that would have come back; advance \"\n            \"payment on risky orders protects the margin.\",\n            _confidence(cod_total, T[\"cod_min\"]),\n            \"Review COD risk and advance settings\", \"/dashboard/cod\")\n\n    checkout = ins.get(\"checkout\") or {}\n    if checkout.get(\"created\", 0) >= T[\"checkout_min\"] \\\n            and checkout.get(\"conversion\", 0) < T[\"checkout_conversion\"]:\n        add(\"checkout_unpaid\",\n            \"Only \" + _pct(checkout[\"conversion\"]) + \" of checkout links get paid\",\n            \"critical\" if checkout[\"conversion\"] < T[\"checkout_conversion\"] / 2 else \"warn\",\n            {\"created\": checkout[\"created\"], \"paid\": checkout[\"paid\"]},\n            str(checkout[\"created\"] - checkout[\"paid\"]) + \" links were sent and never paid; \"\n            \"a reminder workflow recovers a share of them.\",\n            _confidence(checkout[\"created\"], T[\"checkout_min\"]),\n            \"Start a payment-reminder workflow\", \"/dashboard/workflows\")\n\n    deliveries = ins.get(\"deliveries\") or {}\n    if deliveries.get(\"bookings\", 0) >= T[\"bookings_min\"] \\\n            and deliveries.get(\"problem_share\", 0) >= T[\"delivery_fail_share\"]:\n        add(\"delivery_failures\",\n            _pct(deliveries[\"problem_share\"]) + \" of courier bookings failed or came back\",\n            _severity(deliveries[\"problem_share\"], T[\"delivery_fail_share\"]),\n            {\"bookings\": deliveries[\"bookings\"], \"problems\": deliveries[\"problem_bookings\"],\n             \"by_status\": deliveries.get(\"by_status\")},\n            \"Returned parcels cost twice; check addresses, COD confirmation \"\n            \"and the courier's performance.\",\n            _confidence(deliveries[\"bookings\"], T[\"bookings_min\"]),\n            \"Open courier bookings\", \"/dashboard/courier\")\n\n    service = ins.get(\"service\") or {}\n    if service.get(\"overdue_replies\", 0) >= T[\"overdue_min\"]:\n        add(\"slow_replies\",\n            str(service[\"overdue_replies\"]) + \" open chats have waited over \"\n            + str(service.get(\"overdue_hours\", 4)) + \" hours for a reply\",\n            _severity(service[\"overdue_replies\"], T[\"overdue_min\"]),\n            {\"overdue_replies\": service[\"overdue_replies\"],\n             \"overdue_hours\": service.get(\"overdue_hours\")},\n            \"Slow first replies lose sales; routing rules or a higher AI \"\n            \"autonomy level cover the gap.\",\n            0.95,\n            \"Open overdue conversations\", \"/dashboard/conversations?needs_reply=overdue\")\n\n    if service.get(\"csat_answers\", 0) >= T[\"csat_min\"] and service.get(\"csat_avg\") is not None \\\n            and service[\"csat_avg\"] < T[\"csat_low\"]:\n        add(\"csat_low\",\n            \"Customer satisfaction is \" + str(service[\"csat_avg\"]) + \" / 5\",\n            \"critical\" if service[\"csat_avg\"] < T[\"csat_low\"] - 1 else \"warn\",\n            {\"csat_avg\": service[\"csat_avg\"], \"answers\": service[\"csat_answers\"]},\n            \"Low ratings track the complaints above; fix the cause, then ask \"\n            \"again.\",\n            _confidence(service[\"csat_answers\"], T[\"csat_min\"]),\n            \"Review recent ratings\", \"/dashboard/analytics\")\n\n    if fun.get(\"configured\") and fun.get(\"events\", 0) >= T[\"stall_min\"] \\\n            and fun.get(\"stalled_share\", 0) >= T[\"stall_share\"]:\n        stuck = sorted((fun.get(\"stages\") or []), key=lambda s: -s.get(\"stalled\", 0))\n        add(\"journey_stalled\",\n            _pct(fun[\"stalled_share\"]) + \" of customers have not moved in \"\n            + str(fun.get(\"stall_days\", STALL_DAYS)) + \" days\",\n            _severity(fun[\"stalled_share\"], T[\"stall_share\"]),\n            {\"stalled\": fun.get(\"stalled\"), \"worst_stage\": stuck[0][\"name\"] if stuck else None,\n             \"overall_conversion\": fun.get(\"overall_conversion\")},\n            \"Customers stuck at one stage need a nudge - a follow-up workflow \"\n            \"on that stage moves them.\",\n            _confidence(fun.get(\"events\", 0), T[\"stall_min\"]),\n            \"Automate a follow-up for that stage\", \"/dashboard/workflows\")\n\n    rank = {\"critical\": 0, \"warn\": 1, \"info\": 2}\n    problems.sort(key=lambda p: (rank.get(p[\"severity\"], 3), -p[\"confidence\"], p[\"key\"]))\n    return problems[:MAX_PROBLEMS]\n\n\n# ---------------------------------------------------------------------------\n# report\n# ---------------------------------------------------------------------------\n\ndef report(cur, client_id: int, days: int) -> Dict[str, Any]:\n    days = _days(days)\n    T = thresholds_for(cur, client_id)\n    ins = insights(cur, client_id, days)\n    quality = ai_quality(cur, client_id, days, gaps=ins.get(\"gaps\"))\n    fun = _guarded(cur, \"funnel\", lambda: funnel(cur, client_id, days))\n    problems = detect_problems(ins, quality, fun, days, thresholds=T)\n    return {\n        \"days\": days,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n        \"insights\": ins,\n        \"ai_quality\": quality,\n        \"funnel\": fun,\n        \"problems\": problems,\n        \"problem_counts\": {\n            \"critical\": sum(1 for p in problems if p[\"severity\"] == \"critical\"),\n            \"warn\": sum(1 for p in problems if p[\"severity\"] == \"warn\"),\n        },\n        \"topics\": [{\"key\": k, \"label\": l} for k, l, _kw in TOPICS],\n        \"thresholds\": T,\n        \"timezone_offset_hours\": ins.get(\"timezone_offset_hours\", TZ_OFFSET_HOURS),\n    }\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\n@bp.get(\"/bi/report\")\ndef get_report():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = report(cur, client_id, days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(data), 200\n\n\n@bp.get(\"/bi/thresholds\")\ndef get_thresholds():\n    \"\"\"Owner-readable problem-detector thresholds (env defaults + overrides).\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = thresholds_for(cur, client_id)\n            tz = timezone_offset_hours(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\n        \"thresholds\": data,\n        \"defaults\": default_thresholds(),\n        \"timezone_offset_hours\": tz,\n        \"keys\": list(OWNER_THRESHOLD_KEYS),\n    }), 200\n\n\n@bp.put(\"/bi/thresholds\")\ndef update_thresholds():\n    \"\"\"Owner saves problem-detector thresholds into client_settings.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        from portal_auth import ensure_human_principal\n        forbidden = ensure_human_principal(principal)\n        if forbidden is not None:\n            return forbidden\n    except Exception:\n        pass\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"thresholds\", payload.get(\"bi_thresholds\", payload))\n    clean, problem = _validate_thresholds(raw)\n    if problem:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": problem}}), 400\n    client_id = int(principal.get(\"client_id\") or 0)\n    import json as _json\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"client_settings\") +\n                \" (client_id BIGINT PRIMARY KEY,\"\n                \" settings JSONB NOT NULL DEFAULT '{}'::jsonb,\"\n                \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n            )\n            # Merge with existing so partial updates keep other keys.\n            cur.execute(\n                \"SELECT settings -> 'bi_thresholds' AS bi_thresholds FROM \"\n                + portal_db._q(\"client_settings\") +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            existing = {}\n            if rows and isinstance(rows[0].get(\"bi_thresholds\"), dict):\n                existing = dict(rows[0][\"bi_thresholds\"])\n            existing.update(clean)\n            # Re-clamp whole map.\n            final = {}\n            for key in OWNER_THRESHOLD_KEYS:\n                if key in existing:\n                    try:\n                        final[key] = _clamp_threshold(key, float(existing[key]))\n                    except Exception:\n                        continue\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(\"client_settings\") +\n                \" (client_id, settings) VALUES (%s, %s::jsonb)\"\n                \" ON CONFLICT (client_id) DO UPDATE SET\"\n                \" settings = client_settings.settings || EXCLUDED.settings,\"\n                \" updated_at = NOW()\",\n                (client_id, _json.dumps({\"bi_thresholds\": final})),\n            )\n            portal_db.log_action(\n                cur, client_id, \"bi.thresholds_update\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"BI thresholds updated (\" + str(len(final)) + \" keys).\")[:200],\n            )\n            data = thresholds_for(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"thresholds\": data}), 200\n\n\n# ---------------------------------------------------------------------------\n# Weekly problems email (ops polish): rides the connector poll like the\n# owner daily digest. Defaults OFF. Uses portal_bi.report + portal_notify.\n# ---------------------------------------------------------------------------\n\nWEEKLY_DEFAULT_HOUR = int(os.environ.get(\"OF_BI_WEEKLY_HOUR\", \"9\") or 9)\nWEEKLY_DEFAULT_WEEKDAY = int(os.environ.get(\"OF_BI_WEEKLY_WEEKDAY\", \"1\") or 1)  # Mon=1..Sun=7 ISO\n\n\ndef default_weekly_settings() -> Dict[str, Any]:\n    return {\n        \"enabled\": False,\n        \"hour\": max(6, min(21, WEEKLY_DEFAULT_HOUR)),\n        \"weekday\": max(1, min(7, WEEKLY_DEFAULT_WEEKDAY)),\n        \"last_sent_date\": None,\n    }\n\n\ndef _load_weekly_settings(cur, client_id: int) -> Dict[str, Any]:\n    out = default_weekly_settings()\n    try:\n        cur.execute(\n            \"SELECT settings -> 'weekly_problems' AS weekly_problems FROM \"\n            + portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        stored = rows[0].get(\"weekly_problems\") if rows and rows[0] else None\n        if isinstance(stored, str):\n            try:\n                stored = json.loads(stored)\n            except Exception:\n                stored = None\n        if isinstance(stored, dict):\n            if isinstance(stored.get(\"enabled\"), bool):\n                out[\"enabled\"] = stored[\"enabled\"]\n            try:\n                hour = int(stored.get(\"hour\"))\n                if 6 <= hour <= 21:\n                    out[\"hour\"] = hour\n            except Exception:\n                pass\n            try:\n                wd = int(stored.get(\"weekday\"))\n                if 1 <= wd <= 7:\n                    out[\"weekday\"] = wd\n            except Exception:\n                pass\n            ls = stored.get(\"last_sent_date\")\n            if isinstance(ls, str) and ls:\n                out[\"last_sent_date\"] = ls[:10]\n    except Exception as error:\n        logger.warning(\"weekly problems settings load failed: %s\", error)\n    return out\n\n\ndef _save_weekly_settings(cur, client_id: int, settings: Dict[str, Any],\n                          actor_user_id=None, note: str = \"\") -> Dict[str, Any]:\n    cur.execute(\n        \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"client_settings\") +\n        \" (client_id BIGINT PRIMARY KEY,\"\n        \" settings JSONB NOT NULL DEFAULT '{}'::jsonb,\"\n        \" updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())\"\n    )\n    clean = {\n        \"enabled\": bool(settings.get(\"enabled\")),\n        \"hour\": max(6, min(21, int(settings.get(\"hour\") or WEEKLY_DEFAULT_HOUR))),\n        \"weekday\": max(1, min(7, int(settings.get(\"weekday\") or WEEKLY_DEFAULT_WEEKDAY))),\n        \"last_sent_date\": settings.get(\"last_sent_date\"),\n    }\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(\"client_settings\") +\n        \" (client_id, settings) VALUES (%s, %s::jsonb)\"\n        \" ON CONFLICT (client_id) DO UPDATE SET\"\n        \" settings = client_settings.settings || EXCLUDED.settings,\"\n        \" updated_at = NOW()\",\n        (client_id, json.dumps({\"weekly_problems\": clean})),\n    )\n    if note:\n        portal_db.log_action(\n            cur, client_id, \"bi.weekly_problems_settings\", \"customer_user\",\n            actor_user_id, None, note[:200],\n        )\n    return clean\n\n\ndef _format_weekly_body(data: Dict[str, Any]) -> Tuple[str, str, str]:\n    \"\"\"Return (title, detail, severity) for portal_notify.\"\"\"\n    problems = data.get(\"problems\") or []\n    counts = data.get(\"problem_counts\") or {}\n    critical = int(counts.get(\"critical\") or 0)\n    warn = int(counts.get(\"warn\") or 0)\n    days = int(data.get(\"days\") or 7)\n    if not problems:\n        title = \"Business insights: quiet week\"\n        detail = (\n            \"No problems crossed the detector thresholds in the last \"\n            + str(days) + \" days. Open Insights anytime to review topics \"\n            \"and AI quality.\"\n        )\n        return title, detail[:500], \"normal\"\n\n    title = (\n        \"Business insights: \"\n        + str(critical) + \" to fix now, \"\n        + str(warn) + \" worth a look\"\n    )\n    lines = []\n    for problem in problems[:6]:\n        sev = str(problem.get(\"severity\") or \"warn\")\n        label = \"FIX\" if sev == \"critical\" else \"LOOK\"\n        action = (problem.get(\"action\") or {}).get(\"label\") or \"\"\n        line = \"[\" + label + \"] \" + str(problem.get(\"title\") or \"\")\n        if action:\n            line += \" \u2014 \" + action\n        lines.append(line)\n    detail = (\n        \"Last \" + str(days) + \" days. Top signals:\\n\"\n        + \"\\n\".join(lines)\n        + \"\\nOpen /dashboard/insights to review evidence and act.\"\n    )\n    severity = \"high\" if critical else \"normal\"\n    return title[:200], detail[:500], severity\n\n\ndef materialize_weekly_problems(cur, client_id: int, conn=None) -> int:\n    \"\"\"Once a week (owner-chosen weekday + hour), email/bell the BI problems.\n    Defaults OFF. Never raises. Returns 1 when a notification was sent.\"\"\"\n    try:\n        settings = _load_weekly_settings(cur, client_id)\n        if not settings.get(\"enabled\"):\n            return 0\n        # ISO weekday 1=Mon .. 7=Sun via PostgreSQL\n        cur.execute(\n            \"SELECT EXTRACT(ISODOW FROM NOW())::int AS wd,\"\n            \" EXTRACT(HOUR FROM NOW())::int AS h,\"\n            \" TO_CHAR(CURRENT_DATE, 'YYYY-MM-DD') AS d\"\n        )\n        rows = portal_db.rows(cur)\n        row = rows[0] if rows else {}\n        wd = int(row.get(\"wd\") or 0)\n        hour = int(row.get(\"h\") or 0)\n        today = str(row.get(\"d\") or \"\")\n        if wd != int(settings.get(\"weekday\") or 0):\n            return 0\n        if hour < int(settings.get(\"hour\") or 9):\n            return 0\n        if settings.get(\"last_sent_date\") == today:\n            return 0\n\n        data = report(cur, client_id, 7)\n        title, detail, severity = _format_weekly_body(data)\n        import portal_notify\n\n        portal_notify.notify(\n            client_id,\n            \"insights\",\n            title,\n            detail,\n            severity=severity,\n            dedupe_key=\"weekly_problems:\" + today,\n            in_app=True,\n        )\n        settings[\"last_sent_date\"] = today\n        _save_weekly_settings(cur, client_id, settings, note=\"\")\n        if conn is not None:\n            try:\n                conn.commit()\n            except Exception:\n                pass\n        portal_db.log_action(\n            cur, client_id, \"bi.weekly_problems_sent\", \"system\", None, None,\n            (title)[:200],\n        )\n        if conn is not None:\n            try:\n                conn.commit()\n            except Exception:\n                pass\n        return 1\n    except Exception as error:\n        logger.warning(\"weekly problems materialize failed: %s\", error)\n        return 0\n\n\n@bp.get(\"/bi/weekly-problems\")\ndef get_weekly_problems_settings():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = _load_weekly_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\n        \"settings\": data,\n        \"weekdays\": [\n            {\"value\": 1, \"label\": \"Monday\"},\n            {\"value\": 2, \"label\": \"Tuesday\"},\n            {\"value\": 3, \"label\": \"Wednesday\"},\n            {\"value\": 4, \"label\": \"Thursday\"},\n            {\"value\": 5, \"label\": \"Friday\"},\n            {\"value\": 6, \"label\": \"Saturday\"},\n            {\"value\": 7, \"label\": \"Sunday\"},\n        ],\n    }), 200\n\n\n@bp.put(\"/bi/weekly-problems\")\ndef update_weekly_problems_settings():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        from portal_auth import ensure_human_principal\n        forbidden = ensure_human_principal(principal)\n        if forbidden is not None:\n            return forbidden\n    except Exception:\n        pass\n    payload = request.get_json(silent=True) or {}\n    raw = payload.get(\"settings\", payload)\n    if not isinstance(raw, dict):\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"settings must be an object.\"}}), 400\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            current = _load_weekly_settings(cur, client_id)\n            if \"enabled\" in raw and isinstance(raw.get(\"enabled\"), bool):\n                current[\"enabled\"] = raw[\"enabled\"]\n            if \"hour\" in raw:\n                try:\n                    hour = int(raw.get(\"hour\"))\n                    if not (6 <= hour <= 21):\n                        raise ValueError(\"hour\")\n                    current[\"hour\"] = hour\n                except Exception:\n                    return jsonify({\"error\": {\n                        \"code\": \"bad_request\",\n                        \"message\": \"hour must be between 6 and 21.\"}}), 400\n            if \"weekday\" in raw:\n                try:\n                    wd = int(raw.get(\"weekday\"))\n                    if not (1 <= wd <= 7):\n                        raise ValueError(\"weekday\")\n                    current[\"weekday\"] = wd\n                except Exception:\n                    return jsonify({\"error\": {\n                        \"code\": \"bad_request\",\n                        \"message\": \"weekday must be 1 (Mon) to 7 (Sun).\"}}), 400\n            saved = _save_weekly_settings(\n                cur, client_id, current,\n                actor_user_id=principal.get(\"user_id\"),\n                note=(\"Weekly problems email \"\n                      + (\"on\" if current[\"enabled\"] else \"off\") + \".\"),\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"settings\": saved}), 200\n\n\n@bp.post(\"/bi/weekly-problems/send\")\ndef send_weekly_problems_now():\n    \"\"\"Owner test: build this week's report and notify immediately (no schedule gate).\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    try:\n        from portal_auth import ensure_human_principal\n        forbidden = ensure_human_principal(principal)\n        if forbidden is not None:\n            return forbidden\n    except Exception:\n        pass\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = report(cur, client_id, 7)\n            title, detail, severity = _format_weekly_body(data)\n            import portal_notify\n            result = portal_notify.notify(\n                client_id, \"insights\", title, detail,\n                severity=severity,\n                dedupe_key=\"weekly_problems:manual:\"\n                + str(int(__import__(\"time\").time())),\n                in_app=True,\n                email_sync=True,\n            )\n            portal_db.log_action(\n                cur, client_id, \"bi.weekly_problems_sent\", \"customer_user\",\n                principal.get(\"user_id\"), None, (title + \" (manual)\")[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"title\": title, \"result\": result,\n                    \"problem_counts\": data.get(\"problem_counts\")}), 200\n\n");
writeNewRepair("omniflow-backend-patch/portal_notify.py", "(\"insights\", \"Business insights\"", false,
    "\"\"\"Notification service (MASTER-UPGRADE platform service): ONE fan-out for\neverything that must reach the owner - an AI handoff, an approval waiting\nfor a 1/0, a dead delivery, a failed workflow run, a configuration\nproblem.\n\n    portal_notify.notify(client_id, \"escalation\", \"AI handed off a chat\",\n                         detail, severity=\"normal\",\n                         dedupe_key=\"conv:42\", conversation_id=42)\n\ndoes three things and never raises:\n\n* in-app: ``portal_alerts.raise_alert`` (the bell + the Daily brief block;\n  the tenant's alerts toggle and the unread-dedupe law stay exactly as\n  they are);\n* email: through the platform's saved SMTP / Brevo config\n  (``admin_providers._deliver_email``) when THIS tenant switched email on\n  for that kind and severity (opt-in; missing settings row = in-app only;\n  recipient = the saved address or the workspace's first user); the send\n  runs on a background thread so a slow mail server never stalls the\n  message loop;\n* ledger: one ``portal_notifications`` row per notification saying what\n  went where (the owner's \"recent notifications\" list, and the honest\n  answer to \"did the email go out?\").\n\nDesign laws:\n  * callers do NOT pass their cursor - the service uses its own short\n    connection, so a notification never rides (or breaks) the caller's\n    transaction and pinned slot layouts stay untouched;\n  * dedupe: when the same unread alert already exists (same kind +\n    dedupe_key) no second email goes out either;\n  * kinds are a registry (``KINDS``) the settings UI renders from - no\n    per-kind toggles hard-coded in the web layer;\n  * owner API: settings GET/PUT (human-only writes), recent list, and a\n    synchronous \"send a test\" so the owner sees the real delivery result.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport threading\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-notify\")\n\nbp = Blueprint(\"portal_notify\", __name__, url_prefix=\"/api/v1/portal\")\n\nLEDGER_TABLE = \"portal_notifications\"\nSETTINGS_TABLE = \"portal_notify_settings\"\n\n#: (key, label, description) - the settings card renders its toggles from\n#: this list, so adding a kind here is the whole change.\nKINDS: Tuple[Tuple[str, str, str], ...] = (\n    (\"escalation\", \"Handoffs\",\n     \"The AI or a workflow handed a chat to your team.\"),\n    (\"approval\", \"Approvals\",\n     \"An AI action is waiting for your 1 / 0.\"),\n    (\"delivery\", \"Failed deliveries\",\n     \"A message or COD confirmation could not be delivered.\"),\n    (\"workflow\", \"Workflow problems\", \"A workflow run failed.\"),\n    (\"knowledge\", \"Knowledge\", \"A document import or re-fetch failed.\"),\n    (\"system\", \"System\", \"Configuration problems and test notifications.\"),\n    (\"insights\", \"Business insights\",\n     \"Weekly summary of problems the detector flagged.\"),\n)\nKIND_KEYS = tuple(k for k, _l, _d in KINDS)\nSEVERITIES: Tuple[str, ...] = (\"normal\", \"high\")\n\n#: Global kill switch for email (in-app alerts keep their own switch).\nEMAIL_ENABLED = os.environ.get(\n    \"OF_NOTIFY_EMAIL\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n#: OF_NOTIFY_EMAIL_SYNC=1 sends on the request thread (tests, debugging).\nEMAIL_SYNC = os.environ.get(\n    \"OF_NOTIFY_EMAIL_SYNC\", \"0\").strip().lower() in (\"1\", \"true\", \"yes\", \"on\")\n#: Optional absolute base for links inside emails (e.g. https://app.example.com).\nPORTAL_BASE_URL = os.environ.get(\"OF_PORTAL_BASE_URL\", \"\").strip().rstrip(\"/\")\nLIST_LIMIT = 50\nMAX_TITLE = 200\nMAX_DETAIL = 500\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_notifications (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL,\n  severity TEXT NOT NULL DEFAULT 'normal',\n  title TEXT NOT NULL,\n  detail TEXT NOT NULL DEFAULT '',\n  conversation_id BIGINT,\n  alert_id BIGINT,\n  email_to TEXT NOT NULL DEFAULT '',\n  email_status TEXT NOT NULL DEFAULT 'off',\n  email_error TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_notifications_client\n  ON portal_notifications (client_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_notify_settings (\n  client_id BIGINT PRIMARY KEY,\n  email_enabled BOOLEAN NOT NULL DEFAULT FALSE,\n  email_to TEXT NOT NULL DEFAULT '',\n  min_severity TEXT NOT NULL DEFAULT 'normal',\n  kinds JSONB NOT NULL DEFAULT '{}'::jsonb,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# settings\n# ---------------------------------------------------------------------------\n\ndef default_settings() -> Dict[str, Any]:\n    return {\"email_enabled\": False, \"email_to\": \"\", \"min_severity\": \"normal\",\n            \"kinds\": {k: True for k in KIND_KEYS}}\n\n\ndef _shape_settings(row: Optional[Dict[str, Any]]) -> Dict[str, Any]:\n    out = default_settings()\n    if not row:\n        return out\n    out[\"email_enabled\"] = bool(row.get(\"email_enabled\"))\n    out[\"email_to\"] = str(row.get(\"email_to\") or \"\").strip()[:200]\n    severity = str(row.get(\"min_severity\") or \"normal\")\n    out[\"min_severity\"] = severity if severity in SEVERITIES else \"normal\"\n    raw = row.get(\"kinds\")\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw)\n        except Exception:\n            raw = {}\n    if isinstance(raw, dict):\n        for key in KIND_KEYS:\n            if key in raw:\n                out[\"kinds\"][key] = bool(raw.get(key))\n    return out\n\n\ndef load_settings(cur, client_id: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT email_enabled, email_to, min_severity, kinds FROM \"\n        + portal_db._q(SETTINGS_TABLE) + \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    rows = portal_db.rows(cur)\n    return _shape_settings(rows[0] if rows else None)\n\n\ndef save_settings(cur, client_id: int, settings: Dict[str, Any]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(SETTINGS_TABLE) +\n        \" (client_id, email_enabled, email_to, min_severity, kinds,\"\n        \" updated_at) VALUES (%s, %s, %s, %s, CAST(%s AS JSONB), NOW())\"\n        \" ON CONFLICT (client_id) DO UPDATE SET\"\n        \" email_enabled = EXCLUDED.email_enabled,\"\n        \" email_to = EXCLUDED.email_to,\"\n        \" min_severity = EXCLUDED.min_severity,\"\n        \" kinds = EXCLUDED.kinds, updated_at = NOW()\",\n        (client_id, bool(settings.get(\"email_enabled\")),\n         str(settings.get(\"email_to\") or \"\")[:200],\n         str(settings.get(\"min_severity\") or \"normal\"),\n         json.dumps(settings.get(\"kinds\") or {})),\n    )\n\n\ndef validate_settings(payload: Any, current: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:\n    \"\"\"Merge a PUT payload onto the current settings; (settings, error).\"\"\"\n    if not isinstance(payload, dict):\n        return None, \"A JSON object is required.\"\n    out = dict(current)\n    out[\"kinds\"] = dict(current.get(\"kinds\") or {})\n    if \"email_enabled\" in payload:\n        if not isinstance(payload.get(\"email_enabled\"), bool):\n            return None, \"email_enabled must be true or false.\"\n        out[\"email_enabled\"] = payload[\"email_enabled\"]\n    if \"email_to\" in payload:\n        email = str(payload.get(\"email_to\") or \"\").strip()\n        if email and (\"@\" not in email or \" \" in email or len(email) > 200):\n            return None, \"email_to must be a valid e-mail address.\"\n        out[\"email_to\"] = email\n    if \"min_severity\" in payload:\n        severity = str(payload.get(\"min_severity\") or \"\").strip().lower()\n        if severity not in SEVERITIES:\n            return None, \"min_severity must be normal or high.\"\n        out[\"min_severity\"] = severity\n    if \"kinds\" in payload:\n        kinds = payload.get(\"kinds\")\n        if not isinstance(kinds, dict):\n            return None, \"kinds must be an object of booleans.\"\n        for key, value in kinds.items():\n            if key not in KIND_KEYS:\n                return None, \"Unknown notification kind: \" + str(key)[:40]\n            if not isinstance(value, bool):\n                return None, \"kinds.\" + key + \" must be true or false.\"\n            out[\"kinds\"][key] = value\n    return out, None\n\n\ndef _rank(severity: str) -> int:\n    return SEVERITIES.index(severity) if severity in SEVERITIES else 0\n\n\ndef email_configured() -> bool:\n    \"\"\"Is the platform able to send mail at all (admin config or env)?\"\"\"\n    try:\n        import platform_settings\n\n        config = platform_settings.smtp_config()\n        if config.get(\"provider\") == \"brevo\":\n            return bool(config.get(\"brevo_api_key\"))\n        return bool(config.get(\"smtp_host\"))\n    except Exception:\n        return False\n\n\ndef owner_email(cur, client_id: int) -> str:\n    \"\"\"Fallback recipient: the workspace's first user (the owner).\"\"\"\n    try:\n        cur.execute(\n            \"SELECT email FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n            \" WHERE client_id = %s ORDER BY id LIMIT 1\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        return str((rows[0] if rows else {}).get(\"email\") or \"\").strip()\n    except Exception:\n        return \"\"\n\n\n# ---------------------------------------------------------------------------\n# email delivery\n# ---------------------------------------------------------------------------\n\ndef _deliver(to_address: str, subject: str, body: str) -> Tuple[bool, str]:\n    try:\n        import admin_providers\n\n        return admin_providers._deliver_email(to_address, subject, body)\n    except Exception as error:\n        return False, str(error) or \"delivery failed\"\n\n\ndef _mark_email(ledger_id: int, status: str, error: str = \"\") -> None:\n    \"\"\"Record the delivery result (own connection; retried briefly so a\n    ledger row written on a caller's still-open transaction is found).\"\"\"\n    import time\n\n    for attempt in range(3):\n        try:\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(LEDGER_TABLE) +\n                        \" SET email_status = %s, email_error = %s\"\n                        \" WHERE id = %s\",\n                        (status, str(error or \"\")[:300], int(ledger_id)),\n                    )\n                    updated = cur.rowcount\n                conn.commit()\n            finally:\n                conn.close()\n            if updated:\n                return\n        except Exception as problem:\n            logger.warning(\"notification ledger update failed: %s\", problem)\n        time.sleep(2)\n\n\ndef _email_body(title: str, detail: str, conversation_id: Optional[int]) -> str:\n    lines = [title, \"\"]\n    if detail:\n        lines += [detail, \"\"]\n    if conversation_id:\n        path = \"/dashboard/conversations/\" + str(int(conversation_id))\n        lines.append(\"Open the conversation: \" + (PORTAL_BASE_URL + path\n                                                  if PORTAL_BASE_URL else path))\n        lines.append(\"\")\n    lines.append(\"- OmniFlow\")\n    return \"\\n\".join(lines)\n\n\ndef _send(to_address: str, subject: str, body: str, ledger_id: int,\n          sync: bool) -> Tuple[str, str]:\n    \"\"\"Send now (sync) or on a daemon thread; returns (status, error).\"\"\"\n    if sync:\n        ok, detail = _deliver(to_address, subject, body)\n        status = \"sent\" if ok else \"failed\"\n        _mark_email(ledger_id, status, \"\" if ok else detail)\n        return status, (\"\" if ok else detail)\n\n    def _worker() -> None:\n        ok, detail = _deliver(to_address, subject, body)\n        _mark_email(ledger_id, \"sent\" if ok else \"failed\",\n                    \"\" if ok else detail)\n\n    try:\n        threading.Thread(target=_worker, daemon=True,\n                         name=\"of-notify-\" + str(ledger_id)).start()\n        return \"queued\", \"\"\n    except Exception as error:\n        return \"failed\", str(error)\n\n\n# ---------------------------------------------------------------------------\n# the service\n# ---------------------------------------------------------------------------\n\ndef notify(client_id: int, kind: str, title: str, detail: str = \"\",\n           severity: str = \"normal\", dedupe_key: str = \"\",\n           conversation_id: Optional[int] = None, in_app: bool = True,\n           alert_id: Optional[int] = None,\n           email_sync: bool = False) -> Dict[str, Any]:\n    \"\"\"Fan one notification out to the bell, email and the ledger. Never\n    raises; the returned dict says what happened\n    ({in_app, email, email_to, ledger_id, error}).\"\"\"\n    result: Dict[str, Any] = {\"in_app\": alert_id, \"email\": \"off\",\n                              \"email_to\": \"\", \"ledger_id\": None, \"error\": \"\"}\n    kind = str(kind or \"system\")\n    if kind not in KIND_KEYS:\n        kind = \"system\"\n    severity = str(severity or \"normal\")\n    if severity not in SEVERITIES:\n        severity = \"normal\"\n    title = str(title or \"\").strip()[:MAX_TITLE] or \"Notification\"\n    detail = str(detail or \"\").strip()[:MAX_DETAIL]\n    conv = int(conversation_id) if conversation_id else None\n    conn = None\n    try:\n        conn = portal_db._conn()\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = load_settings(cur, client_id)\n            deduped = False\n            if in_app:\n                import portal_alerts\n\n                if portal_alerts.alerts_on(cur, client_id):\n                    new_id = portal_alerts.raise_alert(\n                        cur, client_id, kind, title, detail, severity,\n                        dedupe_key=dedupe_key)\n                    result[\"in_app\"] = new_id\n                    deduped = bool(dedupe_key) and new_id is None\n                else:\n                    result[\"in_app\"] = None\n            email_status, email_to = \"off\", \"\"\n            wants = (EMAIL_ENABLED and settings[\"email_enabled\"]\n                     and settings[\"kinds\"].get(kind, True)\n                     and _rank(severity) >= _rank(settings[\"min_severity\"]))\n            if wants:\n                if deduped:\n                    email_status = \"deduped\"\n                else:\n                    email_to = settings[\"email_to\"] or owner_email(cur, client_id)\n                    email_status = \"queued\" if email_to else \"no_recipient\"\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(LEDGER_TABLE) +\n                \" (client_id, kind, severity, title, detail, conversation_id,\"\n                \" alert_id, email_to, email_status)\"\n                \" VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s) RETURNING id\",\n                (client_id, kind, severity, title, detail, conv,\n                 result[\"in_app\"], email_to, email_status),\n            )\n            rows = portal_db.rows(cur)\n            ledger_id = int((rows[0] if rows else {}).get(\"id\") or 0)\n        conn.commit()\n        conn.close()\n        conn = None\n        result.update({\"ledger_id\": ledger_id or None, \"email\": email_status,\n                       \"email_to\": email_to})\n        if email_status == \"queued\" and ledger_id:\n            status, error = _send(\n                email_to, \"[OmniFlow] \" + title, _email_body(title, detail, conv),\n                ledger_id, sync=bool(email_sync or EMAIL_SYNC))\n            result[\"email\"] = status\n            result[\"error\"] = error\n    except Exception as error:\n        logger.warning(\"notify failed (%s): %s\", kind, error)\n        result[\"error\"] = str(error)[:200]\n    finally:\n        if conn is not None:\n            try:\n                conn.close()\n            except Exception:\n                pass\n    return result\n\n\ndef list_recent(cur, client_id: int, limit: int = LIST_LIMIT) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT id, kind, severity, title, detail, conversation_id, alert_id,\"\n        \" email_to, email_status, email_error, created_at FROM \"\n        + portal_db._q(LEDGER_TABLE) +\n        \" WHERE client_id = %s ORDER BY id DESC LIMIT %s\",\n        (client_id, max(1, min(200, int(limit or LIST_LIMIT)))),\n    )\n    return [_public(r) for r in portal_db.rows(cur)]\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    return value.isoformat() if hasattr(value, \"isoformat\") else str(value)\n\n\ndef _public(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"kind\": str(row.get(\"kind\") or \"\"),\n        \"severity\": str(row.get(\"severity\") or \"normal\"),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"detail\": str(row.get(\"detail\") or \"\"),\n        \"conversation_id\": (int(row[\"conversation_id\"])\n                            if row.get(\"conversation_id\") else None),\n        \"alert_id\": int(row[\"alert_id\"]) if row.get(\"alert_id\") else None,\n        \"email_to\": _mask(str(row.get(\"email_to\") or \"\")),\n        \"email_status\": str(row.get(\"email_status\") or \"off\"),\n        \"email_error\": str(row.get(\"email_error\") or \"\"),\n        \"created_at\": _iso(row.get(\"created_at\")),\n    }\n\n\ndef _mask(email: str) -> str:\n    if \"@\" not in email:\n        return email\n    name, domain = email.split(\"@\", 1)\n    return (name[:2] + \"\\u2026\" if len(name) > 2 else name) + \"@\" + domain\n\n\ndef kinds_public() -> List[Dict[str, str]]:\n    return [{\"key\": k, \"label\": l, \"description\": d} for k, l, d in KINDS]\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _human_or_error():\n    principal, error = _principal_or_error()\n    if error:\n        return None, error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return None, forbidden\n    return principal, None\n\n\ndef _bad(message: str, code: str = \"bad_request\", status: int = 400):\n    return jsonify({\"error\": {\"code\": code, \"message\": message}}), status\n\n\n@bp.get(\"/notifications\")\ndef get_notifications():\n    \"\"\"Recent notifications + this tenant's settings + the kind registry.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        limit = int(request.args.get(\"limit\") or LIST_LIMIT)\n    except Exception:\n        limit = LIST_LIMIT\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            items = list_recent(cur, client_id, limit)\n            settings = load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"items\": items, \"settings\": settings,\n                    \"kinds\": kinds_public(), \"severities\": list(SEVERITIES),\n                    \"email_configured\": email_configured()}), 200\n\n\n@bp.get(\"/notifications/settings\")\ndef get_settings():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"settings\": settings, \"kinds\": kinds_public(),\n                    \"email_configured\": email_configured()}), 200\n\n\n@bp.put(\"/notifications/settings\")\ndef put_settings():\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True)\n    if not isinstance(payload, dict):\n        return _bad(\"A JSON object is required.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            current = load_settings(cur, client_id)\n            merged, problem = validate_settings(payload, current)\n            if problem:\n                conn.rollback()\n                return _bad(problem)\n            save_settings(cur, client_id, merged)\n            portal_db.log_action(\n                cur, client_id, \"notifications.settings\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                \"Email \" + (\"on\" if merged[\"email_enabled\"] else \"off\")\n                + \", min severity \" + merged[\"min_severity\"],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"settings\": merged}), 200\n\n\n@bp.post(\"/notifications/test\")\ndef send_test():\n    \"\"\"Synchronous test through every configured channel - the owner sees\n    exactly what a real notification would do.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    result = notify(\n        client_id, \"system\", \"Test notification\",\n        \"Sent from Settings by \" + str(principal.get(\"email\") or \"you\")\n        + \". If you can read this, notifications work.\",\n        severity=\"normal\", email_sync=True)\n    return jsonify({\"ok\": not result.get(\"error\"), \"result\": result}), 200\n");
writeNewRepair("OmniFlow-Control-Plane/portal_notify.py", "(\"insights\", \"Business insights\"", true,
    "\"\"\"Notification service (MASTER-UPGRADE platform service): ONE fan-out for\neverything that must reach the owner - an AI handoff, an approval waiting\nfor a 1/0, a dead delivery, a failed workflow run, a configuration\nproblem.\n\n    portal_notify.notify(client_id, \"escalation\", \"AI handed off a chat\",\n                         detail, severity=\"normal\",\n                         dedupe_key=\"conv:42\", conversation_id=42)\n\ndoes three things and never raises:\n\n* in-app: ``portal_alerts.raise_alert`` (the bell + the Daily brief block;\n  the tenant's alerts toggle and the unread-dedupe law stay exactly as\n  they are);\n* email: through the platform's saved SMTP / Brevo config\n  (``admin_providers._deliver_email``) when THIS tenant switched email on\n  for that kind and severity (opt-in; missing settings row = in-app only;\n  recipient = the saved address or the workspace's first user); the send\n  runs on a background thread so a slow mail server never stalls the\n  message loop;\n* ledger: one ``portal_notifications`` row per notification saying what\n  went where (the owner's \"recent notifications\" list, and the honest\n  answer to \"did the email go out?\").\n\nDesign laws:\n  * callers do NOT pass their cursor - the service uses its own short\n    connection, so a notification never rides (or breaks) the caller's\n    transaction and pinned slot layouts stay untouched;\n  * dedupe: when the same unread alert already exists (same kind +\n    dedupe_key) no second email goes out either;\n  * kinds are a registry (``KINDS``) the settings UI renders from - no\n    per-kind toggles hard-coded in the web layer;\n  * owner API: settings GET/PUT (human-only writes), recent list, and a\n    synchronous \"send a test\" so the owner sees the real delivery result.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport threading\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-notify\")\n\nbp = Blueprint(\"portal_notify\", __name__, url_prefix=\"/api/v1/portal\")\n\nLEDGER_TABLE = \"portal_notifications\"\nSETTINGS_TABLE = \"portal_notify_settings\"\n\n#: (key, label, description) - the settings card renders its toggles from\n#: this list, so adding a kind here is the whole change.\nKINDS: Tuple[Tuple[str, str, str], ...] = (\n    (\"escalation\", \"Handoffs\",\n     \"The AI or a workflow handed a chat to your team.\"),\n    (\"approval\", \"Approvals\",\n     \"An AI action is waiting for your 1 / 0.\"),\n    (\"delivery\", \"Failed deliveries\",\n     \"A message or COD confirmation could not be delivered.\"),\n    (\"workflow\", \"Workflow problems\", \"A workflow run failed.\"),\n    (\"knowledge\", \"Knowledge\", \"A document import or re-fetch failed.\"),\n    (\"system\", \"System\", \"Configuration problems and test notifications.\"),\n    (\"insights\", \"Business insights\",\n     \"Weekly summary of problems the detector flagged.\"),\n)\nKIND_KEYS = tuple(k for k, _l, _d in KINDS)\nSEVERITIES: Tuple[str, ...] = (\"normal\", \"high\")\n\n#: Global kill switch for email (in-app alerts keep their own switch).\nEMAIL_ENABLED = os.environ.get(\n    \"OF_NOTIFY_EMAIL\", \"1\").strip().lower() not in (\"0\", \"false\", \"no\", \"off\")\n#: OF_NOTIFY_EMAIL_SYNC=1 sends on the request thread (tests, debugging).\nEMAIL_SYNC = os.environ.get(\n    \"OF_NOTIFY_EMAIL_SYNC\", \"0\").strip().lower() in (\"1\", \"true\", \"yes\", \"on\")\n#: Optional absolute base for links inside emails (e.g. https://app.example.com).\nPORTAL_BASE_URL = os.environ.get(\"OF_PORTAL_BASE_URL\", \"\").strip().rstrip(\"/\")\nLIST_LIMIT = 50\nMAX_TITLE = 200\nMAX_DETAIL = 500\n\n_DDL_READY = False\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_notifications (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  kind TEXT NOT NULL,\n  severity TEXT NOT NULL DEFAULT 'normal',\n  title TEXT NOT NULL,\n  detail TEXT NOT NULL DEFAULT '',\n  conversation_id BIGINT,\n  alert_id BIGINT,\n  email_to TEXT NOT NULL DEFAULT '',\n  email_status TEXT NOT NULL DEFAULT 'off',\n  email_error TEXT NOT NULL DEFAULT '',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_notifications_client\n  ON portal_notifications (client_id, id DESC);\nCREATE TABLE IF NOT EXISTS portal_notify_settings (\n  client_id BIGINT PRIMARY KEY,\n  email_enabled BOOLEAN NOT NULL DEFAULT FALSE,\n  email_to TEXT NOT NULL DEFAULT '',\n  min_severity TEXT NOT NULL DEFAULT 'normal',\n  kinds JSONB NOT NULL DEFAULT '{}'::jsonb,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\n# ---------------------------------------------------------------------------\n# settings\n# ---------------------------------------------------------------------------\n\ndef default_settings() -> Dict[str, Any]:\n    return {\"email_enabled\": False, \"email_to\": \"\", \"min_severity\": \"normal\",\n            \"kinds\": {k: True for k in KIND_KEYS}}\n\n\ndef _shape_settings(row: Optional[Dict[str, Any]]) -> Dict[str, Any]:\n    out = default_settings()\n    if not row:\n        return out\n    out[\"email_enabled\"] = bool(row.get(\"email_enabled\"))\n    out[\"email_to\"] = str(row.get(\"email_to\") or \"\").strip()[:200]\n    severity = str(row.get(\"min_severity\") or \"normal\")\n    out[\"min_severity\"] = severity if severity in SEVERITIES else \"normal\"\n    raw = row.get(\"kinds\")\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw)\n        except Exception:\n            raw = {}\n    if isinstance(raw, dict):\n        for key in KIND_KEYS:\n            if key in raw:\n                out[\"kinds\"][key] = bool(raw.get(key))\n    return out\n\n\ndef load_settings(cur, client_id: int) -> Dict[str, Any]:\n    cur.execute(\n        \"SELECT email_enabled, email_to, min_severity, kinds FROM \"\n        + portal_db._q(SETTINGS_TABLE) + \" WHERE client_id = %s\",\n        (client_id,),\n    )\n    rows = portal_db.rows(cur)\n    return _shape_settings(rows[0] if rows else None)\n\n\ndef save_settings(cur, client_id: int, settings: Dict[str, Any]) -> None:\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(SETTINGS_TABLE) +\n        \" (client_id, email_enabled, email_to, min_severity, kinds,\"\n        \" updated_at) VALUES (%s, %s, %s, %s, CAST(%s AS JSONB), NOW())\"\n        \" ON CONFLICT (client_id) DO UPDATE SET\"\n        \" email_enabled = EXCLUDED.email_enabled,\"\n        \" email_to = EXCLUDED.email_to,\"\n        \" min_severity = EXCLUDED.min_severity,\"\n        \" kinds = EXCLUDED.kinds, updated_at = NOW()\",\n        (client_id, bool(settings.get(\"email_enabled\")),\n         str(settings.get(\"email_to\") or \"\")[:200],\n         str(settings.get(\"min_severity\") or \"normal\"),\n         json.dumps(settings.get(\"kinds\") or {})),\n    )\n\n\ndef validate_settings(payload: Any, current: Dict[str, Any]) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:\n    \"\"\"Merge a PUT payload onto the current settings; (settings, error).\"\"\"\n    if not isinstance(payload, dict):\n        return None, \"A JSON object is required.\"\n    out = dict(current)\n    out[\"kinds\"] = dict(current.get(\"kinds\") or {})\n    if \"email_enabled\" in payload:\n        if not isinstance(payload.get(\"email_enabled\"), bool):\n            return None, \"email_enabled must be true or false.\"\n        out[\"email_enabled\"] = payload[\"email_enabled\"]\n    if \"email_to\" in payload:\n        email = str(payload.get(\"email_to\") or \"\").strip()\n        if email and (\"@\" not in email or \" \" in email or len(email) > 200):\n            return None, \"email_to must be a valid e-mail address.\"\n        out[\"email_to\"] = email\n    if \"min_severity\" in payload:\n        severity = str(payload.get(\"min_severity\") or \"\").strip().lower()\n        if severity not in SEVERITIES:\n            return None, \"min_severity must be normal or high.\"\n        out[\"min_severity\"] = severity\n    if \"kinds\" in payload:\n        kinds = payload.get(\"kinds\")\n        if not isinstance(kinds, dict):\n            return None, \"kinds must be an object of booleans.\"\n        for key, value in kinds.items():\n            if key not in KIND_KEYS:\n                return None, \"Unknown notification kind: \" + str(key)[:40]\n            if not isinstance(value, bool):\n                return None, \"kinds.\" + key + \" must be true or false.\"\n            out[\"kinds\"][key] = value\n    return out, None\n\n\ndef _rank(severity: str) -> int:\n    return SEVERITIES.index(severity) if severity in SEVERITIES else 0\n\n\ndef email_configured() -> bool:\n    \"\"\"Is the platform able to send mail at all (admin config or env)?\"\"\"\n    try:\n        import platform_settings\n\n        config = platform_settings.smtp_config()\n        if config.get(\"provider\") == \"brevo\":\n            return bool(config.get(\"brevo_api_key\"))\n        return bool(config.get(\"smtp_host\"))\n    except Exception:\n        return False\n\n\ndef owner_email(cur, client_id: int) -> str:\n    \"\"\"Fallback recipient: the workspace's first user (the owner).\"\"\"\n    try:\n        cur.execute(\n            \"SELECT email FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n            \" WHERE client_id = %s ORDER BY id LIMIT 1\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n        return str((rows[0] if rows else {}).get(\"email\") or \"\").strip()\n    except Exception:\n        return \"\"\n\n\n# ---------------------------------------------------------------------------\n# email delivery\n# ---------------------------------------------------------------------------\n\ndef _deliver(to_address: str, subject: str, body: str) -> Tuple[bool, str]:\n    try:\n        import admin_providers\n\n        return admin_providers._deliver_email(to_address, subject, body)\n    except Exception as error:\n        return False, str(error) or \"delivery failed\"\n\n\ndef _mark_email(ledger_id: int, status: str, error: str = \"\") -> None:\n    \"\"\"Record the delivery result (own connection; retried briefly so a\n    ledger row written on a caller's still-open transaction is found).\"\"\"\n    import time\n\n    for attempt in range(3):\n        try:\n            conn = portal_db._conn()\n            try:\n                with conn.cursor() as cur:\n                    cur.execute(\n                        \"UPDATE \" + portal_db._q(LEDGER_TABLE) +\n                        \" SET email_status = %s, email_error = %s\"\n                        \" WHERE id = %s\",\n                        (status, str(error or \"\")[:300], int(ledger_id)),\n                    )\n                    updated = cur.rowcount\n                conn.commit()\n            finally:\n                conn.close()\n            if updated:\n                return\n        except Exception as problem:\n            logger.warning(\"notification ledger update failed: %s\", problem)\n        time.sleep(2)\n\n\ndef _email_body(title: str, detail: str, conversation_id: Optional[int]) -> str:\n    lines = [title, \"\"]\n    if detail:\n        lines += [detail, \"\"]\n    if conversation_id:\n        path = \"/dashboard/conversations/\" + str(int(conversation_id))\n        lines.append(\"Open the conversation: \" + (PORTAL_BASE_URL + path\n                                                  if PORTAL_BASE_URL else path))\n        lines.append(\"\")\n    lines.append(\"- OmniFlow\")\n    return \"\\n\".join(lines)\n\n\ndef _send(to_address: str, subject: str, body: str, ledger_id: int,\n          sync: bool) -> Tuple[str, str]:\n    \"\"\"Send now (sync) or on a daemon thread; returns (status, error).\"\"\"\n    if sync:\n        ok, detail = _deliver(to_address, subject, body)\n        status = \"sent\" if ok else \"failed\"\n        _mark_email(ledger_id, status, \"\" if ok else detail)\n        return status, (\"\" if ok else detail)\n\n    def _worker() -> None:\n        ok, detail = _deliver(to_address, subject, body)\n        _mark_email(ledger_id, \"sent\" if ok else \"failed\",\n                    \"\" if ok else detail)\n\n    try:\n        threading.Thread(target=_worker, daemon=True,\n                         name=\"of-notify-\" + str(ledger_id)).start()\n        return \"queued\", \"\"\n    except Exception as error:\n        return \"failed\", str(error)\n\n\n# ---------------------------------------------------------------------------\n# the service\n# ---------------------------------------------------------------------------\n\ndef notify(client_id: int, kind: str, title: str, detail: str = \"\",\n           severity: str = \"normal\", dedupe_key: str = \"\",\n           conversation_id: Optional[int] = None, in_app: bool = True,\n           alert_id: Optional[int] = None,\n           email_sync: bool = False) -> Dict[str, Any]:\n    \"\"\"Fan one notification out to the bell, email and the ledger. Never\n    raises; the returned dict says what happened\n    ({in_app, email, email_to, ledger_id, error}).\"\"\"\n    result: Dict[str, Any] = {\"in_app\": alert_id, \"email\": \"off\",\n                              \"email_to\": \"\", \"ledger_id\": None, \"error\": \"\"}\n    kind = str(kind or \"system\")\n    if kind not in KIND_KEYS:\n        kind = \"system\"\n    severity = str(severity or \"normal\")\n    if severity not in SEVERITIES:\n        severity = \"normal\"\n    title = str(title or \"\").strip()[:MAX_TITLE] or \"Notification\"\n    detail = str(detail or \"\").strip()[:MAX_DETAIL]\n    conv = int(conversation_id) if conversation_id else None\n    conn = None\n    try:\n        conn = portal_db._conn()\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = load_settings(cur, client_id)\n            deduped = False\n            if in_app:\n                import portal_alerts\n\n                if portal_alerts.alerts_on(cur, client_id):\n                    new_id = portal_alerts.raise_alert(\n                        cur, client_id, kind, title, detail, severity,\n                        dedupe_key=dedupe_key)\n                    result[\"in_app\"] = new_id\n                    deduped = bool(dedupe_key) and new_id is None\n                else:\n                    result[\"in_app\"] = None\n            email_status, email_to = \"off\", \"\"\n            wants = (EMAIL_ENABLED and settings[\"email_enabled\"]\n                     and settings[\"kinds\"].get(kind, True)\n                     and _rank(severity) >= _rank(settings[\"min_severity\"]))\n            if wants:\n                if deduped:\n                    email_status = \"deduped\"\n                else:\n                    email_to = settings[\"email_to\"] or owner_email(cur, client_id)\n                    email_status = \"queued\" if email_to else \"no_recipient\"\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(LEDGER_TABLE) +\n                \" (client_id, kind, severity, title, detail, conversation_id,\"\n                \" alert_id, email_to, email_status)\"\n                \" VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s) RETURNING id\",\n                (client_id, kind, severity, title, detail, conv,\n                 result[\"in_app\"], email_to, email_status),\n            )\n            rows = portal_db.rows(cur)\n            ledger_id = int((rows[0] if rows else {}).get(\"id\") or 0)\n        conn.commit()\n        conn.close()\n        conn = None\n        result.update({\"ledger_id\": ledger_id or None, \"email\": email_status,\n                       \"email_to\": email_to})\n        if email_status == \"queued\" and ledger_id:\n            status, error = _send(\n                email_to, \"[OmniFlow] \" + title, _email_body(title, detail, conv),\n                ledger_id, sync=bool(email_sync or EMAIL_SYNC))\n            result[\"email\"] = status\n            result[\"error\"] = error\n    except Exception as error:\n        logger.warning(\"notify failed (%s): %s\", kind, error)\n        result[\"error\"] = str(error)[:200]\n    finally:\n        if conn is not None:\n            try:\n                conn.close()\n            except Exception:\n                pass\n    return result\n\n\ndef list_recent(cur, client_id: int, limit: int = LIST_LIMIT) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT id, kind, severity, title, detail, conversation_id, alert_id,\"\n        \" email_to, email_status, email_error, created_at FROM \"\n        + portal_db._q(LEDGER_TABLE) +\n        \" WHERE client_id = %s ORDER BY id DESC LIMIT %s\",\n        (client_id, max(1, min(200, int(limit or LIST_LIMIT)))),\n    )\n    return [_public(r) for r in portal_db.rows(cur)]\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if value is None or value == \"\":\n        return None\n    return value.isoformat() if hasattr(value, \"isoformat\") else str(value)\n\n\ndef _public(row: Dict[str, Any]) -> Dict[str, Any]:\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"kind\": str(row.get(\"kind\") or \"\"),\n        \"severity\": str(row.get(\"severity\") or \"normal\"),\n        \"title\": str(row.get(\"title\") or \"\"),\n        \"detail\": str(row.get(\"detail\") or \"\"),\n        \"conversation_id\": (int(row[\"conversation_id\"])\n                            if row.get(\"conversation_id\") else None),\n        \"alert_id\": int(row[\"alert_id\"]) if row.get(\"alert_id\") else None,\n        \"email_to\": _mask(str(row.get(\"email_to\") or \"\")),\n        \"email_status\": str(row.get(\"email_status\") or \"off\"),\n        \"email_error\": str(row.get(\"email_error\") or \"\"),\n        \"created_at\": _iso(row.get(\"created_at\")),\n    }\n\n\ndef _mask(email: str) -> str:\n    if \"@\" not in email:\n        return email\n    name, domain = email.split(\"@\", 1)\n    return (name[:2] + \"\\u2026\" if len(name) > 2 else name) + \"@\" + domain\n\n\ndef kinds_public() -> List[Dict[str, str]]:\n    return [{\"key\": k, \"label\": l, \"description\": d} for k, l, d in KINDS]\n\n\n# ---------------------------------------------------------------------------\n# HTTP\n# ---------------------------------------------------------------------------\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _human_or_error():\n    principal, error = _principal_or_error()\n    if error:\n        return None, error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return None, forbidden\n    return principal, None\n\n\ndef _bad(message: str, code: str = \"bad_request\", status: int = 400):\n    return jsonify({\"error\": {\"code\": code, \"message\": message}}), status\n\n\n@bp.get(\"/notifications\")\ndef get_notifications():\n    \"\"\"Recent notifications + this tenant's settings + the kind registry.\"\"\"\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    try:\n        limit = int(request.args.get(\"limit\") or LIST_LIMIT)\n    except Exception:\n        limit = LIST_LIMIT\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            items = list_recent(cur, client_id, limit)\n            settings = load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"items\": items, \"settings\": settings,\n                    \"kinds\": kinds_public(), \"severities\": list(SEVERITIES),\n                    \"email_configured\": email_configured()}), 200\n\n\n@bp.get(\"/notifications/settings\")\ndef get_settings():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            settings = load_settings(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"settings\": settings, \"kinds\": kinds_public(),\n                    \"email_configured\": email_configured()}), 200\n\n\n@bp.put(\"/notifications/settings\")\ndef put_settings():\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True)\n    if not isinstance(payload, dict):\n        return _bad(\"A JSON object is required.\")\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            current = load_settings(cur, client_id)\n            merged, problem = validate_settings(payload, current)\n            if problem:\n                conn.rollback()\n                return _bad(problem)\n            save_settings(cur, client_id, merged)\n            portal_db.log_action(\n                cur, client_id, \"notifications.settings\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                \"Email \" + (\"on\" if merged[\"email_enabled\"] else \"off\")\n                + \", min severity \" + merged[\"min_severity\"],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"settings\": merged}), 200\n\n\n@bp.post(\"/notifications/test\")\ndef send_test():\n    \"\"\"Synchronous test through every configured channel - the owner sees\n    exactly what a real notification would do.\"\"\"\n    principal, error = _human_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    result = notify(\n        client_id, \"system\", \"Test notification\",\n        \"Sent from Settings by \" + str(principal.get(\"email\") or \"you\")\n        + \". If you can read this, notifications work.\",\n        severity=\"normal\", email_sync=True)\n    return jsonify({\"ok\": not result.get(\"error\"), \"result\": result}), 200\n");
writeNewRepair("omniflow-backend-patch/connector_api.py", "materialize_weekly_problems", false,
    "\"\"\"\nOmniFlow Control Plane \u2014 CONNECTOR endpoints (shared channel queue).\n\nYe endpoints customer ke apne device (home laptop) par chalne wale connector\nke liye hain \u2014 server par WhatsApp session KABHI nahi chalta. Instagram\ncommands use the same queue and a server-side Meta Graph dispatch adapter.\nAuth: X-Omniflow-Key header = OMNIFLOW_SERVICE_KEY ya\nOMNIFLOW_ADMIN_API_KEY (wahi proven pattern jo admin endpoints use karte hain).\n\nConnector ka tenant resolve hota hai (pehla match jeeta):\n  1. Request body/query me explicit `client_id`\n  2. Backend env OMNIFLOW_CONNECTOR_USER_EMAIL -> platform_users lookup\n\nEndpoints:\n  POST /api/v1/connector/whatsapp/status          {state, phone?, account_name?, client_id?}\n  GET  /api/v1/connector/whatsapp/commands        ?limit=20  (pending, oldest first)\n  POST /api/v1/connector/whatsapp/commands/ack    {command_id, ok, note?, client_id?}\n  GET  /api/v1/connector/bot                      (tenant ka agent config)\n  POST /api/v1/connector/whatsapp/messages        {messages:[{from, body, name?, direction?}]}\n                                                  -> conversation upsert + message store\n\"\"\"\n\nimport logging\nimport os\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_cod\nimport portal_contacts\nimport portal_sequences\n\n\nlogger = logging.getLogger(\"omniflow.connector-api\")\n\nbp = Blueprint(\"connector_api\", __name__, url_prefix=\"/api/v1/connector\")\n\nALLOWED_STATES = (\"disconnected\", \"connecting\", \"connected\")\n_TENANT_TTL_SECONDS = 300.0\n_tenant_lock = threading.Lock()\n_tenant_cache: Dict[str, Any] = {\"email\": None, \"value\": None, \"at\": 0.0}\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _resolve_tenant(explicit_client_id: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"client_id (explicit > env email lookup). None = not configurable.\"\"\"\n    if isinstance(explicit_client_id, str) and explicit_client_id.strip().isdigit():\n        explicit_client_id = int(explicit_client_id.strip())\n    if isinstance(explicit_client_id, int) and not isinstance(explicit_client_id, bool) \\\n            and explicit_client_id > 0:\n        return {\"client_id\": explicit_client_id, \"user_id\": None, \"source\": \"request\"}\n\n    email = os.environ.get(\"OMNIFLOW_CONNECTOR_USER_EMAIL\", \"\").strip().lower()\n    if not email:\n        return None\n\n    now = time.time()\n    with _tenant_lock:\n        cached = (\n            _tenant_cache[\"email\"] == email\n            and _tenant_cache[\"value\"] is not None\n            and (now - float(_tenant_cache[\"at\"])) < _TENANT_TTL_SECONDS\n        )\n        if cached:\n            return dict(_tenant_cache[\"value\"])\n\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n                \" WHERE \" + portal_db._q(portal_db.USER_EMAIL_COL) + \" = %s LIMIT 1\",\n                (email,),\n            )\n            found = portal_db.rows(cur)\n    finally:\n        conn.close()\n\n    if not found:\n        return None\n    tenant = {\"client_id\": found[0][\"client_id\"], \"user_id\": found[0][\"id\"], \"source\": \"env\"}\n    with _tenant_lock:\n        _tenant_cache.update({\"email\": email, \"value\": tenant, \"at\": now})\n    return dict(tenant)\n\n\ndef _tenant_or_error(explicit_client_id: Any):\n    try:\n        tenant = _resolve_tenant(explicit_client_id)\n    except Exception as error:\n        return None, (jsonify(portal_db.portal_unavailable(error, \"tenant resolve\")[0]), 503)\n    if tenant is None:\n        return None, (jsonify({\"error\": {\n            \"code\": \"connector_not_configured\",\n            \"message\": (\n                \"Connector tenant resolve nahi hua: body/query me client_id bhejein \"\n                \"ya backend par OMNIFLOW_CONNECTOR_USER_EMAIL set karein.\"\n            ),\n        }}), 503)\n    return tenant, None\n\n\ndef _json_body() -> Dict[str, Any]:\n    payload = request.get_json(silent=True)\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _query_int(name: str, default: int, low: int, high: int) -> int:\n    raw = request.args.get(name, \"\")\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        return default\n    return max(low, min(high, value))\n\n\n@bp.post(\"/whatsapp/status\")\ndef report_status():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    state = payload.get(\"state\")\n    if state not in ALLOWED_STATES:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"state disconnected|connecting|connected hon.\"}}), 400\n    phone = payload.get(\"phone\")\n    phone = phone.strip() if isinstance(phone, str) else None\n    account_name = payload.get(\"account_name\")\n    account_name = account_name.strip() if isinstance(account_name, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.STATUS_TABLE) +\n                    \" (client_id, state, phone, account_name, last_seen_at,\"\n                    \" reported_by, updated_at) \"\n                    \"VALUES (%s, %s, %s, %s, NOW(), %s, NOW()) \"\n                    \"ON CONFLICT (client_id) DO UPDATE SET \"\n                    \" state = EXCLUDED.state,\"\n                    \" phone = EXCLUDED.phone,\"\n                    \" account_name = EXCLUDED.account_name,\"\n                    \" last_seen_at = EXCLUDED.last_seen_at,\"\n                    \" reported_by = EXCLUDED.reported_by,\"\n                    \" updated_at = NOW()\",\n                    (tenant[\"client_id\"], state, phone, account_name, tenant[\"user_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"wa status write\")[0]), 503\n\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/whatsapp/commands\")\ndef list_commands():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 20, 1, 50)\n    channel = (args.get(\"channel\") or \"\").strip()\n    if channel and channel not in ALLOWED_CHANNELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"channel whatsapp|telegram|instagram hon.\"}}), 400\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_growth\n\n                    portal_growth.materialize_due_broadcasts(cur, tenant[\"client_id\"], conn)\n                    import portal_digest\n\n                    portal_digest.materialize_due_digest(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    import portal_checkout\n\n                    portal_checkout.materialize_cart_reminders(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    try:\n                        import portal_bi\n                        portal_bi.materialize_weekly_problems(\n                            cur, tenant[\"client_id\"], conn\n                        )\n                    except Exception:\n                        pass\n\n                except Exception:\n                    pass\n                try:\n                    import portal_webhooks\n\n                    portal_webhooks.deliver_pending_webhooks(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_sequences\n\n                    portal_sequences.deliver_due_sequence_steps(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_workflows\n\n                    portal_workflows.run_due_workflows(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_events\n\n                    portal_events.requeue_due_commands(\n                        cur, tenant[\"client_id\"]\n                    )\n                except Exception:\n                    pass\n                cmd_sql = (\n                    \"SELECT id, action, payload, created_at FROM \"\n                    + portal_db._q(portal_db.CMD_TABLE) +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                )\n                cmd_params: list = [tenant[\"client_id\"]]\n                if channel:\n                    cmd_sql += \" AND channel = %s\"\n                    cmd_params.append(channel)\n                cmd_sql += \" ORDER BY id ASC LIMIT %s\"\n                cmd_params.append(limit)\n                cur.execute(cmd_sql, tuple(cmd_params))\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"commands read\")[0]), 503\n\n    commands = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        commands.append({\n            \"id\": row.get(\"id\"),\n            \"action\": row.get(\"action\"),\n            \"payload\": row.get(\"payload\") or {},\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"commands\": commands}), 200\n\n\n@bp.post(\"/whatsapp/commands/ack\")\ndef ack_command():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    command_id = payload.get(\"command_id\")\n    if isinstance(command_id, bool) or not isinstance(command_id, int) or command_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"command_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CMD_TABLE) +\n                    \" SET status = %s, result_note = %s, updated_at = NOW() \"\n                    \"WHERE id = %s AND client_id = %s RETURNING id\",\n                    (\"done\" if ok_flag else \"failed\", note, command_id, tenant[\"client_id\"]),\n                )\n                try:\n                    import portal_events\n\n                    portal_events.on_command_ack(\n                        cur,\n                        tenant[\"client_id\"],\n                        command_id,\n                        ok_flag,\n                        note,\n                        payload.get(\"provider_message_id\"),\n                    )\n                except Exception:\n                    pass\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"command ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Command nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/bot\")\ndef connector_bot_config():\n    tenant, error = _tenant_or_error(request.args.get(\"client_id\"))\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT agent_name, tone, greeting, fallback,\"\n                    \" working_hours_enabled, working_hours_start, working_hours_end,\"\n                    \" human_handoff_enabled, updated_at\"\n                    \" FROM \" + portal_db._q(portal_db.BOT_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (tenant[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"connector bot read\")[0]), 503\n\n    if not found:\n        return jsonify({\n            \"agent_name\": \"OmniFlow Assistant\",\n            \"tone\": \"friendly\",\n            \"greeting\": \"\",\n            \"fallback\": \"\",\n            \"working_hours_enabled\": False,\n            \"working_hours_start\": \"09:00\",\n            \"working_hours_end\": \"18:00\",\n            \"human_handoff_enabled\": False,\n            \"updated_at\": None,\n        }), 200\n\n    row = found[0]\n    updated = row.get(\"updated_at\")\n    if isinstance(updated, datetime) and updated.tzinfo is None:\n        updated = updated.replace(tzinfo=timezone.utc)\n    return jsonify({\n        \"agent_name\": row.get(\"agent_name\") or \"OmniFlow Assistant\",\n        \"tone\": row.get(\"tone\") if row.get(\"tone\") in (\"friendly\", \"professional\", \"concise\") else \"friendly\",\n        \"greeting\": row.get(\"greeting\") or \"\",\n        \"fallback\": row.get(\"fallback\") or \"\",\n        \"working_hours_enabled\": row.get(\"working_hours_enabled\") is True,\n        \"working_hours_start\": row.get(\"working_hours_start\") or \"09:00\",\n        \"working_hours_end\": row.get(\"working_hours_end\") or \"18:00\",\n        \"human_handoff_enabled\": row.get(\"human_handoff_enabled\") is True,\n        \"updated_at\": updated.isoformat() if isinstance(updated, datetime) else None,\n    }), 200\n\n\nMAX_INGEST_MESSAGES = 100\nALLOWED_DIRECTIONS = (\"in\", \"out\")\nALLOWED_CHANNELS = (\"whatsapp\", \"telegram\", \"instagram\")\n\n\n_AWAY_TABLE_READY = False\nAWAY_COOLDOWN_HOURS = 4\n_AWAY_DEFAULTS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"\",\n}\n\n\ndef _ensure_away_table() -> None:\n    global _AWAY_TABLE_READY\n    if _AWAY_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"portal_away_replies\") +\n                \" (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL,\"\n                \" conversation_id BIGINT, contact_id TEXT NOT NULL,\"\n                \" body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\"\n                \" result_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n                \" sent_at TIMESTAMPTZ)\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_away_pending_idx ON \" +\n                portal_db._q(\"portal_away_replies\") +\n                \" (client_id, status, id)\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _AWAY_TABLE_READY = True\n\n\ndef _load_business_hours(cur, client_id):\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n            portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        return _AWAY_DEFAULTS\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    return stored if isinstance(stored, dict) else _AWAY_DEFAULTS\n\n\ndef _away_closed_now(config) -> bool:\n    try:\n        from zoneinfo import ZoneInfo\n\n        days = config.get(\"days\")\n        if not isinstance(days, list) or len(days) != 7:\n            return False\n        now = datetime.now(ZoneInfo(str(config.get(\"timezone\") or \"UTC\")))\n        day = days[(now.weekday() + 1) % 7]\n        if not isinstance(day, dict) or day.get(\"enabled\") is not True:\n            return True\n        current = now.strftime(\"%H:%M\")\n        start = day.get(\"start\")\n        end = day.get(\"end\")\n        if not isinstance(start, str) or not isinstance(end, str):\n            return True\n        return not (start <= current <= end)\n    except Exception:\n        return False\n\n\ndef _maybe_enqueue_away_reply(client_id, conversation_id, contact_id, direction, conn) -> Optional[bool]:\n    \"\"\"Queue one automatic away reply, inside the ingest transaction.\n\n    Fires only for inbound messages while business hours are enabled and\n    currently closed, at most once per conversation per cooldown window.\n    Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if direction != \"in\":\n        return\n    with conn.cursor() as cur:\n        config = _load_business_hours(cur, client_id)\n        message = config.get(\"away_message\")\n        if (\n            config.get(\"enabled\") is not True\n            or not isinstance(message, str)\n            or not message.strip()\n        ):\n            return\n        if not _away_closed_now(config):\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(\"portal_away_replies\") +\n            \" WHERE client_id = %s AND conversation_id = %s\"\n            \" AND created_at > NOW() - INTERVAL '\" +\n            str(AWAY_COOLDOWN_HOURS) + \" hours'\"\n            \" LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        if portal_db.rows(cur):\n            return\n        try:\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, contact_id)\n        except Exception:\n            contact_lang = None\n        if contact_lang == \"ur\":\n            variant = config.get(\"away_message_ur\")\n        elif contact_lang == \"roman\":\n            variant = config.get(\"away_message_roman\")\n        else:\n            variant = None\n        if isinstance(variant, str) and variant.strip():\n            message = variant\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(\"portal_away_replies\") +\n            \" (client_id, conversation_id, contact_id, body)\"\n            \" VALUES (%s, %s, %s, %s)\",\n            (client_id, conversation_id, contact_id, message.strip()),\n        )\n        return True\n\n\n@bp.get(\"/away-replies\")\ndef list_due_away_replies():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 5, 1, 20)\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, contact_id, body, created_at FROM \" +\n                    portal_db._q(\"portal_away_replies\") +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                    \" ORDER BY id ASC LIMIT %s\",\n                    (tenant[\"client_id\"], limit),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away replies read\")[0]), 503\n\n    replies = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        replies.append({\n            \"id\": row.get(\"id\"),\n            \"external_user_id\": row.get(\"contact_id\"),\n            \"body\": row.get(\"body\"),\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"away_replies\": replies}), 200\n\n\n@bp.post(\"/away-replies/ack\")\ndef ack_away_reply():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    away_id = payload.get(\"away_id\")\n    if isinstance(away_id, bool) or not isinstance(away_id, int) or away_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"away_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(\"portal_away_replies\") +\n                    \" SET status = %s, result_note = %s, sent_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s AND status = 'pending' RETURNING id\",\n                    (\"sent\" if ok_flag else \"failed\", note, away_id, tenant[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Away reply nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\nclass MessageValidationError(ValueError):\n    \"\"\"A connector payload failed the shared message contract.\"\"\"\n\n\nclass IngestRateLimited(Exception):\n    \"\"\"The tenant exceeded the shared inbound ingest limit.\"\"\"\n\n\nclass IngestFailure(Exception):\n    \"\"\"Wrap a persistence/automation failure for route-level JSON errors.\"\"\"\n\n    def __init__(self, original: Exception, operation: str):\n        super().__init__(str(original))\n        self.original = original\n        self.operation = operation\n\n\ndef normalize_messages(messages: Any, default_channel: str = \"whatsapp\",\n                        require_nonempty: bool = True):\n    \"\"\"Normalize provider-neutral messages for every channel adapter.\n\n    The returned records are deliberately the same records consumed by the\n    existing conversation, event, automation, compliance and audit engine.\n    Provider adapters may retain ``id``, ``media`` and ``postback`` metadata;\n    the core still uses the normalized ``from/body/name/direction/channel``\n    contract for conversation work.\n    \"\"\"\n    if not isinstance(messages, list) or (require_nonempty and not messages):\n        raise MessageValidationError(\n            \"messages (non-empty list) zaroori hai.\"\n            if require_nonempty else \"messages list zaroori hai.\"\n        )\n    if len(messages) > MAX_INGEST_MESSAGES:\n        raise MessageValidationError(\n            \"Aik request me max \" + str(MAX_INGEST_MESSAGES)\n            + \" messages bhejein.\"\n        )\n\n    normalized = []\n    for item in messages:\n        if not isinstance(item, dict):\n            raise MessageValidationError(\"Har message aik object ho.\")\n        sender = item.get(\"from\")\n        if not isinstance(sender, str) or not sender.strip():\n            raise MessageValidationError(\"Har message me 'from' zaroori hai.\")\n        body = item.get(\"body\")\n        if body is None:\n            body = \"\"\n        elif not isinstance(body, str):\n            body = str(body)\n        try:\n            import portal_interactive\n\n            reply_body = portal_interactive.interactive_body_override(\n                item.get(\"interactive\"), body\n            )\n            if reply_body is not None:\n                body = reply_body\n        except Exception:\n            pass\n        direction = item.get(\"direction\", \"in\")\n        if direction not in ALLOWED_DIRECTIONS:\n            raise MessageValidationError(\"direction in|out hon.\")\n        channel = item.get(\"channel\", default_channel)\n        if channel not in ALLOWED_CHANNELS:\n            raise MessageValidationError(\n                \"channel \" + \"|\".join(ALLOWED_CHANNELS) + \" hon.\"\n            )\n        name = item.get(\"name\")\n        name = name.strip() if isinstance(name, str) else None\n        record = {\n            \"from\": sender.strip(),\n            \"body\": body,\n            \"name\": name,\n            \"direction\": direction,\n            \"channel\": channel,\n        }\n        provider_id = item.get(\"id\")\n        if isinstance(provider_id, (str, int)) and str(provider_id).strip():\n            record[\"id\"] = str(provider_id).strip()\n        # Keep adapter metadata in the event/audit payload without making it\n        # part of the core conversation contract.\n        for key in (\"media\", \"postback\", \"timestamp\", \"provider\"):\n            if key in item and item[key] is not None:\n                record[key] = item[key]\n        normalized.append(record)\n    return normalized\n\n\ndef ingest_messages_for_tenant(tenant: Dict[str, Any], normalized) -> int:\n    \"\"\"Run the existing message engine for any normalized channel.\n\n    Instagram calls this function rather than creating a second conversation\n    or automation pipeline. One-reply, approvals, compliance, sequences,\n    workflows, intelligence and event idempotency all remain in this path.\n    \"\"\"\n    inserted = 0\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_ratelimit\n\n                    if not portal_ratelimit.allow(\n                        cur,\n                        \"ingest:\" + str(tenant[\"client_id\"]),\n                        portal_ratelimit.ingest_limit(),\n                        60,\n                    ):\n                        conn.commit()\n                        raise IngestRateLimited()\n                except IngestRateLimited:\n                    raise\n                except Exception:\n                    pass\n                for item in normalized:\n                    try:\n                        import portal_events\n\n                        if not portal_events.record_inbound(\n                            cur, tenant[\"client_id\"], item\n                        ):\n                            continue\n                    except Exception:\n                        pass\n                    if item[\"channel\"] == \"instagram\":\n                        try:\n                            import portal_identity\n\n                            identity_handle = item[\"from\"]\n                            if identity_handle.startswith(\"ig:\"):\n                                identity_handle = identity_handle[3:]\n                            portal_identity.resolve(\n                                cur,\n                                tenant[\"client_id\"],\n                                \"instagram\",\n                                identity_handle,\n                                item[\"name\"] or \"\",\n                                create=True,\n                                source=\"instagram_webhook\",\n                            )\n                        except Exception:\n                            pass\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" (client_id, channel, contact_id, contact_name,\"\n                        \" status, last_message_preview, last_message_at,\"\n                        \" created_at, updated_at) \"\n                        \"VALUES (%s, %s, %s, %s, 'open', %s, NOW(), NOW(), NOW()) \"\n                        \"ON CONFLICT (client_id, channel, contact_id) DO UPDATE SET \"\n                        \" contact_name = COALESCE(EXCLUDED.contact_name,\"\n                        \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name), \"\n                        \" last_message_preview = EXCLUDED.last_message_preview, \"\n                        \" last_message_at = EXCLUDED.last_message_at, \"\n                        \" updated_at = NOW() \"\n                        \"RETURNING id\",\n                        (tenant[\"client_id\"], item[\"channel\"], item[\"from\"],\n                         item[\"name\"], item[\"body\"]),\n                    )\n                    conv = portal_db.rows(cur)\n                    conversation_id = conv[0][\"id\"] if conv else None\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" (conversation_id, client_id, direction, body,\"\n                        \" sender_name, status, created_at) \"\n                        \"VALUES (%s, %s, %s, %s, %s, %s, NOW())\",\n                        (conversation_id, tenant[\"client_id\"], item[\"direction\"],\n                         item[\"body\"], item[\"name\"],\n                         \"received\" if item[\"direction\"] == \"in\" else \"sent\"),\n                    )\n                    # One-reply law (B2): the first automation that sends a\n                    # customer-visible reply claims the message; the other\n                    # reply hooks stay quiet. Side-effect hooks (language\n                    # detection, compliance, listen, routing, sequences)\n                    # always run.\n                    claimed_by = None\n                    if claimed_by is None:\n                        try:\n                            import portal_approvals\n\n                            if portal_approvals.maybe_decide(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"approvals\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if _maybe_enqueue_away_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"away\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if portal_cod.maybe_cod_flow(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"cod\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_brain\n\n                            if portal_brain.maybe_answer(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                conn,\n                            ):\n                                claimed_by = \"brain\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_kb\n                            import portal_intents\n\n                            import portal_llm\n\n                            with portal_llm.usage_scope(\n                                    \"intent\", tenant[\"client_id\"]):\n                                intent = portal_intents.classify(item[\"body\"])\n                            if portal_kb.maybe_auto_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                intent,\n                                conn,\n                            ):\n                                claimed_by = \"kb\"\n                        except Exception:\n                            pass\n                    if claimed_by:\n                        try:\n                            import portal_events\n\n                            portal_events.note_claim(\n                                cur, tenant[\"client_id\"], item, claimed_by\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_contacts.maybe_detect_language(\n                            tenant[\"client_id\"],\n                            item[\"from\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    if item[\"direction\"] == \"in\":\n                        try:\n                            import portal_compliance\n\n                            portal_compliance.maybe_opt_out(\n                                tenant[\"client_id\"],\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_listen\n\n                            portal_listen.maybe_listen(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_routing\n\n                            portal_routing.maybe_route(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_intelligence\n\n                            portal_intelligence.maybe_analyze(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_approvals\n\n                            portal_approvals.maybe_request(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_sequences.maybe_enroll_new_contact(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_enroll_keyword(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_auto_pause_replies(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_workflows\n\n                        portal_workflows.maybe_trigger_message(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            item[\"direction\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_events\n\n                        portal_events.mark_inbound_done(\n                            cur, tenant[\"client_id\"], item\n                        )\n                    except Exception:\n                        pass\n                    inserted += 1\n            conn.commit()\n        finally:\n            conn.close()\n    except IngestRateLimited:\n        raise\n    except Exception as error:\n        raise IngestFailure(error, \"messages ingest\") from error\n    return inserted\n\n\n@bp.post(\"/whatsapp/messages\")\ndef ingest_whatsapp_messages():\n    \"\"\"Store connector-delivered messages through the shared channel engine.\"\"\"\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n    try:\n        normalized = normalize_messages(\n            payload.get(\"messages\"), default_channel=\"whatsapp\"\n        )\n    except MessageValidationError as error:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": str(error)}}), 400\n\n    try:\n        inserted = ingest_messages_for_tenant(tenant, normalized)\n    except IngestRateLimited:\n        return jsonify({\"error\": {\n            \"code\": \"rate_limited\",\n            \"message\": \"Too many messages; slow down.\",\n        }}), 429\n    except IngestFailure as failure:\n        return jsonify(portal_db.portal_unavailable(\n            failure.original, failure.operation)[0]), 503\n\n    logger.info(\"whatsapp messages ingested client_id=%s count=%s\",\n                tenant[\"client_id\"], inserted)\n    return jsonify({\"ok\": True, \"inserted\": inserted}), 200\n\n");
writeNewRepair("OmniFlow-Control-Plane/connector_api.py", "materialize_weekly_problems", true,
    "\"\"\"\nOmniFlow Control Plane \u2014 CONNECTOR endpoints (shared channel queue).\n\nYe endpoints customer ke apne device (home laptop) par chalne wale connector\nke liye hain \u2014 server par WhatsApp session KABHI nahi chalta. Instagram\ncommands use the same queue and a server-side Meta Graph dispatch adapter.\nAuth: X-Omniflow-Key header = OMNIFLOW_SERVICE_KEY ya\nOMNIFLOW_ADMIN_API_KEY (wahi proven pattern jo admin endpoints use karte hain).\n\nConnector ka tenant resolve hota hai (pehla match jeeta):\n  1. Request body/query me explicit `client_id`\n  2. Backend env OMNIFLOW_CONNECTOR_USER_EMAIL -> platform_users lookup\n\nEndpoints:\n  POST /api/v1/connector/whatsapp/status          {state, phone?, account_name?, client_id?}\n  GET  /api/v1/connector/whatsapp/commands        ?limit=20  (pending, oldest first)\n  POST /api/v1/connector/whatsapp/commands/ack    {command_id, ok, note?, client_id?}\n  GET  /api/v1/connector/bot                      (tenant ka agent config)\n  POST /api/v1/connector/whatsapp/messages        {messages:[{from, body, name?, direction?}]}\n                                                  -> conversation upsert + message store\n\"\"\"\n\nimport logging\nimport os\nimport secrets\nimport threading\nimport time\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nimport portal_cod\nimport portal_contacts\nimport portal_sequences\n\n\nlogger = logging.getLogger(\"omniflow.connector-api\")\n\nbp = Blueprint(\"connector_api\", __name__, url_prefix=\"/api/v1/connector\")\n\nALLOWED_STATES = (\"disconnected\", \"connecting\", \"connected\")\n_TENANT_TTL_SECONDS = 300.0\n_tenant_lock = threading.Lock()\n_tenant_cache: Dict[str, Any] = {\"email\": None, \"value\": None, \"at\": 0.0}\n\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\ndef _resolve_tenant(explicit_client_id: Any) -> Optional[Dict[str, Any]]:\n    \"\"\"client_id (explicit > env email lookup). None = not configurable.\"\"\"\n    if isinstance(explicit_client_id, str) and explicit_client_id.strip().isdigit():\n        explicit_client_id = int(explicit_client_id.strip())\n    if isinstance(explicit_client_id, int) and not isinstance(explicit_client_id, bool) \\\n            and explicit_client_id > 0:\n        return {\"client_id\": explicit_client_id, \"user_id\": None, \"source\": \"request\"}\n\n    email = os.environ.get(\"OMNIFLOW_CONNECTOR_USER_EMAIL\", \"\").strip().lower()\n    if not email:\n        return None\n\n    now = time.time()\n    with _tenant_lock:\n        cached = (\n            _tenant_cache[\"email\"] == email\n            and _tenant_cache[\"value\"] is not None\n            and (now - float(_tenant_cache[\"at\"])) < _TENANT_TTL_SECONDS\n        )\n        if cached:\n            return dict(_tenant_cache[\"value\"])\n\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"SELECT id, client_id FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n                \" WHERE \" + portal_db._q(portal_db.USER_EMAIL_COL) + \" = %s LIMIT 1\",\n                (email,),\n            )\n            found = portal_db.rows(cur)\n    finally:\n        conn.close()\n\n    if not found:\n        return None\n    tenant = {\"client_id\": found[0][\"client_id\"], \"user_id\": found[0][\"id\"], \"source\": \"env\"}\n    with _tenant_lock:\n        _tenant_cache.update({\"email\": email, \"value\": tenant, \"at\": now})\n    return dict(tenant)\n\n\ndef _tenant_or_error(explicit_client_id: Any):\n    try:\n        tenant = _resolve_tenant(explicit_client_id)\n    except Exception as error:\n        return None, (jsonify(portal_db.portal_unavailable(error, \"tenant resolve\")[0]), 503)\n    if tenant is None:\n        return None, (jsonify({\"error\": {\n            \"code\": \"connector_not_configured\",\n            \"message\": (\n                \"Connector tenant resolve nahi hua: body/query me client_id bhejein \"\n                \"ya backend par OMNIFLOW_CONNECTOR_USER_EMAIL set karein.\"\n            ),\n        }}), 503)\n    return tenant, None\n\n\ndef _json_body() -> Dict[str, Any]:\n    payload = request.get_json(silent=True)\n    return payload if isinstance(payload, dict) else {}\n\n\ndef _query_int(name: str, default: int, low: int, high: int) -> int:\n    raw = request.args.get(name, \"\")\n    try:\n        value = int(raw)\n    except (TypeError, ValueError):\n        return default\n    return max(low, min(high, value))\n\n\n@bp.post(\"/whatsapp/status\")\ndef report_status():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    state = payload.get(\"state\")\n    if state not in ALLOWED_STATES:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"state disconnected|connecting|connected hon.\"}}), 400\n    phone = payload.get(\"phone\")\n    phone = phone.strip() if isinstance(phone, str) else None\n    account_name = payload.get(\"account_name\")\n    account_name = account_name.strip() if isinstance(account_name, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"INSERT INTO \" + portal_db._q(portal_db.STATUS_TABLE) +\n                    \" (client_id, state, phone, account_name, last_seen_at,\"\n                    \" reported_by, updated_at) \"\n                    \"VALUES (%s, %s, %s, %s, NOW(), %s, NOW()) \"\n                    \"ON CONFLICT (client_id) DO UPDATE SET \"\n                    \" state = EXCLUDED.state,\"\n                    \" phone = EXCLUDED.phone,\"\n                    \" account_name = EXCLUDED.account_name,\"\n                    \" last_seen_at = EXCLUDED.last_seen_at,\"\n                    \" reported_by = EXCLUDED.reported_by,\"\n                    \" updated_at = NOW()\",\n                    (tenant[\"client_id\"], state, phone, account_name, tenant[\"user_id\"]),\n                )\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"wa status write\")[0]), 503\n\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/whatsapp/commands\")\ndef list_commands():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 20, 1, 50)\n    channel = (args.get(\"channel\") or \"\").strip()\n    if channel and channel not in ALLOWED_CHANNELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"channel whatsapp|telegram|instagram hon.\"}}), 400\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_growth\n\n                    portal_growth.materialize_due_broadcasts(cur, tenant[\"client_id\"], conn)\n                    import portal_digest\n\n                    portal_digest.materialize_due_digest(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    import portal_checkout\n\n                    portal_checkout.materialize_cart_reminders(\n                        cur, tenant[\"client_id\"], conn\n                    )\n\n                    try:\n                        import portal_bi\n                        portal_bi.materialize_weekly_problems(\n                            cur, tenant[\"client_id\"], conn\n                        )\n                    except Exception:\n                        pass\n\n                except Exception:\n                    pass\n                try:\n                    import portal_webhooks\n\n                    portal_webhooks.deliver_pending_webhooks(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_sequences\n\n                    portal_sequences.deliver_due_sequence_steps(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_workflows\n\n                    portal_workflows.run_due_workflows(\n                        cur, tenant[\"client_id\"], conn\n                    )\n                except Exception:\n                    pass\n                try:\n                    import portal_events\n\n                    portal_events.requeue_due_commands(\n                        cur, tenant[\"client_id\"]\n                    )\n                except Exception:\n                    pass\n                cmd_sql = (\n                    \"SELECT id, action, payload, created_at FROM \"\n                    + portal_db._q(portal_db.CMD_TABLE) +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                )\n                cmd_params: list = [tenant[\"client_id\"]]\n                if channel:\n                    cmd_sql += \" AND channel = %s\"\n                    cmd_params.append(channel)\n                cmd_sql += \" ORDER BY id ASC LIMIT %s\"\n                cmd_params.append(limit)\n                cur.execute(cmd_sql, tuple(cmd_params))\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"commands read\")[0]), 503\n\n    commands = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        commands.append({\n            \"id\": row.get(\"id\"),\n            \"action\": row.get(\"action\"),\n            \"payload\": row.get(\"payload\") or {},\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"commands\": commands}), 200\n\n\n@bp.post(\"/whatsapp/commands/ack\")\ndef ack_command():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    command_id = payload.get(\"command_id\")\n    if isinstance(command_id, bool) or not isinstance(command_id, int) or command_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"command_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(portal_db.CMD_TABLE) +\n                    \" SET status = %s, result_note = %s, updated_at = NOW() \"\n                    \"WHERE id = %s AND client_id = %s RETURNING id\",\n                    (\"done\" if ok_flag else \"failed\", note, command_id, tenant[\"client_id\"]),\n                )\n                try:\n                    import portal_events\n\n                    portal_events.on_command_ack(\n                        cur,\n                        tenant[\"client_id\"],\n                        command_id,\n                        ok_flag,\n                        note,\n                        payload.get(\"provider_message_id\"),\n                    )\n                except Exception:\n                    pass\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"command ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Command nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.get(\"/bot\")\ndef connector_bot_config():\n    tenant, error = _tenant_or_error(request.args.get(\"client_id\"))\n    if error:\n        return error\n\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT agent_name, tone, greeting, fallback,\"\n                    \" working_hours_enabled, working_hours_start, working_hours_end,\"\n                    \" human_handoff_enabled, updated_at\"\n                    \" FROM \" + portal_db._q(portal_db.BOT_TABLE) +\n                    \" WHERE client_id = %s\",\n                    (tenant[\"client_id\"],),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"connector bot read\")[0]), 503\n\n    if not found:\n        return jsonify({\n            \"agent_name\": \"OmniFlow Assistant\",\n            \"tone\": \"friendly\",\n            \"greeting\": \"\",\n            \"fallback\": \"\",\n            \"working_hours_enabled\": False,\n            \"working_hours_start\": \"09:00\",\n            \"working_hours_end\": \"18:00\",\n            \"human_handoff_enabled\": False,\n            \"updated_at\": None,\n        }), 200\n\n    row = found[0]\n    updated = row.get(\"updated_at\")\n    if isinstance(updated, datetime) and updated.tzinfo is None:\n        updated = updated.replace(tzinfo=timezone.utc)\n    return jsonify({\n        \"agent_name\": row.get(\"agent_name\") or \"OmniFlow Assistant\",\n        \"tone\": row.get(\"tone\") if row.get(\"tone\") in (\"friendly\", \"professional\", \"concise\") else \"friendly\",\n        \"greeting\": row.get(\"greeting\") or \"\",\n        \"fallback\": row.get(\"fallback\") or \"\",\n        \"working_hours_enabled\": row.get(\"working_hours_enabled\") is True,\n        \"working_hours_start\": row.get(\"working_hours_start\") or \"09:00\",\n        \"working_hours_end\": row.get(\"working_hours_end\") or \"18:00\",\n        \"human_handoff_enabled\": row.get(\"human_handoff_enabled\") is True,\n        \"updated_at\": updated.isoformat() if isinstance(updated, datetime) else None,\n    }), 200\n\n\nMAX_INGEST_MESSAGES = 100\nALLOWED_DIRECTIONS = (\"in\", \"out\")\nALLOWED_CHANNELS = (\"whatsapp\", \"telegram\", \"instagram\")\n\n\n_AWAY_TABLE_READY = False\nAWAY_COOLDOWN_HOURS = 4\n_AWAY_DEFAULTS = {\n    \"enabled\": False,\n    \"timezone\": \"Asia/Karachi\",\n    \"days\": [\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n        {\"enabled\": True, \"start\": \"09:00\", \"end\": \"17:00\"},\n    ],\n    \"away_message\": \"\",\n}\n\n\ndef _ensure_away_table() -> None:\n    global _AWAY_TABLE_READY\n    if _AWAY_TABLE_READY:\n        return\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            cur.execute(\n                \"CREATE TABLE IF NOT EXISTS \" + portal_db._q(\"portal_away_replies\") +\n                \" (id BIGSERIAL PRIMARY KEY, client_id BIGINT NOT NULL,\"\n                \" conversation_id BIGINT, contact_id TEXT NOT NULL,\"\n                \" body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending',\"\n                \" result_note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\"\n                \" sent_at TIMESTAMPTZ)\"\n            )\n            cur.execute(\n                \"CREATE INDEX IF NOT EXISTS portal_away_pending_idx ON \" +\n                portal_db._q(\"portal_away_replies\") +\n                \" (client_id, status, id)\"\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    _AWAY_TABLE_READY = True\n\n\ndef _load_business_hours(cur, client_id):\n    try:\n        cur.execute(\n            \"SELECT settings -> 'business_hours' AS business_hours FROM \" +\n            portal_db._q(\"client_settings\") +\n            \" WHERE client_id = %s\",\n            (client_id,),\n        )\n        rows = portal_db.rows(cur)\n    except Exception:\n        return _AWAY_DEFAULTS\n    stored = rows[0].get(\"business_hours\") if rows and rows[0] else None\n    return stored if isinstance(stored, dict) else _AWAY_DEFAULTS\n\n\ndef _away_closed_now(config) -> bool:\n    try:\n        from zoneinfo import ZoneInfo\n\n        days = config.get(\"days\")\n        if not isinstance(days, list) or len(days) != 7:\n            return False\n        now = datetime.now(ZoneInfo(str(config.get(\"timezone\") or \"UTC\")))\n        day = days[(now.weekday() + 1) % 7]\n        if not isinstance(day, dict) or day.get(\"enabled\") is not True:\n            return True\n        current = now.strftime(\"%H:%M\")\n        start = day.get(\"start\")\n        end = day.get(\"end\")\n        if not isinstance(start, str) or not isinstance(end, str):\n            return True\n        return not (start <= current <= end)\n    except Exception:\n        return False\n\n\ndef _maybe_enqueue_away_reply(client_id, conversation_id, contact_id, direction, conn) -> Optional[bool]:\n    \"\"\"Queue one automatic away reply, inside the ingest transaction.\n\n    Fires only for inbound messages while business hours are enabled and\n    currently closed, at most once per conversation per cooldown window.\n    Never raises into the caller: wrap in try/except there.\n    \"\"\"\n    if direction != \"in\":\n        return\n    with conn.cursor() as cur:\n        config = _load_business_hours(cur, client_id)\n        message = config.get(\"away_message\")\n        if (\n            config.get(\"enabled\") is not True\n            or not isinstance(message, str)\n            or not message.strip()\n        ):\n            return\n        if not _away_closed_now(config):\n            return\n        cur.execute(\n            \"SELECT 1 FROM \" + portal_db._q(\"portal_away_replies\") +\n            \" WHERE client_id = %s AND conversation_id = %s\"\n            \" AND created_at > NOW() - INTERVAL '\" +\n            str(AWAY_COOLDOWN_HOURS) + \" hours'\"\n            \" LIMIT 1\",\n            (client_id, conversation_id),\n        )\n        if portal_db.rows(cur):\n            return\n        try:\n            contact_lang = portal_contacts.stored_language(\n                cur, client_id, contact_id)\n        except Exception:\n            contact_lang = None\n        if contact_lang == \"ur\":\n            variant = config.get(\"away_message_ur\")\n        elif contact_lang == \"roman\":\n            variant = config.get(\"away_message_roman\")\n        else:\n            variant = None\n        if isinstance(variant, str) and variant.strip():\n            message = variant\n        cur.execute(\n            \"INSERT INTO \" + portal_db._q(\"portal_away_replies\") +\n            \" (client_id, conversation_id, contact_id, body)\"\n            \" VALUES (%s, %s, %s, %s)\",\n            (client_id, conversation_id, contact_id, message.strip()),\n        )\n        return True\n\n\n@bp.get(\"/away-replies\")\ndef list_due_away_replies():\n    args = request.args\n    tenant, error = _tenant_or_error(args.get(\"client_id\"))\n    if error:\n        return error\n    limit = _query_int(\"limit\", 5, 1, 20)\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"SELECT id, contact_id, body, created_at FROM \" +\n                    portal_db._q(\"portal_away_replies\") +\n                    \" WHERE client_id = %s AND status = 'pending'\"\n                    \" AND (next_attempt_at IS NULL OR next_attempt_at <= NOW())\"\n                    \" ORDER BY id ASC LIMIT %s\",\n                    (tenant[\"client_id\"], limit),\n                )\n                found = portal_db.rows(cur)\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away replies read\")[0]), 503\n\n    replies = []\n    for row in found:\n        created = row.get(\"created_at\")\n        if isinstance(created, datetime) and created.tzinfo is None:\n            created = created.replace(tzinfo=timezone.utc)\n        replies.append({\n            \"id\": row.get(\"id\"),\n            \"external_user_id\": row.get(\"contact_id\"),\n            \"body\": row.get(\"body\"),\n            \"created_at\": created.isoformat() if isinstance(created, datetime) else None,\n        })\n    return jsonify({\"away_replies\": replies}), 200\n\n\n@bp.post(\"/away-replies/ack\")\ndef ack_away_reply():\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n\n    away_id = payload.get(\"away_id\")\n    if isinstance(away_id, bool) or not isinstance(away_id, int) or away_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"away_id (positive int) zaroori hai.\"}}), 400\n    ok_flag = payload.get(\"ok\") is True\n    note = payload.get(\"note\")\n    note = note if isinstance(note, str) else None\n\n    try:\n        _ensure_away_table()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                cur.execute(\n                    \"UPDATE \" + portal_db._q(\"portal_away_replies\") +\n                    \" SET status = %s, result_note = %s, sent_at = NOW()\"\n                    \" WHERE id = %s AND client_id = %s AND status = 'pending' RETURNING id\",\n                    (\"sent\" if ok_flag else \"failed\", note, away_id, tenant[\"client_id\"]),\n                )\n                updated = portal_db.rows(cur)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        return jsonify(portal_db.portal_unavailable(error, \"away ack\")[0]), 503\n\n    if not updated:\n        return jsonify({\"error\": {\"code\": \"not_found\",\n                                  \"message\": \"Away reply nahi mili.\"}}), 404\n    return jsonify({\"ok\": True}), 200\n\n\nclass MessageValidationError(ValueError):\n    \"\"\"A connector payload failed the shared message contract.\"\"\"\n\n\nclass IngestRateLimited(Exception):\n    \"\"\"The tenant exceeded the shared inbound ingest limit.\"\"\"\n\n\nclass IngestFailure(Exception):\n    \"\"\"Wrap a persistence/automation failure for route-level JSON errors.\"\"\"\n\n    def __init__(self, original: Exception, operation: str):\n        super().__init__(str(original))\n        self.original = original\n        self.operation = operation\n\n\ndef normalize_messages(messages: Any, default_channel: str = \"whatsapp\",\n                        require_nonempty: bool = True):\n    \"\"\"Normalize provider-neutral messages for every channel adapter.\n\n    The returned records are deliberately the same records consumed by the\n    existing conversation, event, automation, compliance and audit engine.\n    Provider adapters may retain ``id``, ``media`` and ``postback`` metadata;\n    the core still uses the normalized ``from/body/name/direction/channel``\n    contract for conversation work.\n    \"\"\"\n    if not isinstance(messages, list) or (require_nonempty and not messages):\n        raise MessageValidationError(\n            \"messages (non-empty list) zaroori hai.\"\n            if require_nonempty else \"messages list zaroori hai.\"\n        )\n    if len(messages) > MAX_INGEST_MESSAGES:\n        raise MessageValidationError(\n            \"Aik request me max \" + str(MAX_INGEST_MESSAGES)\n            + \" messages bhejein.\"\n        )\n\n    normalized = []\n    for item in messages:\n        if not isinstance(item, dict):\n            raise MessageValidationError(\"Har message aik object ho.\")\n        sender = item.get(\"from\")\n        if not isinstance(sender, str) or not sender.strip():\n            raise MessageValidationError(\"Har message me 'from' zaroori hai.\")\n        body = item.get(\"body\")\n        if body is None:\n            body = \"\"\n        elif not isinstance(body, str):\n            body = str(body)\n        try:\n            import portal_interactive\n\n            reply_body = portal_interactive.interactive_body_override(\n                item.get(\"interactive\"), body\n            )\n            if reply_body is not None:\n                body = reply_body\n        except Exception:\n            pass\n        direction = item.get(\"direction\", \"in\")\n        if direction not in ALLOWED_DIRECTIONS:\n            raise MessageValidationError(\"direction in|out hon.\")\n        channel = item.get(\"channel\", default_channel)\n        if channel not in ALLOWED_CHANNELS:\n            raise MessageValidationError(\n                \"channel \" + \"|\".join(ALLOWED_CHANNELS) + \" hon.\"\n            )\n        name = item.get(\"name\")\n        name = name.strip() if isinstance(name, str) else None\n        record = {\n            \"from\": sender.strip(),\n            \"body\": body,\n            \"name\": name,\n            \"direction\": direction,\n            \"channel\": channel,\n        }\n        provider_id = item.get(\"id\")\n        if isinstance(provider_id, (str, int)) and str(provider_id).strip():\n            record[\"id\"] = str(provider_id).strip()\n        # Keep adapter metadata in the event/audit payload without making it\n        # part of the core conversation contract.\n        for key in (\"media\", \"postback\", \"timestamp\", \"provider\"):\n            if key in item and item[key] is not None:\n                record[key] = item[key]\n        normalized.append(record)\n    return normalized\n\n\ndef ingest_messages_for_tenant(tenant: Dict[str, Any], normalized) -> int:\n    \"\"\"Run the existing message engine for any normalized channel.\n\n    Instagram calls this function rather than creating a second conversation\n    or automation pipeline. One-reply, approvals, compliance, sequences,\n    workflows, intelligence and event idempotency all remain in this path.\n    \"\"\"\n    inserted = 0\n    try:\n        portal_db.ensure_tables()\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                try:\n                    import portal_ratelimit\n\n                    if not portal_ratelimit.allow(\n                        cur,\n                        \"ingest:\" + str(tenant[\"client_id\"]),\n                        portal_ratelimit.ingest_limit(),\n                        60,\n                    ):\n                        conn.commit()\n                        raise IngestRateLimited()\n                except IngestRateLimited:\n                    raise\n                except Exception:\n                    pass\n                for item in normalized:\n                    try:\n                        import portal_events\n\n                        if not portal_events.record_inbound(\n                            cur, tenant[\"client_id\"], item\n                        ):\n                            continue\n                    except Exception:\n                        pass\n                    if item[\"channel\"] == \"instagram\":\n                        try:\n                            import portal_identity\n\n                            identity_handle = item[\"from\"]\n                            if identity_handle.startswith(\"ig:\"):\n                                identity_handle = identity_handle[3:]\n                            portal_identity.resolve(\n                                cur,\n                                tenant[\"client_id\"],\n                                \"instagram\",\n                                identity_handle,\n                                item[\"name\"] or \"\",\n                                create=True,\n                                source=\"instagram_webhook\",\n                            )\n                        except Exception:\n                            pass\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.CONV_TABLE) +\n                        \" (client_id, channel, contact_id, contact_name,\"\n                        \" status, last_message_preview, last_message_at,\"\n                        \" created_at, updated_at) \"\n                        \"VALUES (%s, %s, %s, %s, 'open', %s, NOW(), NOW(), NOW()) \"\n                        \"ON CONFLICT (client_id, channel, contact_id) DO UPDATE SET \"\n                        \" contact_name = COALESCE(EXCLUDED.contact_name,\"\n                        \" \" + portal_db._q(portal_db.CONV_TABLE) + \".contact_name), \"\n                        \" last_message_preview = EXCLUDED.last_message_preview, \"\n                        \" last_message_at = EXCLUDED.last_message_at, \"\n                        \" updated_at = NOW() \"\n                        \"RETURNING id\",\n                        (tenant[\"client_id\"], item[\"channel\"], item[\"from\"],\n                         item[\"name\"], item[\"body\"]),\n                    )\n                    conv = portal_db.rows(cur)\n                    conversation_id = conv[0][\"id\"] if conv else None\n                    cur.execute(\n                        \"INSERT INTO \" + portal_db._q(portal_db.MSGS_TABLE) +\n                        \" (conversation_id, client_id, direction, body,\"\n                        \" sender_name, status, created_at) \"\n                        \"VALUES (%s, %s, %s, %s, %s, %s, NOW())\",\n                        (conversation_id, tenant[\"client_id\"], item[\"direction\"],\n                         item[\"body\"], item[\"name\"],\n                         \"received\" if item[\"direction\"] == \"in\" else \"sent\"),\n                    )\n                    # One-reply law (B2): the first automation that sends a\n                    # customer-visible reply claims the message; the other\n                    # reply hooks stay quiet. Side-effect hooks (language\n                    # detection, compliance, listen, routing, sequences)\n                    # always run.\n                    claimed_by = None\n                    if claimed_by is None:\n                        try:\n                            import portal_approvals\n\n                            if portal_approvals.maybe_decide(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"approvals\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if _maybe_enqueue_away_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"away\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            if portal_cod.maybe_cod_flow(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            ):\n                                claimed_by = \"cod\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_brain\n\n                            if portal_brain.maybe_answer(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                conn,\n                            ):\n                                claimed_by = \"brain\"\n                        except Exception:\n                            pass\n                    if claimed_by is None:\n                        try:\n                            import portal_kb\n                            import portal_intents\n\n                            import portal_llm\n\n                            with portal_llm.usage_scope(\n                                    \"intent\", tenant[\"client_id\"]):\n                                intent = portal_intents.classify(item[\"body\"])\n                            if portal_kb.maybe_auto_reply(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                intent,\n                                conn,\n                            ):\n                                claimed_by = \"kb\"\n                        except Exception:\n                            pass\n                    if claimed_by:\n                        try:\n                            import portal_events\n\n                            portal_events.note_claim(\n                                cur, tenant[\"client_id\"], item, claimed_by\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_contacts.maybe_detect_language(\n                            tenant[\"client_id\"],\n                            item[\"from\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    if item[\"direction\"] == \"in\":\n                        try:\n                            import portal_compliance\n\n                            portal_compliance.maybe_opt_out(\n                                tenant[\"client_id\"],\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_listen\n\n                            portal_listen.maybe_listen(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_routing\n\n                            portal_routing.maybe_route(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_intelligence\n\n                            portal_intelligence.maybe_analyze(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                        try:\n                            import portal_approvals\n\n                            portal_approvals.maybe_request(\n                                tenant[\"client_id\"],\n                                conversation_id,\n                                item[\"from\"],\n                                item[\"name\"],\n                                item[\"body\"],\n                                item[\"direction\"],\n                                conn,\n                            )\n                        except Exception:\n                            pass\n                    try:\n                        portal_sequences.maybe_enroll_new_contact(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_enroll_keyword(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        portal_sequences.maybe_auto_pause_replies(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_workflows\n\n                        portal_workflows.maybe_trigger_message(\n                            tenant[\"client_id\"],\n                            conversation_id,\n                            item[\"from\"],\n                            item[\"name\"],\n                            item[\"body\"],\n                            item[\"direction\"],\n                            conn,\n                        )\n                    except Exception:\n                        pass\n                    try:\n                        import portal_events\n\n                        portal_events.mark_inbound_done(\n                            cur, tenant[\"client_id\"], item\n                        )\n                    except Exception:\n                        pass\n                    inserted += 1\n            conn.commit()\n        finally:\n            conn.close()\n    except IngestRateLimited:\n        raise\n    except Exception as error:\n        raise IngestFailure(error, \"messages ingest\") from error\n    return inserted\n\n\n@bp.post(\"/whatsapp/messages\")\ndef ingest_whatsapp_messages():\n    \"\"\"Store connector-delivered messages through the shared channel engine.\"\"\"\n    payload = _json_body()\n    tenant, error = _tenant_or_error(payload.get(\"client_id\"))\n    if error:\n        return error\n    try:\n        normalized = normalize_messages(\n            payload.get(\"messages\"), default_channel=\"whatsapp\"\n        )\n    except MessageValidationError as error:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": str(error)}}), 400\n\n    try:\n        inserted = ingest_messages_for_tenant(tenant, normalized)\n    except IngestRateLimited:\n        return jsonify({\"error\": {\n            \"code\": \"rate_limited\",\n            \"message\": \"Too many messages; slow down.\",\n        }}), 429\n    except IngestFailure as failure:\n        return jsonify(portal_db.portal_unavailable(\n            failure.original, failure.operation)[0]), 503\n\n    logger.info(\"whatsapp messages ingested client_id=%s count=%s\",\n                tenant[\"client_id\"], inserted)\n    return jsonify({\"ok\": True, \"inserted\": inserted}), 200\n\n");
writeNewRepair("tools/cp-testrig/test_weekly_problems.py", "summary(\"weekly_problems\")", false,
    "\"\"\"Tests for weekly problems email (\u00a7207): settings CRUD, body format,\nschedule gates, connector wiring, notify kind, and UI/API surface.\"\"\"\nimport json\nimport os\nimport sys\nfrom unittest import mock\n\n# Avoid rig portal_* stubs shadowing the real Control Plane modules.\n_HERE = os.path.abspath(os.path.dirname(__file__))\n_ROOT = os.path.abspath(os.path.join(_HERE, \"..\", \"..\"))\n_CP = os.path.join(_ROOT, \"omniflow-backend-patch\")\nsys.path = [p for p in sys.path if os.path.abspath(p or \".\") != _HERE]\nsys.path.insert(0, _CP)\nsys.path.append(_HERE)\n\nfrom flask import Flask\n\nimport portal_bi\nimport portal_notify\nfrom test_lib import check, install_db_stub, PrincipalStub, status, summary\n\nROOT = _ROOT\n\napp = Flask(__name__)\napp.register_blueprint(portal_bi.bp)\nclient = app.test_client()\n\nhuman = {\n    \"session_id\": \"s\", \"user_id\": 11, \"client_id\": 1, \"role\": \"owner\",\n    \"email\": \"ahmed@example.com\", \"display_name\": \"Ahmed\", \"via_api_key\": False,\n}\nPrincipalStub(portal_bi, principal=human)\n\n# ensure_human_principal is imported inside the route handlers\ntry:\n    import portal_auth\n\n    def _ok_human(principal):\n        return None\n\n    portal_auth.ensure_human_principal = _ok_human\nexcept Exception:\n    pass\n\n\ndef fresh(script):\n    return install_db_stub(portal_bi, script)\n\n\nprint(\"== notify kind ==\")\n\ncheck(\"insights kind registered\",\n      \"insights\" in portal_notify.KIND_KEYS,\n      portal_notify.KIND_KEYS)\ncheck(\"insights label\",\n      any(k == \"insights\" and \"insight\" in l.lower()\n          for k, l, _d in portal_notify.KINDS),\n      portal_notify.KINDS)\n\nprint(\"== defaults ==\")\n\nd = portal_bi.default_weekly_settings()\ncheck(\"defaults off\", d[\"enabled\"] is False, d)\ncheck(\"default hour in range\", 6 <= d[\"hour\"] <= 21, d)\ncheck(\"default weekday mon-sun\", 1 <= d[\"weekday\"] <= 7, d)\ncheck(\"no last sent\", d[\"last_sent_date\"] is None, d)\n\nprint(\"== load settings ==\")\n\nconn = fresh([[{\"weekly_problems\": {\n    \"enabled\": True, \"hour\": 10, \"weekday\": 5, \"last_sent_date\": \"2026-09-26\"\n}}]])\nout = portal_bi._load_weekly_settings(conn.cur, 1)\ncheck(\"load kept values\",\n      out[\"enabled\"] is True and out[\"hour\"] == 10\n      and out[\"weekday\"] == 5 and out[\"last_sent_date\"] == \"2026-09-26\",\n      out)\n\nconn = fresh([[{\"weekly_problems\": {\n    \"enabled\": True, \"hour\": 99, \"weekday\": 0\n}}]])\nout = portal_bi._load_weekly_settings(conn.cur, 1)\ncheck(\"junk hour ignored\",\n      out[\"hour\"] == portal_bi.default_weekly_settings()[\"hour\"], out)\ncheck(\"junk weekday ignored\",\n      out[\"weekday\"] == portal_bi.default_weekly_settings()[\"weekday\"], out)\n\nconn = fresh([[]])  # no row\nout = portal_bi._load_weekly_settings(conn.cur, 1)\ncheck(\"empty -> defaults\", out[\"enabled\"] is False, out)\n\nconn = fresh([[{\"weekly_problems\": json.dumps({\n    \"enabled\": True, \"hour\": 8, \"weekday\": 2\n})}]])\nout = portal_bi._load_weekly_settings(conn.cur, 1)\ncheck(\"json string stored ok\",\n      out[\"enabled\"] is True and out[\"hour\"] == 8 and out[\"weekday\"] == 2, out)\n\nprint(\"== format body ==\")\n\ntitle, detail, sev = portal_bi._format_weekly_body({\n    \"days\": 7, \"problems\": [], \"problem_counts\": {\"critical\": 0, \"warn\": 0},\n})\ncheck(\"quiet title\", \"quiet\" in title.lower(), title)\ncheck(\"quiet severity normal\", sev == \"normal\", sev)\n\ntitle, detail, sev = portal_bi._format_weekly_body({\n    \"days\": 7,\n    \"problem_counts\": {\"critical\": 2, \"warn\": 1},\n    \"problems\": [\n        {\"severity\": \"critical\", \"title\": \"Knowledge gaps growing\",\n         \"action\": {\"label\": \"Open knowledge\", \"href\": \"/dashboard/knowledge\"}},\n        {\"severity\": \"warn\", \"title\": \"Handoffs spiking\",\n         \"action\": {\"label\": \"Review AI\", \"href\": \"/dashboard/insights\"}},\n        {\"severity\": \"warn\", \"title\": \"Delivery complaints\"},\n    ],\n})\ncheck(\"busy title counts\", \"2\" in title and \"1\" in title, title)\ncheck(\"busy severity high\", sev == \"high\", sev)\ncheck(\"detail has FIX/LOOK\", \"[FIX]\" in detail and \"[LOOK]\" in detail, detail)\ncheck(\"detail capped\", len(detail) <= 500, len(detail))\ncheck(\"title capped\", len(title) <= 200, len(title))\n\nprint(\"== settings API ==\")\n\nconn = fresh([[{\"weekly_problems\": {\n    \"enabled\": False, \"hour\": 9, \"weekday\": 1, \"last_sent_date\": None\n}}]])\nresponse = client.get(\"/api/v1/portal/bi/weekly-problems\")\npayload = response.get_json()\ncheck(\"get 200\", status(response) == 200, status(response))\ncheck(\"get settings object\", isinstance(payload.get(\"settings\"), dict), payload)\ncheck(\"get defaults off\", payload[\"settings\"][\"enabled\"] is False, payload)\ncheck(\"get weekdays 7\",\n      isinstance(payload.get(\"weekdays\"), list)\n      and len(payload[\"weekdays\"]) == 7, payload.get(\"weekdays\"))\n\n# PUT: load current, CREATE TABLE, INSERT, log_action\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": False, \"hour\": 9, \"weekday\": 1}}],\n    [],  # CREATE TABLE\n    1,   # INSERT\n    1,   # log_action\n])\nresponse = client.put(\n    \"/api/v1/portal/bi/weekly-problems\",\n    json={\"settings\": {\"enabled\": True, \"hour\": 10, \"weekday\": 3}},\n)\npayload = response.get_json()\ncheck(\"put 200\", status(response) == 200 and payload.get(\"ok\") is True,\n      (status(response), payload))\ncheck(\"put saved enabled\",\n      isinstance(payload, dict) and payload.get(\"settings\", {}).get(\"enabled\") is True,\n      payload)\ncheck(\"put saved hour\",\n      isinstance(payload, dict) and payload.get(\"settings\", {}).get(\"hour\") == 10,\n      payload)\ncheck(\"put saved weekday\",\n      isinstance(payload, dict) and payload.get(\"settings\", {}).get(\"weekday\") == 3,\n      payload)\n\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": False, \"hour\": 9, \"weekday\": 1}}],\n])\nresponse = client.put(\n    \"/api/v1/portal/bi/weekly-problems\",\n    json={\"settings\": {\"enabled\": True, \"hour\": 3}},\n)\ncheck(\"bad hour 400\", status(response) == 400, status(response))\n\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": False, \"hour\": 9, \"weekday\": 1}}],\n])\nresponse = client.put(\n    \"/api/v1/portal/bi/weekly-problems\",\n    json={\"settings\": {\"enabled\": True, \"weekday\": 9}},\n)\ncheck(\"bad weekday 400\", status(response) == 400, status(response))\n\nprint(\"== materialize gates ==\")\n\nconn = fresh([[{\"weekly_problems\": {\"enabled\": False, \"hour\": 9, \"weekday\": 1}}]])\nn = portal_bi.materialize_weekly_problems(conn.cur, 1, conn)\ncheck(\"off -> 0\", n == 0, n)\n\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": True, \"hour\": 9, \"weekday\": 1,\n                          \"last_sent_date\": None}}],\n    [{\"wd\": 2, \"h\": 10, \"d\": \"2026-09-29\"}],\n])\nn = portal_bi.materialize_weekly_problems(conn.cur, 1, conn)\ncheck(\"wrong weekday -> 0\", n == 0, n)\n\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": True, \"hour\": 12, \"weekday\": 1,\n                          \"last_sent_date\": None}}],\n    [{\"wd\": 1, \"h\": 9, \"d\": \"2026-09-28\"}],\n])\nn = portal_bi.materialize_weekly_problems(conn.cur, 1, conn)\ncheck(\"before hour -> 0\", n == 0, n)\n\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": True, \"hour\": 9, \"weekday\": 1,\n                          \"last_sent_date\": \"2026-09-28\"}}],\n    [{\"wd\": 1, \"h\": 10, \"d\": \"2026-09-28\"}],\n])\nn = portal_bi.materialize_weekly_problems(conn.cur, 1, conn)\ncheck(\"already sent -> 0\", n == 0, n)\n\n# happy path: mock report + notify\nconn = fresh([\n    [{\"weekly_problems\": {\"enabled\": True, \"hour\": 9, \"weekday\": 1,\n                          \"last_sent_date\": None}}],\n    [{\"wd\": 1, \"h\": 10, \"d\": \"2026-09-28\"}],\n    [],  # CREATE TABLE in _save\n    1,   # INSERT\n    1,   # log_action\n])\nfake_report = {\n    \"days\": 7,\n    \"problems\": [\n        {\"severity\": \"critical\", \"title\": \"Gaps\",\n         \"action\": {\"label\": \"Fix KB\", \"href\": \"/x\"}},\n    ],\n    \"problem_counts\": {\"critical\": 1, \"warn\": 0},\n}\nnotifies = []\n\n\ndef fake_notify(client_id, kind, title, detail, **kwargs):\n    notifies.append({\"client_id\": client_id, \"kind\": kind, \"title\": title,\n                     \"detail\": detail, **kwargs})\n    return {\"in_app\": 1, \"email\": \"queued\"}\n\n\nwith mock.patch.object(portal_bi, \"report\", return_value=fake_report):\n    with mock.patch.object(portal_notify, \"notify\", side_effect=fake_notify):\n        n = portal_bi.materialize_weekly_problems(conn.cur, 1, conn)\n\ncheck(\"sent once\", n == 1, n)\ncheck(\"notify called\", len(notifies) == 1, notifies)\nif notifies:\n    check(\"notify kind insights\", notifies[0][\"kind\"] == \"insights\", notifies[0])\n    check(\"dedupe key has date\",\n          \"weekly_problems:2026-09-28\" in str(notifies[0].get(\"dedupe_key\")),\n          notifies[0])\n    check(\"title mentions critical\", \"1\" in notifies[0][\"title\"], notifies[0])\n\nconn = fresh([Exception(\"db down\")])\nn = portal_bi.materialize_weekly_problems(conn.cur, 1, conn)\ncheck(\"fail soft -> 0\", n == 0, n)\n\nprint(\"== send now API ==\")\n\nconn = fresh([\n    1,  # log_action only (report mocked)\n])\nwith mock.patch.object(portal_bi, \"report\", return_value={\n    \"days\": 7, \"problems\": [], \"problem_counts\": {\"critical\": 0, \"warn\": 0},\n}):\n    with mock.patch.object(portal_notify, \"notify\",\n                           return_value={\"in_app\": 9, \"email\": \"queued\"}):\n        response = client.post(\"/api/v1/portal/bi/weekly-problems/send\")\npayload = response.get_json()\ncheck(\"send 200\", status(response) == 200 and payload.get(\"ok\") is True,\n      (status(response), payload))\ncheck(\"send title quiet\",\n      \"quiet\" in str((payload or {}).get(\"title\") or \"\").lower(),\n      payload)\n\nprint(\"== connector wiring ==\")\n\nca = open(os.path.join(_CP, \"connector_api.py\"), encoding=\"utf8\").read()\ncheck(\"connector imports portal_bi\", \"import portal_bi\" in ca, \"missing import\")\ncheck(\"connector calls materialize\",\n      \"materialize_weekly_problems\" in ca, \"missing call\")\n\nprint(\"== UI + BFF surface ==\")\n\ncard = os.path.join(ROOT, \"app\", \"dashboard\", \"(portal)\", \"settings\",\n                    \"WeeklyProblemsCard.tsx\")\ncheck(\"card exists\", os.path.isfile(card), card)\nif os.path.isfile(card):\n    ct = open(card, encoding=\"utf8\").read()\n    check(\"card English title\", \"Weekly problems email\" in ct, \"title\")\n    check(\"card fetch path\",\n          \"/api/omniflow/portal/bi/weekly-problems\" in ct, \"path\")\n    check(\"card send test\", \"Send test now\" in ct, \"send\")\n    check(\"no emoji glyphs\", not any(g in ct for g in \"\\u25b6\\u26a1\\u2709\\u2699\\u2714\"),\n          \"emoji\")\n\nsp = open(os.path.join(ROOT, \"app\", \"dashboard\", \"(portal)\", \"settings\",\n                       \"page.tsx\"), encoding=\"utf8\").read()\ncheck(\"settings imports card\", \"WeeklyProblemsCard\" in sp, \"import\")\n\nroute = os.path.join(ROOT, \"app\", \"api\", \"omniflow\", \"portal\", \"bi\",\n                     \"weekly-problems\", \"route.ts\")\ncheck(\"BFF route\", os.path.isfile(route), route)\nsend_route = os.path.join(ROOT, \"app\", \"api\", \"omniflow\", \"portal\", \"bi\",\n                          \"weekly-problems\", \"send\", \"route.ts\")\ncheck(\"BFF send route\", os.path.isfile(send_route), send_route)\n\nportal_ts = open(os.path.join(ROOT, \"lib\", \"omniflow\", \"portal.ts\"),\n                 encoding=\"utf8\").read()\ncheck(\"portal get helper\", \"getWeeklyProblemsSettings\" in portal_ts, \"get\")\ncheck(\"portal save helper\", \"saveWeeklyProblemsSettings\" in portal_ts, \"save\")\ncheck(\"portal send helper\", \"sendWeeklyProblemsNow\" in portal_ts, \"send\")\n\nsummary(\"weekly_problems\")\n");
writeNewRepair("app/dashboard/(portal)/settings/WeeklyProblemsCard.tsx", "Weekly problems email", false,
    "\"use client\";\n\nimport { useCallback, useEffect, useState } from \"react\";\n\ntype Weekday = { value: number; label: string };\n\nconst FALLBACK_WEEKDAYS: Weekday[] = [\n  { value: 1, label: \"Monday\" },\n  { value: 2, label: \"Tuesday\" },\n  { value: 3, label: \"Wednesday\" },\n  { value: 4, label: \"Thursday\" },\n  { value: 5, label: \"Friday\" },\n  { value: 6, label: \"Saturday\" },\n  { value: 7, label: \"Sunday\" },\n];\n\nexport default function WeeklyProblemsCard() {\n  const [enabled, setEnabled] = useState(false);\n  const [hour, setHour] = useState(9);\n  const [weekday, setWeekday] = useState(1);\n  const [weekdays, setWeekdays] = useState<Weekday[]>(FALLBACK_WEEKDAYS);\n  const [lastSent, setLastSent] = useState<string | null>(null);\n  const [loaded, setLoaded] = useState(false);\n  const [saving, setSaving] = useState(false);\n  const [sending, setSending] = useState(false);\n  const [note, setNote] = useState(\"\");\n\n  const load = useCallback(async () => {\n    try {\n      const response = await fetch(\"/api/omniflow/portal/bi/weekly-problems\", {\n        credentials: \"same-origin\",\n        cache: \"no-store\",\n      });\n      if (!response.ok) return;\n      const payload = (await response.json().catch(() => null)) as {\n        settings?: {\n          enabled?: boolean;\n          hour?: number;\n          weekday?: number;\n          last_sent_date?: string | null;\n        };\n        weekdays?: Weekday[];\n      } | null;\n      const s = payload?.settings;\n      if (!s) return;\n      setEnabled(s.enabled === true);\n      setHour(typeof s.hour === \"number\" ? s.hour : 9);\n      setWeekday(typeof s.weekday === \"number\" ? s.weekday : 1);\n      if (Array.isArray(payload?.weekdays) && payload!.weekdays!.length) {\n        setWeekdays(payload!.weekdays!);\n      }\n      setLastSent(\n        typeof s.last_sent_date === \"string\" && s.last_sent_date\n          ? s.last_sent_date\n          : null\n      );\n    } catch {\n      // Transient network issue.\n    } finally {\n      setLoaded(true);\n    }\n  }, []);\n\n  useEffect(() => {\n    void load();\n  }, [load]);\n\n  async function save() {\n    setSaving(true);\n    setNote(\"\");\n    try {\n      const response = await fetch(\"/api/omniflow/portal/bi/weekly-problems\", {\n        method: \"PUT\",\n        headers: { \"Content-Type\": \"application/json\" },\n        credentials: \"same-origin\",\n        body: JSON.stringify({\n          settings: { enabled, hour, weekday },\n        }),\n      });\n      const payload = (await response.json().catch(() => null)) as {\n        settings?: {\n          enabled?: boolean;\n          hour?: number;\n          weekday?: number;\n          last_sent_date?: string | null;\n        };\n        error?: { message?: string };\n      } | null;\n      if (!response.ok) {\n        setNote(\n          payload?.error?.message ||\n            \"Could not save right now. Try again shortly.\"\n        );\n        return;\n      }\n      if (payload?.settings) {\n        setEnabled(payload.settings.enabled === true);\n        if (typeof payload.settings.hour === \"number\") {\n          setHour(payload.settings.hour);\n        }\n        if (typeof payload.settings.weekday === \"number\") {\n          setWeekday(payload.settings.weekday);\n        }\n      }\n      setNote(\n        enabled\n          ? \"Saved. You will get a weekly problems email on the day and hour you picked (also needs Notifications email on).\"\n          : \"Saved. The weekly problems email is off.\"\n      );\n    } catch {\n      setNote(\"Could not save right now. Try again shortly.\");\n    } finally {\n      setSaving(false);\n    }\n  }\n\n  async function sendNow() {\n    setSending(true);\n    setNote(\"\");\n    try {\n      const response = await fetch(\n        \"/api/omniflow/portal/bi/weekly-problems/send\",\n        {\n          method: \"POST\",\n          credentials: \"same-origin\",\n          headers: { \"Content-Type\": \"application/json\" },\n          body: \"{}\",\n        }\n      );\n      const payload = (await response.json().catch(() => null)) as {\n        title?: string;\n        problem_counts?: { critical?: number; warn?: number };\n        error?: { message?: string };\n      } | null;\n      if (!response.ok) {\n        setNote(\n          payload?.error?.message ||\n            \"Could not send right now. Try again shortly.\"\n        );\n        return;\n      }\n      const crit = payload?.problem_counts?.critical ?? 0;\n      const warn = payload?.problem_counts?.warn ?? 0;\n      setNote(\n        (payload?.title || \"Weekly summary sent.\") +\n          \" (\" +\n          crit +\n          \" critical, \" +\n          warn +\n          \" warn)\"\n      );\n    } catch {\n      setNote(\"Could not send right now. Try again shortly.\");\n    } finally {\n      setSending(false);\n    }\n  }\n\n  return (\n    <div className=\"mt-6 rounded-xl2 border border-line bg-white p-5 shadow-card\">\n      <div className=\"flex flex-wrap items-start justify-between gap-3\">\n        <div>\n          <h2 className=\"text-sm font-semibold text-ink\">Weekly problems email</h2>\n          <p className=\"mt-1 text-xs leading-relaxed text-ink-3\">\n            Once a week, get a short email of what the problem detector flagged\n            (knowledge gaps, handoffs, delivery issues, and more). Off by\n            default. Delivery uses your Notifications email settings.\n          </p>\n        </div>\n        <button\n          type=\"button\"\n          role=\"switch\"\n          aria-checked={enabled}\n          onClick={() => setEnabled((prev) => !prev)}\n          className={\n            \"rounded-lg border px-2.5 py-1 text-[11px] \" +\n            (enabled\n              ? \"border-emerald-400/25 bg-emerald-400/[0.08] text-ok\"\n              : \"border-line bg-soft text-ink-3\")\n          }\n        >\n          {enabled ? \"Email on\" : \"Email off\"}\n        </button>\n      </div>\n\n      {!loaded ? (\n        <p className=\"mt-4 text-xs text-ink-3\">Loading schedule...</p>\n      ) : (\n        <div className=\"mt-4 grid gap-3 sm:grid-cols-2\">\n          <label className=\"block text-xs text-ink-2\">\n            <span className=\"mb-1 block\">Day of week</span>\n            <select\n              value={weekday}\n              onChange={(event) =>\n                setWeekday(Number(event.target.value) || 1)\n              }\n              className=\"w-full rounded-lg border border-line bg-soft px-2.5 py-1.5 text-xs text-ink outline-none focus:border-brand/40\"\n            >\n              {weekdays.map((day) => (\n                <option key={day.value} value={day.value}>\n                  {day.label}\n                </option>\n              ))}\n            </select>\n          </label>\n          <label className=\"block text-xs text-ink-2\">\n            <span className=\"mb-1 block\">Send after (hour, 6-21)</span>\n            <input\n              type=\"number\"\n              min={6}\n              max={21}\n              value={hour}\n              onChange={(event) =>\n                setHour(Number(event.target.value) || 0)\n              }\n              className=\"w-full rounded-lg border border-line bg-soft px-2.5 py-1.5 text-xs text-ink outline-none focus:border-brand/40\"\n            />\n          </label>\n        </div>\n      )}\n\n      {lastSent ? (\n        <p className=\"mt-3 text-[11px] text-ink-3\">\n          Last automatic send: {lastSent}\n        </p>\n      ) : null}\n\n      <div className=\"mt-4 flex flex-wrap items-center gap-2\">\n        <button\n          type=\"button\"\n          disabled={saving || !loaded}\n          onClick={() => void save()}\n          className=\"rounded-xl border border-brand/25 bg-brand-soft px-4 py-2 text-xs font-medium text-brand transition-colors hover:bg-brand-soft disabled:opacity-50\"\n        >\n          {saving ? \"Saving...\" : \"Save\"}\n        </button>\n        <button\n          type=\"button\"\n          disabled={sending || !loaded}\n          onClick={() => void sendNow()}\n          className=\"rounded-xl border border-line bg-white px-3 py-2 text-xs font-medium text-ink-2 transition-colors hover:border-line-2 disabled:opacity-50\"\n        >\n          {sending ? \"Sending...\" : \"Send test now\"}\n        </button>\n        {note ? <span className=\"text-xs text-ink-2\">{note}</span> : null}\n      </div>\n    </div>\n  );\n}\n");
